public class OptionGroup implements Serializable
{
    private static final long serialVersionUID = 1L;

    /** hold the options */
    private Map optionMap = new HashMap();

    /** the name of the selected option */
    private String selected;

    /** specified whether this group is required */
    private boolean required;

    /**
     * Add the specified <code>Option</code> to this group.
     *
     * @param option the option to add to this group
     * @return this option group with the option added
     */
    public OptionGroup addOption(Option option)
    {
        // key   - option name
        // value - the option
        optionMap.put(option.getKey(), option);

        return this;
    }

    /**
     * @return the names of the options in this group as a 
     * <code>Collection</code>
     */
    public Collection getNames()
    {
        // the key set is the collection of names
        return optionMap.keySet();
    }

    /**
     * @return the options in this group as a <code>Collection</code>
     */
    public Collection getOptions()
    {
        // the values are the collection of options
        return optionMap.values();
    }

    /**
     * Set the selected option of this group to <code>name</code>.
     *
     * @param option the option that is selected
     * @throws AlreadySelectedException if an option from this group has 
     * already been selected.
     */
    public void setSelected(Option option) throws AlreadySelectedException
    {
        if (option == null)
        {
            // reset the option previously selected
            selected = null;
            return;
        }

        // if no option has already been selected or the 
        // same option is being reselected then set the
        // selected member variable
        if (selected == null || (option.getOpt() != null && selected.equals(option.getOpt())) || (option.getOpt() == null && selected.equals(option.getLongOpt())))
        {
            selected = option.getOpt() != null ? option.getOpt() : option.getLongOpt();
        }
        else
        {
            throw new AlreadySelectedException(this, option);
        }
    }

    /**
     * @return the selected option name
     */
    public String getSelected()
    {
        return selected;
    }

    /**
     * @param required specifies if this group is required
     */
    public void setRequired(boolean required)
    {
        this.required = required;
    }

    /**
     * Returns whether this option group is required.
     *
     * @return whether this option group is required
     */
    public boolean isRequired()
    {
        return required;
    }

    /**
     * Returns the stringified version of this OptionGroup.
     * 
     * @return the stringified representation of this group
     */
    public String toString()
    {
        StringBuffer buff = new StringBuffer();

        Iterator iter = getOptions().iterator();

        buff.append("[");

        while (iter.hasNext())
        {
            Option option = (Option) iter.next();

            if (option.getOpt() != null)
            {
                buff.append("-");
                buff.append(option.getOpt());
            }
            else
            {
                buff.append("--");
                buff.append(option.getLongOpt());
            }

            buff.append(" ");
            buff.append(option.getDescription());

            if (iter.hasNext())
            {
                buff.append(", ");
            }
        }

        buff.append("]");

        return buff.toString();
    }
}

protected void processProperties(Properties properties)
{
    if (properties == null)
    {
        return;
    }

    for (Enumeration e = properties.propertyNames(); e.hasMoreElements();)
    {
        String option = e.nextElement().toString();

        if (!cmd.hasOption(option))
        {
            Option opt = getOptions().getOption(option);

            // get the value from the properties instance
            String value = properties.getProperty(option);

            if (opt.hasArg())
            {
                if (opt.getValues() == null || opt.getValues().length == 0)
                {
                    try
                    {
                        opt.addValueForProcessing(value);
                    }
                    catch (RuntimeException exp)
                    {
                        // if we cannot add the value don't worry about it
                    }
                }
            }
            else if (!("yes".equalsIgnoreCase(value)
                    || "true".equalsIgnoreCase(value)
                    || "1".equalsIgnoreCase(value)))
            {
                // if the value is not yes, true or 1 then don't add the
                // option to the CommandLine
                continue; // Changed from break to continue
            }

            cmd.addOption(opt);
        }
    }
}

    // process each flattened token
    while (iterator.hasNext())
    {
        String t = (String) iterator.next();

        // the value is the double-dash
        if ("--".equals(t))
        {
            eatTheRest = true;
        }

        // the value is a single dash
        else if ("-".equals(t))
        {
            if (stopAtNonOption)
            {
                eatTheRest = true;
            }
            else
            {
                cmd.addArg(t);
            }
        }

        // the value is an option
        else if (t.startsWith("-"))
        {
            if (stopAtNonOption && !getOptions().hasOption(t))
            {
                eatTheRest = true;
                cmd.addArg(t);
            }
            else
            {
                processOption(t, iterator);
            }
        }

        // the value is an argument
        else
        {
            cmd.addArg(t);

            if (stopAtNonOption)
            {
                eatTheRest = true;
            }
        }

        // eat the remaining tokens
        if (eatTheRest)
        {
            while (iterator.hasNext())
            {
                String str = (String) iterator.next();

                // ensure only one double-dash is added
                if (!"--".equals(str))
                {
                    cmd.addArg(str);
                }
            }
        }
    }

    processProperties(properties); // Moved this line to after the while loop
    checkRequiredOptions();

    return cmd;
}

class Util
{
    /**
     * Remove the hyphens from the begining of <code>str</code> and
     * return the new String.
     *
     * @param str The string from which the hyphens should be removed.
     *
     * @return the new String.
     */
    static String stripLeadingHyphens(String str)
    {
        if (str == null)
        {
            return null;
        }
        if (str.startsWith("--"))
        {
            return str.substring(2, str.length());
        }
        else if (str.startsWith("-"))
        {
            return str.substring(1, str.length());
        }

        return str;
    }

    /**
     * Remove the leading and trailing quotes from <code>str</code>.
     * E.g. if str is '"one two"', then 'one two' is returned.
     *
     * @param str The string from which the leading and trailing quotes
     * should be removed.
     *
     * @return The string without the leading and trailing quotes.
     */
    static String stripLeadingAndTrailingQuotes(String str)
    {
        if (str.startsWith("\""))
        {
            str = str.substring(1, str.length());
        }
        int length = str.length();
        if (str.endsWith("\""))
        {
            str = str.substring(0, length - 1);
        }

        return str;
    }
}

public CommandLine parse(Options options, String[] arguments, Properties properties, boolean stopAtNonOption) throws ParseException
{
    this.options = options;
    this.stopAtNonOption = stopAtNonOption;
    skipParsing = false;
    currentOption = null;
    expectedOpts = new ArrayList(options.getRequiredOptions());

    // clear the data from the groups
    for (Iterator it = options.getOptionGroups().iterator(); it.hasNext();)
    {
        OptionGroup group = (OptionGroup) it.next();
        group.setSelected(null);
    }

    cmd = new CommandLine();

    if (arguments != null)
    {
        for (int i = 0; i < arguments.length; i++)
        {
            handleToken(arguments[i]);
        }
    }

    // check the arguments of the last option
    checkRequiredArgs();

    // add the default options
    handleProperties(properties);

    checkRequiredOptions();

    return cmd;
}

private void handleProperties(Properties properties) throws ParseException
{
    if (properties == null)
    {
        return;
    }

    for (Enumeration e = properties.propertyNames(); e.hasMoreElements();)
    {
        String option = e.nextElement().toString();

        if (!cmd.hasOption(option))
        {
            Option opt = options.getOption(option);

            // if the option is part of a group, check if another option of the group has been selected

            // get the value from the properties
            String value = properties.getProperty(option);

            if (opt.hasArg())
            {
                if (opt.getValues() == null || opt.getValues().length == 0)
                {
                    opt.addValueForProcessing(value);
                }
            }
            else if (!("yes".equalsIgnoreCase(value)
                    || "true".equalsIgnoreCase(value)
                    || "1".equalsIgnoreCase(value)))
            {
                // if the value is not yes, true or 1 then don't add the option to the CommandLine
                continue;
            }

            handleOption(opt);
            currentOption = null;
        }
    }
}

