public void setPrototypeBasedOn(ObjectType baseType) {
  // This is a bit weird. We need to successfully handle these
  // two cases:
  // Foo.prototype = new Bar();
  // and
  // Foo.prototype = {baz: 3};
  // In the first case, we do not want new properties to get
  // added to Bar. In the second case, we do want new properties
  // to get added to the type of the anonymous object.
  //
  // We handle this by breaking it into two cases:
  //
  // In the first case, we create a new PrototypeObjectType and set
  // its implicit prototype to the type being assigned. This ensures
  // that Bar will not get any properties of Foo.prototype, but properties
  // later assigned to Bar will get inherited properly.
  //
  // In the second case, we just use the anonymous object as the prototype.
  if (baseType.hasReferenceName() ||
      baseType.isUnknownType() ||
      isNativeObjectType() ||
      baseType.isFunctionPrototypeType() ||
      !(baseType instanceof PrototypeObjectType)) {

    baseType = new PrototypeObjectType(
        registry, this.getReferenceName() + ".prototype", baseType);
  }
  setPrototype((PrototypeObjectType) baseType);
}

public boolean setPrototype(PrototypeObjectType prototype) {
  if (prototype == null) {
    return false;
  }
  // getInstanceType fails if the function is not a constructor
  if (isConstructor() && prototype == getInstanceType()) {
    return false;
  }

  boolean replacedPrototype = prototype != null;

  this.prototype = prototype;
  this.prototypeSlot = new SimpleSlot("prototype", prototype, true);
  this.prototype.setOwnerFunction(this);

    // Disassociating the old prototype makes this easier to debug--
    // we don't have to worry about two prototypes running around.

  if (isConstructor() || isInterface()) {
    FunctionType superClass = getSuperClassConstructor();
    if (superClass != null) {
      superClass.addSubType(this);
    }

    if (isInterface()) {
      for (ObjectType interfaceType : getExtendedInterfaces()) {
        if (interfaceType.getConstructor() != null) {
          interfaceType.getConstructor().addSubType(this);
        }
      }
    }
  }

  if (replacedPrototype) {
    clearCachedValues();
  }

  return true;
}

private static boolean isReduceableFunctionExpression(Node n) {
  if (NodeUtil.isFunctionExpression(n)) {
    Node fn = n.getFirstChild();
    return fn.getChildCount() == 1 && NodeUtil.isFunction(fn.getFirstChild());
  }
  return false;
}

public String getLine(int lineNumber) {
  String js = "";
  try {
    // NOTE(nicksantos): Right now, this is optimized for few warnings.
    // This is probably the right trade-off, but will be slow if there
    // are lots of warnings in one file.
    js = getCode();
  } catch (IOException e) {
    return null;
  }

  int pos = 0;
  int startLine = 1;

  // If we've saved a previous offset and it's for a line less than the
  // one we're searching for, then start at that point.
  if (lineNumber >= lastLine) {
    pos = lastOffset;
    startLine = lastLine;
  }

  for (int n = startLine; n < lineNumber; n++) {
    int nextpos = js.indexOf('\n', pos);
    if (nextpos == -1) {
      return null;
    }
    pos = nextpos + 1;
  }

  // Remember this offset for the next search we do.
  lastOffset = pos;
  lastLine = lineNumber;

  if (js.indexOf('\n', pos) == -1) {
    // If next new line cannot be found, there are two cases
    // 1. pos already reaches the end of file, then null should be returned
    // 2. otherwise, return the contents between pos and the end of file.
    return js.substring(pos);
  } else {
    return js.substring(pos, js.indexOf('\n', pos));
  }
}

public void initOptions(CompilerOptions options) {
  this.options = options;
  if (errorManager == null) {
    if (outStream == null) {
      setErrorManager(
          new LoggerErrorManager(createMessageFormatter(), logger));
    } else {
      PrintStreamErrorManager printer =
          new PrintStreamErrorManager(createMessageFormatter(), outStream);
      printer.setSummaryDetailLevel(options.summaryDetailLevel);
      setErrorManager(printer);
    }
  }

  // DiagnosticGroups override the plain checkTypes option.
  if (options.enables(DiagnosticGroups.CHECK_TYPES)) {
    options.checkTypes = true;
  } else if (options.disables(DiagnosticGroups.CHECK_TYPES)) {
    options.checkTypes = false;
  } else if (!options.checkTypes) {
    // If DiagnosticGroups did not override the plain checkTypes
    // option, and checkTypes is enabled, then turn off the
    // parser type warnings.
    options.setWarningLevel(
        DiagnosticGroup.forType(
            RhinoErrorReporter.TYPE_PARSE_ERROR),
        CheckLevel.OFF);
  }

  if (options.checkGlobalThisLevel.isOn()) {
    options.setWarningLevel(
        DiagnosticGroups.GLOBAL_THIS,
        options.checkGlobalThisLevel);
  }

  if (options.getLanguageIn() == LanguageMode.ECMASCRIPT5_STRICT) {
    options.setWarningLevel(
        DiagnosticGroups.ES5_STRICT,
        CheckLevel.ERROR);
  }

  // Initialize the warnings guard.
  List<WarningsGuard> guards = Lists.newArrayList();
  guards.add(
      new SuppressDocWarningsGuard(
          getDiagnosticGroups().getRegisteredGroups()));
  guards.add(options.getWarningsGuard());

  ComposeWarningsGuard composedGuards = new ComposeWarningsGuard(guards);

  // All passes must run the variable check. This synthesizes
  // variables later so that the compiler doesn't crash. It also
  // checks the externs file for validity. If you don't want to warn
  // about missing variable declarations, we shut that specific
  // error off.
  if (!options.checkSymbols &&
      !composedGuards.enables(DiagnosticGroups.CHECK_VARIABLES)) {
    composedGuards.addGuard(new DiagnosticGroupWarningsGuard(
        DiagnosticGroups.CHECK_VARIABLES, CheckLevel.OFF));
  }

  this.warningsGuard = composedGuards;
}

static TernaryValue getImpureBooleanValue(Node n) {
  switch (n.getType()) {
    case Token.ASSIGN:
    case Token.COMMA:
      // For ASSIGN and COMMA the value is the value of the RHS.
      return getImpureBooleanValue(n.getLastChild());
    case Token.NOT:
      TernaryValue value = getImpureBooleanValue(n.getLastChild());
      return value.not();
    case Token.AND: {
      TernaryValue lhs = getImpureBooleanValue(n.getFirstChild());
      TernaryValue rhs = getImpureBooleanValue(n.getLastChild());
      return lhs.and(rhs);
    }
    case Token.OR:  {
      TernaryValue lhs = getImpureBooleanValue(n.getFirstChild());
      TernaryValue rhs = getImpureBooleanValue(n.getLastChild());
      return lhs.or(rhs);
    }
    case Token.HOOK:  {
      TernaryValue trueValue = getImpureBooleanValue(
          n.getFirstChild().getNext());
      TernaryValue falseValue = getImpureBooleanValue(n.getLastChild());
      if (trueValue.equals(falseValue)) {
        return trueValue;
      } else {
        return TernaryValue.UNKNOWN;
      }
    }
    case Token.ARRAYLIT:
    case Token.OBJECTLIT:
      // ignoring side-effects
      return TernaryValue.TRUE;

    default:
      return getPureBooleanValue(n);
  }
}

static TernaryValue getPureBooleanValue(Node n) {
  switch (n.getType()) {
    case Token.STRING:
      return TernaryValue.forBoolean(n.getString().length() > 0);

    case Token.NUMBER:
      return TernaryValue.forBoolean(n.getDouble() != 0);

    case Token.NOT:
      return getPureBooleanValue(n.getLastChild()).not();

    case Token.NULL:
    case Token.FALSE:
      return TernaryValue.FALSE;

    case Token.VOID:
        return TernaryValue.FALSE;

    case Token.NAME:
      String name = n.getString();
      if ("undefined".equals(name)
          || "NaN".equals(name)) {
        // We assume here that programs don't change the value of the keyword
        // undefined to something other than the value undefined.
        return TernaryValue.FALSE;
      } else if ("Infinity".equals(name)) {
        return TernaryValue.TRUE;
      }
      break;

    case Token.TRUE:
    case Token.REGEXP:
      return TernaryValue.TRUE;

    case Token.ARRAYLIT:
    case Token.OBJECTLIT:
      if (!mayHaveSideEffects(n)) {
        return TernaryValue.TRUE;
      }
      break;
  }

  return TernaryValue.UNKNOWN;
}

static boolean isNumericResultHelper(Node n) {
    switch (n.getType()) {
      case Token.ADD:
        return !mayBeString(n.getFirstChild())
            && !mayBeString(n.getLastChild());
      case Token.BITNOT:
      case Token.BITOR:
      case Token.BITXOR:
      case Token.BITAND:
      case Token.LSH:
      case Token.RSH:
      case Token.URSH:
      case Token.SUB:
      case Token.MUL:
      case Token.MOD:
      case Token.DIV:
      case Token.INC:
      case Token.DEC:
      case Token.POS:
      case Token.NEG:
      case Token.NUMBER:
        return true;
      case Token.NAME:
        String name = n.getString();
        if (name.equals("NaN")) {
          return true;
        }
        if (name.equals("Infinity")) {
          return true;
        }
        return false;
      default:
        return false;
    }
  }

static boolean constructorCallHasSideEffects(Node callNode, AbstractCompiler compiler) {
    if (callNode.getType() != Token.NEW) {
      throw new IllegalStateException(
          "Expected NEW node, got " + Token.name(callNode.getType()));
    }

    if (callNode.isNoSideEffectsCall()) {
      return false;
    }

    Node nameNode = callNode.getFirstChild();
    if (nameNode.getType() == Token.NAME &&
        CONSTRUCTORS_WITHOUT_SIDE_EFFECTS.contains(nameNode.getString())) {
      return false;
    }

    return true;
  }

private String format(JSError error, boolean warning) {
  // extract source excerpt
  SourceExcerptProvider source = getSource();
  String sourceExcerpt = source == null ? null :
      excerpt.get(
          source, error.sourceName, error.lineNumber, excerptFormatter);

  // formatting the message
  StringBuilder b = new StringBuilder();
  if (error.sourceName != null) {
    b.append(error.sourceName);
    if (error.lineNumber > 0) {
      b.append(':');
      b.append(error.lineNumber);
    }
    b.append(": ");
  }

  b.append(getLevelName(warning ? CheckLevel.WARNING : CheckLevel.ERROR));
  b.append(" - ");

  b.append(error.description);
  b.append('\n');
  if (sourceExcerpt != null) {
    b.append(sourceExcerpt);
    b.append('\n');
    int charno = error.getCharno();

    // padding equal to the excerpt and arrow at the end
    // charno == sourceExpert.length() means something is missing
    // at the end of the line
    if (excerpt.equals(LINE)
        && 0 <= charno && charno < sourceExcerpt.length()) {
      for (int i = 0; i < charno; i++) {
        char c = sourceExcerpt.charAt(i);
        if (Character.isWhitespace(c)) {
          b.append(c);
        } else {
          b.append(' ');
        }
      }
      b.append("^\n");
    }
  }
  return b.toString();
}

runInCompilerThread(new Callable<Void>() {
  public Void call() throws Exception {
    if (options.printInputDelimiter) {
      if ((cb.getLength() > 0) && !cb.endsWith("\n")) {
        cb.append("\n");  // Make sure that the label starts on a new line
      }
      Preconditions.checkState(root.getType() == Token.SCRIPT);

      String delimiter = options.inputDelimiter;

      String sourceName = (String)root.getProp(Node.SOURCENAME_PROP);
      Preconditions.checkState(sourceName != null);
      Preconditions.checkState(!sourceName.isEmpty());

      delimiter = delimiter.replaceAll("%name%", sourceName)
        .replaceAll("%num%", String.valueOf(inputSeqNum));

      cb.append(delimiter)
        .append("\n");
    }
    if (root.getJSDocInfo() != null &&
        root.getJSDocInfo().getLicense() != null) {
      cb.append("/*\n")
        .append(root.getJSDocInfo().getLicense())
        .append("*/\n");
    }

    // If there is a valid source map, then indicate to it that the current
    // root node's mappings are offset by the given string builder buffer.
    if (options.sourceMapOutputPath != null) {
      sourceMap.setStartingPosition(
          cb.getLineIndex(), cb.getColumnIndex());
    }

    // if LanguageMode is ECMASCRIPT5_STRICT, only print 'use strict'
    // for the first input file
    String code = toSource(root, sourceMap);
    if (!code.isEmpty()) {
      cb.append(code);

      // In order to avoid parse ambiguity when files are concatenated
      // together, all files should end in a semi-colon. Do a quick
      // heuristic check if there's an obvious semi-colon already there.
      int length = code.length();
      char lastChar = code.charAt(length - 1);
      char secondLastChar = length >= 2 ?
          code.charAt(length - 2) : '\0';
      boolean hasSemiColon = lastChar == ';' ||
          (lastChar == '\n' && secondLastChar == ';');
      if (!hasSemiColon) {
        cb.append(";");
      }
    }
    return null;
  }
});

String toSource(Node n) {
  initCompilerOptionsIfTesting();
  return toSource(n, null);
}

private String toSource(Node n, SourceMap sourceMap) {
  CodePrinter.Builder builder = new CodePrinter.Builder(n);
  builder.setPrettyPrint(options.prettyPrint);
  builder.setLineBreak(options.lineBreak);
  builder.setSourceMap(sourceMap);
  builder.setSourceMapDetailLevel(options.sourceMapDetailLevel);
  builder.setTagAsStrict(
      options.getLanguageOut() == LanguageMode.ECMASCRIPT5_STRICT);
  builder.setLineLengthThreshold(options.lineLengthThreshold);

  Charset charset = options.outputCharset != null ?
      Charset.forName(options.outputCharset) : null;
  builder.setOutputCharset(charset);

  return builder.build();
}

private boolean isPrototypePropertyAssign(Node assign) {
  Node n = assign.getFirstChild();
  if (n != null && NodeUtil.isVarOrSimpleAssignLhs(n, assign)
      && n.getType() == Token.GETPROP
      ) {
    // We want to exclude the assignment itself from the usage list
    boolean isChainedProperty =
        n.getFirstChild().getType() == Token.GETPROP;

    if (isChainedProperty) {
      Node child = n.getFirstChild().getFirstChild().getNext();

      if (child.getType() == Token.STRING &&
          child.getString().equals("prototype")) {
        return true;
      }
    }
  }

  return false;
}

private void visitCall(NodeTraversal t, Node n) {
  Node child = n.getFirstChild();
  JSType childType = getJSType(child).restrictByNotNullOrUndefined();

  if (!childType.canBeCalled()) {
    report(t, n, NOT_CALLABLE, childType.toString());
    ensureTyped(t, n);
    return;
  }

  // A couple of types can be called as if they were functions.
  // If it is a function type, then validate parameters.
  if (childType instanceof FunctionType) {
    FunctionType functionType = (FunctionType) childType;

    boolean isExtern = false;
    JSDocInfo functionJSDocInfo = functionType.getJSDocInfo();
    if(functionJSDocInfo != null) {
      String sourceName = functionJSDocInfo.getSourceName();
      CompilerInput functionSource = compiler.getInput(sourceName);
      isExtern = functionSource.isExtern();
    }

    // Non-native constructors should not be called directly
    // unless they specify a return type and are defined
    // in an extern.
    if (functionType.isConstructor() &&
        !functionType.isNativeObjectType() &&
        (functionType.getReturnType().isUnknownType() ||
         functionType.getReturnType().isVoidType() ||
         !isExtern)) {
      report(t, n, CONSTRUCTOR_NOT_CALLABLE, childType.toString());
    }

    // Functions with explcit 'this' types must be called in a GETPROP
    // or GETELEM.

    visitParameterList(t, n, functionType);
    ensureTyped(t, n, functionType.getReturnType());
  } else {
    ensureTyped(t, n);
  }

  // TODO: Add something to check for calls of RegExp objects, which is not
  // supported by IE.  Either say something about the return type or warn
  // about the non-portability of the call or both.

  // Check if the function is being called as an instance method
  if (n.isFunction() && n.getParent().isCall() && n.getParent().getFirstChild() == n) {
    Node context = n.getParent().getSecondChild();
    if (context != null && !context.isThis()) {
      report(t, n, INSTANCE_METHOD_AS_FUNCTION, childType.toString());
    }
  }
}

private void declareArguments(Node functionNode) {
  Node astParameters = functionNode.getFirstChild().getNext();
  Node body = astParameters.getNext();
  FunctionType functionType = (FunctionType) functionNode.getJSType();
  if (functionType != null) {
    Node jsDocParameters = functionType.getParametersNode();
    if (jsDocParameters != null) {
      Node jsDocParameter = jsDocParameters.getFirstChild();
      for (Node astParameter : astParameters.children()) {
        if (jsDocParameter != null) {
          defineSlot(astParameter, functionNode,
              jsDocParameter.getJSType(), true);
          jsDocParameter = jsDocParameter.getNext();
        } else {
          defineSlot(astParameter, functionNode, null, true);
        }
      }
    }
  }
} // end declareArguments

private void makeLocalNamesUnique(Node fnNode, boolean isCallInLoop) {
  Supplier<String> idSupplier = compiler.getUniqueNameIdSupplier();
  // Make variable names unique to this instance.
  NodeTraversal.traverse(
      compiler, fnNode, new MakeDeclaredNamesUnique(
          new InlineRenamer(
              idSupplier,
              "inline_",
              isCallInLoop)));
  // Make label names unique to this instance.
  NodeTraversal.traverse(
      compiler, fnNode, new RenameLabels(
          idSupplier,
          "label_",
          isCallInLoop));
}

private void visitLabel(Node node, Node parent) {
  Node nameNode = node.getFirstChild();
  Preconditions.checkState(nameNode != null);
  String name = nameNode.getString();
  LabelInfo li = getLabelInfo(name);
  // This is a label...
  if (li.referenced) {
    String newName = getNameForId(li.id);
    if (!name.equals(newName)) {
      // ... and it is used, give it the short name.
      nameNode.setString(newName);
      compiler.reportCodeChange();
    }
  } else {
    // ... and it is not referenced, just remove it.
    Node newChild = node.getLastChild();
    node.removeChild(newChild);
    parent.replaceChild(node, newChild);
    if (newChild.getType() == Token.BLOCK) {
      NodeUtil.tryMergeBlock(newChild);
    }
    compiler.reportCodeChange();
  }

  // Remove the label from the current stack of labels.
  namespaceStack.peek().renameMap.remove(name);
}

private Node tryFoldComparison(Node n, Node left, Node right) {
  if (!NodeUtil.isLiteralValue(left, false) ||
      !NodeUtil.isLiteralValue(right, false)) {
    // We only handle non-literal operands for LT and GT.
    if (n.getType() != Token.GT && n.getType() != Token.LT) {
      return n;
    }
  }

  int op = n.getType();
  boolean result;

  // TODO(johnlenz): Use the JSType to compare nodes of different types.

  boolean rightLiteral = NodeUtil.isLiteralValue(right, false);
  boolean undefinedRight = ((Token.NAME == right.getType()
        && right.getString().equals("undefined"))
        || (Token.VOID == right.getType()
            && NodeUtil.isLiteralValue(right.getFirstChild(), false)));
  int lhType = left.getType();
  int rhType = right.getType();
  switch (lhType) {
    case Token.VOID:
      if (!NodeUtil.isLiteralValue(left.getFirstChild(), false)) {
        return n;
      } else if (!rightLiteral) {
        return n;
      } else {
        result = compareToUndefined(right, op);
      }
      break;

    case Token.NULL:
    case Token.TRUE:
    case Token.FALSE:
      if (undefinedRight) {
        result = compareToUndefined(left, op);
        break;
      }
      if (rhType != Token.TRUE &&
          rhType != Token.FALSE &&
          rhType != Token.NULL) {
        return n;
      }
      switch (op) {
        case Token.SHEQ:
        case Token.EQ:
          result = lhType == rhType;
          break;

        case Token.SHNE:
        case Token.NE:
          result = lhType != rhType;
          break;

        case Token.GE:
        case Token.LE:
        case Token.GT:
        case Token.LT:
          Boolean compareResult = compareAsNumbers(op, left, right);
          if (compareResult != null) {
            result = compareResult;
          } else {
            return n;
          }
          break;

        default:
          return n;  // we only handle == and != here
      }
      break;

    case Token.THIS:
      if (right.getType() != Token.THIS) {
        return n;
      }
      switch (op) {
        case Token.SHEQ:
        case Token.EQ:
          result = true;
          break;

        case Token.SHNE:
        case Token.NE:
          result = false;
          break;

        // We can only handle == and != here.
        // GT, LT, GE, LE depend on the type of "this" and how it will
        // be converted to number.  The results are different depending on
        // whether it is a string, NaN or other number value.
        default:
          return n;
      }
      break;

    case Token.STRING:
      if (undefinedRight) {
        result = compareToUndefined(left, op);
        break;
      }
      if (Token.STRING != right.getType()) {
        return n;  // Only eval if they are the same type
      }
      switch (op) {
        case Token.SHEQ:
        case Token.EQ:
          result = left.getString().equals(right.getString());
          break;

        case Token.SHNE:
        case Token.NE:
          result = !left.getString().equals(right.getString());
          break;

        default:
          return n;  // we only handle == and != here
      }
      break;

    case Token.NUMBER:
      if (undefinedRight) {
        result = compareToUndefined(left, op);
        break;
      }
      if (Token.NUMBER != right.getType()) {
        return n;  // Only eval if they are the same type
      }
      Boolean compareResult = compareAsNumbers(op, left, right);
      if (compareResult != null) {
        result = compareResult;
      } else {
        return null;
      }
      break;

    case Token.NAME:
      if (undefinedRight) {
        result = compareToUndefined(left, op);
        break;
      }

      if (rightLiteral) {
        boolean undefinedLeft = (left.getString().equals("undefined"));
        if (undefinedLeft) {
          result = compareToUndefined(right, op);
          break;
        }
      }

      if (Token.NAME != right.getType()) {
        return n;  // Only eval if they are the same type
      }
      String ln = left.getString();
      String rn = right.getString();
      if (!ln.equals(rn)) {
        return n;  // Not the same value name.
      }

      switch (op) {
        // If we knew the named value wouldn't be NaN, it would be nice
        // to handle EQ,NE,LE,GE,SHEQ, and SHNE.
        case Token.LT:
        case Token.GT:
          result = false;
          break;
        default:
          return n;  // don't handle that op
      }
      break;

    default:
      // assert, this should cover all consts
      return n;
  }

  Node newNode = new Node(result ? Token.TRUE : Token.FALSE);
  n.getParent().replaceChild(n, newNode);
  reportCodeChange();

  return newNode;
}

static Double getStringNumberValue(String rawJsString) {
    // vertical tab is not always whitespace

  String s = trimJsWhiteSpace(rawJsString);
  // return ScriptRuntime.toNumber(s);
  if (s.length() == 0) {
    return 0.0;
  }

  if (s.length() > 2
      && s.charAt(0) == '0'
      && (s.charAt(1) == 'x' || s.charAt(1) == 'X')) {
    // Attempt to convert hex numbers.
    try {
      return Double.valueOf(Integer.parseInt(s.substring(2), 16));
    } catch (NumberFormatException e) {
      return Double.NaN;
    }
  }

  if (s.length() > 3
      && (s.charAt(0) == '-' || s.charAt(0) == '+')
      && s.charAt(1) == '0'
      && (s.charAt(2) == 'x' || s.charAt(2) == 'X')) {
    // hex numbers with explicit signs vary between browsers.
    return null;
  }

  // FireFox and IE treat the "Infinity" differently. FireFox is case
  // insensitive, but IE treats "infinity" as NaN.  So leave it alone.
  if (s.equalsIgnoreCase("infinity")) {
    return Double.POSITIVE_INFINITY;
  }

  try {
    return Double.parseDouble(s);
  } catch (NumberFormatException e) {
    return Double.NaN;
  }
}

static TernaryValue isStrWhiteSpaceChar(int c) {
  switch (c) {
    case '\u000B': // <VT>
      return TernaryValue.TRUE;
    case ' ': // <SP>
    case '\n': // <LF>
    case '\r': // <CR>
    case '\t': // <TAB>
    case '\u00A0': // <NBSP>
    case '\u000C': // <FF>
    case '\u2028': // <LS>
    case '\u2029': // <PS>
    case '\uFEFF': // <BOM>
      return TernaryValue.TRUE;
    default:
      return (Character.getType(c) == Character.SPACE_SEPARATOR)
          ? TernaryValue.TRUE : TernaryValue.FALSE;
  }
}

