static boolean isValidDefineValue(Node val, Set<String> defines) {
  switch (val.getType()) {
    case Token.STRING:
    case Token.NUMBER:
    case Token.TRUE:
    case Token.FALSE:
      return true;

    // Binary operators are only valid if both children are valid.
    case Token.BITAND:
    case Token.BITNOT:
    case Token.BITOR:
    case Token.BITXOR:

    // Uniary operators are valid if the child is valid.
    case Token.NOT:
    case Token.NEG:
      return isValidDefineValue(val.getFirstChild(), defines);

    // Names are valid if and only if they are defines themselves.
    case Token.NAME:
    case Token.GETPROP:
      if (val.isQualifiedName()) {
        return defines.contains(val.getQualifiedName());
      }
  }
  return false;
}

void defineSlot(Node n, Node parent, JSType type, boolean inferred) {
  Preconditions.checkArgument(inferred || type != null);

  // Only allow declarations of NAMEs and qualfied names.
  boolean shouldDeclareOnGlobalThis = false;
  if (n.getType() == Token.NAME) {
    Preconditions.checkArgument(
        parent.getType() == Token.FUNCTION ||
        parent.getType() == Token.VAR ||
        parent.getType() == Token.LP ||
        parent.getType() == Token.CATCH);
    shouldDeclareOnGlobalThis = scope.isGlobal() &&
        (parent.getType() == Token.VAR ||
         parent.getType() == Token.FUNCTION);
  } else {
    Preconditions.checkArgument(
        n.getType() == Token.GETPROP &&
        (parent.getType() == Token.ASSIGN ||
         parent.getType() == Token.EXPR_RESULT));
  }
  String variableName = n.getQualifiedName();
  Preconditions.checkArgument(!variableName.isEmpty());

  // If n is a property, then we should really declare it in the
  // scope where the root object appears. This helps out people
  // who declare "global" names in an anonymous namespace.
  Scope scopeToDeclareIn = scope;

    // don't try to declare in the global scope if there's
    // already a symbol there with this name.

  // declared in closest scope?
  if (scopeToDeclareIn.isDeclared(variableName, false)) {
    Var oldVar = scopeToDeclareIn.getVar(variableName);
    validator.expectUndeclaredVariable(
        sourceName, n, parent, oldVar, variableName, type);
  } else {
    if (!inferred) {
      setDeferredType(n, type);
    }
    CompilerInput input = compiler.getInput(sourceName);
    scopeToDeclareIn.declare(variableName, n, type, input, inferred);

    if (shouldDeclareOnGlobalThis) {
      ObjectType globalThis =
          typeRegistry.getNativeObjectType(JSTypeNative.GLOBAL_THIS);
      boolean isExtern = input.isExtern();
      if (inferred) {
        globalThis.defineInferredProperty(variableName,
            type == null ?
                getNativeType(JSTypeNative.NO_TYPE) :
                type,
            isExtern);
      } else {
        globalThis.defineDeclaredProperty(variableName, type, isExtern);
      }
    }

    // If we're in the global scope, also declare var.prototype
    // in the scope chain.
    if (scopeToDeclareIn.isGlobal() && type instanceof FunctionType) {
      FunctionType fnType = (FunctionType) type;
      if (fnType.isConstructor() || fnType.isInterface()) {
        FunctionType superClassCtor = fnType.getSuperClassConstructor();
        scopeToDeclareIn.declare(variableName + ".prototype", n,
            fnType.getPrototype(), compiler.getInput(sourceName),
            /* declared iff there's an explicit supertype */
            superClassCtor == null ||
            superClassCtor.getInstanceType().equals(
                getNativeType(OBJECT_TYPE)));
      }
    }
  }
}

public boolean shouldTraverse(NodeTraversal t, Node n, Node parent) {
    checkNoTypeCheckSection(n, true);
    switch (n.getType()) {
      case Token.FUNCTION:
        // normal type checking
        final TypeCheck outerThis = this;
        final Scope outerScope = t.getScope();
        final FunctionType functionType = (FunctionType) n.getJSType();
        final String functionPrivateName = n.getFirstChild().getString();
        if (functionPrivateName != null && functionPrivateName.length() > 0 &&
            outerScope.isDeclared(functionPrivateName, false) &&
            // Ideally, we would want to check whether the type in the scope
            // differs from the type being defined, but then the extern
            // redeclarations of built-in types generates spurious warnings.
            !(outerScope.getVar(
                functionPrivateName).getType() instanceof FunctionType)) {
          report(t, n, FUNCTION_MASKS_VARIABLE, functionPrivateName);
        }

        // TODO(user): Only traverse the function's body. The function's
        // name and arguments are traversed by the scope creator, and ideally
        // should not be traversed by the type checker.
        break;
    }
    return true;
}

private Node tryFoldShift(Node n, Node left, Node right) {
  if (left.getType() == Token.NUMBER &&
      right.getType() == Token.NUMBER) {

    double result;
    double lval = left.getDouble();
    double rval = right.getDouble();

    // check ranges.  We do not do anything that would clip the double to
    // a 32-bit range, since the user likely does not intend that.
    if (!(lval >= Integer.MIN_VALUE && lval <= Integer.MAX_VALUE)) {
      error(BITWISE_OPERAND_OUT_OF_RANGE, left);
      return n;
    }

    // only the lower 5 bits are used when shifting, so don't do anything
    // if the shift amount is outside [0,32)
    if (!(rval >= 0 && rval < 32)) {
      error(SHIFT_AMOUNT_OUT_OF_BOUNDS, right);
      return n;
    }

    // Convert the numbers to ints
    int lvalInt = (int) lval;
    if (lvalInt != lval) {
      error(FRACTIONAL_BITWISE_OPERAND, left);
      return n;
    }

    int rvalInt = (int) rval;
    if (rvalInt != rval) {
      error(FRACTIONAL_BITWISE_OPERAND, right);
      return n;
    }

    switch (n.getType()) {
      case Token.LSH:
        result = lvalInt << rvalInt;
        break;
      case Token.RSH:
        result = lvalInt >> rvalInt;
        break;
      case Token.URSH:
        // JavaScript handles zero shifts on signed numbers differently than
        // Java as an Java int can not represent the unsigned 32-bit number
        // where JavaScript can so use a long here.
        result = (double) (lvalInt >>> rvalInt);
        break;
      default:
        throw new AssertionError("Unknown shift operator: " +
            Node.tokenToName(n.getType()));
    }

    Node newNumber = Node.newNumber(result);
    n.getParent().replaceChild(n, newNumber);
    reportCodeChange();

    return newNumber;
  }

  return n;
}

boolean isAssignedOnceInLifetime() {
  Reference ref = getOneAndOnlyAssignment();
  if (ref == null) {
    return false;
  }

  // Make sure this assignment is not in a loop.

  Node assignmentNode = ref.getNode();
  while (NodeUtil.isInLoop(assignmentNode)) {
    assignmentNode = assignmentNode.getParent();
  }

  return true;
}

BasicBlock(BasicBlock parent, Node root) {
  this.parent = parent;

  // only named functions may be hoisted.
  this.isHoisted = NodeUtil.isHoistedFunctionDeclaration(root);

  // Check if the function is in a loop
  if (NodeUtil.isInLoop(root)) {
    this.isHoisted = false;
  }
}

public boolean shouldTraverse(NodeTraversal t, Node n, Node parent) {

  if (n.getType() == Token.FUNCTION) {
    // Don't traverse functions that are constructors or have the @this
    // or @override annotation.
    JSDocInfo jsDoc = getFunctionJsDocInfo(n);
    if (jsDoc != null &&
        (jsDoc.isConstructor() ||
         jsDoc.hasThisType() ||
         jsDoc.isOverride())) {
      return false;
    }

    // Don't traverse functions unless they would normally
    // be able to have a @this annotation associated with them. e.g.,
    // var a = function() { }; // or
    // function a() {} // or
    // a.x = function() {};
    int pType = parent.getType();
    if (!(pType == Token.BLOCK ||
          pType == Token.SCRIPT ||
          pType == Token.NAME ||
          pType == Token.ASSIGN)) {
      return false;
    }
  }

  if (parent != null && parent.getType() == Token.ASSIGN) {
    Node lhs = parent.getFirstChild();
    Node rhs = lhs.getNext();

    if (n == lhs) {
      // Always traverse the left side of the assignment. To handle
      // nested assignments properly (e.g., (a = this).property = c;),
      // assignLhsChild should not be overridden.
      if (assignLhsChild == null) {
        assignLhsChild = lhs;
      }
    } else {
      // Only traverse the right side if it's not an assignment to a prototype
      // property or subproperty.
        if (lhs.getType() == Token.GETPROP &&
            lhs.getLastChild().getString().equals("prototype")) {
          return false;
        }
        if (lhs.getQualifiedName() != null && lhs.getQualifiedName().contains(".prototype.")) {
          return false;
        }
    }
  }

  return true;
}

public boolean shouldTraverse(NodeTraversal t, Node n, Node parent) {

  if (n.getType() == Token.FUNCTION) {
    // Don't traverse functions that are constructors or have the @this
    // annotation.
    JSDocInfo jsDoc = getFunctionJsDocInfo(n);
    if (jsDoc != null && (jsDoc.isConstructor() || jsDoc.hasThisType())) {
      return false;
    }

    // Don't traverse functions unless they would normally
    // be able to have a @this annotation associated with them. e.g.,
    // var a = function() { }; // or
    // function a() {} // or
    // a.x = function() {};
  }

  if (parent != null && parent.getType() == Token.ASSIGN) {
    Node lhs = parent.getFirstChild();
    Node rhs = lhs.getNext();

    if (n == lhs) {
      // Always traverse the left side of the assignment. To handle
      // nested assignments properly (e.g., (a = this).property = c;),
      // assignLhsChild should not be overridden.
      if (assignLhsChild == null) {
        assignLhsChild = lhs;
      }
    } else {
      // Only traverse the right side if it's not an assignment to a prototype
      // property or subproperty.
      if (lhs.getType() == Token.GETPROP) {
        if (lhs.getLastChild().getString().equals("prototype")) {
          return false;
        }
        String leftName = lhs.getQualifiedName();
        if (leftName != null && leftName.contains(".prototype.")) {
          return false;
        }
      }
    }
  }

  return true;
}

private boolean shouldReportThis(Node n, Node parent) {
  if (assignLhsChild != null) {
    // Always report a THIS on the left side of an assign.
    return true;
  }

  // Also report a THIS with a property access.
  return false;
}

protected CompilerOptions createOptions() {
  CompilerOptions options = new CompilerOptions();
  options.setCodingConvention(new ClosureCodingConvention());
  CompilationLevel level = flags.compilation_level;
  level.setOptionsForCompilationLevel(options);
  if (flags.debug) {
    level.setDebugOptionsForCompilationLevel(options);
  }

  WarningLevel wLevel = flags.warning_level;
  wLevel.setOptionsForWarningLevel(options);
  for (FormattingOption formattingOption : flags.formatting) {
    formattingOption.applyToOptions(options);
  }
  if (flags.process_closure_primitives) {
    options.closurePass = true;
  } else {
    options.closurePass = false;
  }

  initOptionsFromFlags(options);
  return options;
}

public void process(Node externs, Node root) {
  NodeTraversal.traverse(compiler, root, this);
  if (MAKE_LOCAL_NAMES_UNIQUE) {
    MakeDeclaredNamesUnique renamer = new MakeDeclaredNamesUnique();
    NodeTraversal t = new NodeTraversal(compiler, renamer);
    t.traverseRoots(externs, root);
  }
  removeDuplicateDeclarations(root);
  new PropogateConstantAnnotations(compiler, assertOnChange)
      .process(externs, root);
}

private static boolean mayThrowException(Node n) {
  switch (n.getType()) {
    case Token.CALL:
    case Token.GETPROP:
    case Token.GETELEM:
    case Token.THROW:
    case Token.NEW:
    case Token.ASSIGN:
    case Token.INC:
    case Token.DEC:
      return true;
    case Token.FUNCTION:
      return false;
  }
  for (Node c = n.getFirstChild(); c != null; c = c.getNext()) {
    if (!ControlFlowGraph.isEnteringNewCfgNode(c) && mayThrowException(c)) {
      return true;
    }
  }
  return false;
}

boolean canCollapseUnannotatedChildNames() {
  if (type == Type.OTHER || globalSets != 1 || localSets != 0) {
    return false;
  }

  // Don't try to collapse if the one global set is a twin reference.
  // We could theoretically handle this case in CollapseProperties, but
  // it's probably not worth the effort.

  if (isClassOrEnum) {
    return true;
  }
  return (type == Type.FUNCTION || aliasingGets == 0) &&
      (parent == null || parent.canCollapseUnannotatedChildNames());
}

protected CompilerOptions createOptions() {
  CompilerOptions options = new CompilerOptions();
  if (flags.processJqueryPrimitives) {
    options.setCodingConvention(new JqueryCodingConvention());
  } else {
    options.setCodingConvention(new ClosureCodingConvention());
  }

  options.setExtraAnnotationNames(flags.extraAnnotationName);

  CompilationLevel level = flags.compilationLevel;
  level.setOptionsForCompilationLevel(options);

  if (flags.debug) {
    level.setDebugOptionsForCompilationLevel(options);
  }

  if (flags.useTypesForOptimization) {
    level.setTypeBasedOptimizationOptions(options);
  }

  if (flags.generateExports) {
    options.setGenerateExports(flags.generateExports);
  }

  WarningLevel wLevel = flags.warningLevel;
  wLevel.setOptionsForWarningLevel(options);
  for (FormattingOption formattingOption : flags.formatting) {
    formattingOption.applyToOptions(options);
  }

  options.closurePass = flags.processClosurePrimitives;

  options.jqueryPass = CompilationLevel.ADVANCED_OPTIMIZATIONS == level &&
      flags.processJqueryPrimitives;

  options.angularPass = flags.angularPass;

  if (!flags.translationsFile.isEmpty()) {
    try {
      options.messageBundle = new XtbMessageBundle(
          new FileInputStream(flags.translationsFile),
          flags.translationsProject);
    } catch (IOException e) {
      throw new RuntimeException("Reading XTB file", e);
    }
  } else if (CompilationLevel.ADVANCED_OPTIMIZATIONS == level) {
    // In SIMPLE or WHITESPACE mode, if the user hasn't specified a
    // translations file, they might reasonably try to write their own
    // implementation of goog.getMsg that makes the substitution at
    // run-time.
    //
    // In ADVANCED mode, goog.getMsg is going to be renamed anyway,
    // so we might as well inline it. But shut off the i18n warnings,
    // because the user didn't really ask for i18n.
    options.messageBundle = new EmptyMessageBundle();
  }

  // Fix for the issue: Rename MSG_ prefixed variables to avoid errors with advanced optimizations
  if (options.messageBundle instanceof EmptyMessageBundle) {
      options.setCodingConvention(new CodingConvention() {
          @Override
          public VariableDeclaration getVariableDeclaration(Node node) {
              String name = node.getString();
              if (name.startsWith("MSG_")) {
                  return new VariableDeclaration("msg_" + name.substring(4));
              }
              return null;
          }

          @Override
          public Node getFunctionCall(Node node) {
              return null;
          }

          @Override
          public Node getFunctionDefinition(Node node) {
              return null;
          }

          @Override
          public Node getFunctionExpression(Node node) {
              return null;
          }

          @Override
          public Node getFunctionParameter(Node node) {
              return null;
          }

          @Override
          public Node getFunctionReturnType(Node node) {
              return null;
          }

          @Override
          public Node getFunctionThis(Node node) {
              return null;
          }

          @Override
          public Node getFunctionVarArgs(Node node) {
              return null;
          }

          @Override
          public Node getGlobalThis() {
              return null;
          }

          @Override
          public Node getParameter(Node node) {
              return null;
          }

          @Override
          public Node getReturnStatement(Node node) {
              return null;
          }

          @Override
          public Node getThisExpression(Node node) {
              return null;
          }

          @Override
          public Node getVariable(Node node) {
              return null;
          }

          @Override
          public Node getVariableReference(Node node) {
              return null;
          }

          @Override
          public Node getVariableValue(Node node) {
              return null;
          }

          @Override
          public Node getWithStatement(Node node) {
              return null;
          }
      });
  }

  return options;
}

private class Traversal implements NodeTraversal.ScopedCallback {
  // The job of this class is to collect these three data sets.

  // The order of this list determines the order that aliases are applied.
  private final List<Node> aliasDefinitionsInOrder = Lists.newArrayList();

  private final List<Node> scopeCalls = Lists.newArrayList();

  private final List<AliasUsage> aliasUsages = Lists.newArrayList();

  // This map is temporary and cleared for each scope.
  private final Map<String, Var> aliases = Maps.newHashMap();

  // Also temporary and cleared for each scope.

  // Suppose you create an alias.
  // var x = goog.x;
  // As a side-effect, this means you can shadow the namespace 'goog'
  // in inner scopes. When we inline the namespaces, we have to rename
  // these shadows.
  //
  // Fortunately, we already have a name uniquifier that runs during tree
  // normalization (before optimizations). We run it here on a limited
  // set of variables, but only as a last resort (because this will screw
  // up warning messages downstream).
  private final Set<String> forbiddenLocals = Sets.newHashSet("$jscomp");
  private boolean hasNamespaceShadows = false;

  private boolean hasErrors = false;

  private AliasTransformation transformation = null;

  Collection<Node> getAliasDefinitionsInOrder() {
    return aliasDefinitionsInOrder;
  }

  private List<AliasUsage> getAliasUsages() {
    return aliasUsages;
  }

  List<Node> getScopeCalls() {
    return scopeCalls;
  }

  boolean hasErrors() {
    return hasErrors;
  }

public void exitScope(NodeTraversal t) {
  if (t.getScopeDepth() > 2) {
    findNamespaceShadows(t);
  }

  if (t.getScopeDepth() == 2) {
    renameNamespaceShadows(t);
    aliases.clear();
    forbiddenLocals.clear();
    transformation = null;
    hasNamespaceShadows = false;
  }
}

private void findAliases(NodeTraversal t) {
  Scope scope = t.getScope();
  for (Var v : scope.getVarIterable()) {
    Node n = v.getNode();
    Node parent = n.getParent();
    boolean isVar = parent.isVar();
    boolean isFunctionDecl = NodeUtil.isFunctionDeclaration(parent);
    if (isVar && n.getFirstChild() != null && n.getFirstChild().isQualifiedName()) {
      recordAlias(v);
    } else if (v.isBleedingFunction()) {
      // Bleeding functions already get a BAD_PARAMETERS error, so just
      // do nothing.
    } else if (parent.getType() == Token.LP) {
      // Parameters of the scope function also get a BAD_PARAMETERS
      // error.
    } else if (isVar || isFunctionDecl) {
      boolean isHoisted = NodeUtil.isHoistedFunctionDeclaration(parent);
      Node grandparent = parent.getParent();
      Node value = v.getInitialValue() != null ?
          v.getInitialValue() :
          null;
      Node varNode = null;

      String name = n.getString();
      int nameCount = scopedAliasNames.count(name);
      scopedAliasNames.add(name);
      String globalName =
          "$jscomp.scope." + name + (nameCount == 0 ? "" : ("$" + nameCount));

      compiler.ensureLibraryInjected("base");

      // First, we need to free up the function expression (EXPR)
      // to be used in another expression.
      if (isFunctionDecl) {
        // Replace "function NAME() { ... }" with "var NAME;".
        Node existingName = v.getNameNode();

        // We can't keep the local name on the function expression,
        // because IE is buggy and will leak the name into the global
        // scope. This is covered in more detail here:
        // http://wiki.ecmascript.org/lib/exe/fetch.php?id=resources:resources&cache=cache&media=resources:jscriptdeviationsfromes3.pdf
        //
        // This will only cause problems if this is a hoisted, recursive
        // function, and the programmer is using the hoisting.
        Node newName = IR.name("").useSourceInfoFrom(existingName);
        value.replaceChild(existingName, newName);

        varNode = IR.var(existingName).useSourceInfoFrom(existingName);
        grandparent.replaceChild(parent, varNode);
      } else {
        if (value != null) {
          // If this is a VAR, we can just detach the expression and
          // the tree will still be valid.
          value.detachFromParent();
        }
        varNode = parent;
      }

      // Add $jscomp.scope.name = EXPR;
      // Make sure we copy over all the jsdoc and debug info.
      if (value != null || v.getJSDocInfo() != null) {
        Node newDecl = NodeUtil.newQualifiedNameNodeDeclaration(
            compiler.getCodingConvention(),
            globalName,
            value,
            v.getJSDocInfo())
            .useSourceInfoIfMissingFromForTree(n);
        NodeUtil.setDebugInformation(
            newDecl.getFirstChild().getFirstChild(), n, name);

        if (isHoisted) {
          grandparent.addChildToFront(newDecl);
        } else {
          grandparent.addChildBefore(newDecl, varNode);
        }
      }

      // Rewrite "var name = EXPR;" to "var name = $jscomp.scope.name;"
      v.getNameNode().addChildToFront(
          NodeUtil.newQualifiedNameNode(
              compiler.getCodingConvention(), globalName, n, name));

      recordAlias(v);
    } else {
      // Do not other kinds of local symbols, like catch params.
      report(t, n, GOOG_SCOPE_NON_ALIAS_LOCAL, n.getString());
    }
  }
}

public void visit(NodeTraversal t, Node n, Node parent) {
  if (isCallToScopeMethod(n)) {
    validateScopeCall(t, n, n.getParent());
  }

  if (t.getScopeDepth() < 2) {
    return;
  }

  int type = n.getType();
  Var aliasVar = null;
  if (type == Token.NAME) {
    String name = n.getString();
    Var lexicalVar = t.getScope().getVar(n.getString());
    if (lexicalVar != null && lexicalVar == aliases.get(name)) {
      aliasVar = lexicalVar;
    }
  }

  // Validate the top-level of the goog.scope block.
  if (t.getScopeDepth() == 2) {
    if (aliasVar != null && NodeUtil.isLValue(n)) {
      if (aliasVar.getNode() == n) {
        aliasDefinitionsInOrder.add(n);

        // Return early, to ensure that we don't record a definition
        // twice.
        return;
      } else {
        report(t, n, GOOG_SCOPE_ALIAS_REDEFINED, n.getString());
      }
    }

    if (type == Token.RETURN) {
      report(t, n, GOOG_SCOPE_USES_RETURN);
    } else if (type == Token.THIS) {
      report(t, n, GOOG_SCOPE_REFERENCES_THIS);
    } else if (type == Token.THROW) {
      report(t, n, GOOG_SCOPE_USES_THROW);
    }
  }

  // Validate all descendent scopes of the goog.scope block.
  if (t.getScopeDepth() >= 2) {
    // Check if this name points to an alias.
    if (aliasVar != null) {
      // Note, to support the transitive case, it's important we don't
      // clone aliasedNode here.  For example,
      // var g = goog; var d = g.dom; d.createElement('DIV');
      // The node in aliasedNode (which is "g") will be replaced in the
      // changes pass above with "goog".  If we cloned here, we'd end up
      // with <code>g.dom.createElement('DIV')</code>.
      aliasUsages.add(new AliasedNode(aliasVar, n));
    }

    // When we inject declarations, we duplicate jsdoc. Make sure
    // we only process that jsdoc once.
    JSDocInfo info = n.getJSDocInfo();
    if (info != null) {
      for (Node node : info.getTypeNodes()) {
        fixTypeNode(node);
      }
    }

    // TODO(robbyw): Error for goog.scope not at root.
  }
}

private Node parseContextTypeExpression(JsDocToken token) {
    if (token.getType() == JsDocToken.Type.QUESTION) {
        return null;
    }
    return parseTypeName(token);
}

