private void visitNew(NodeTraversal t, Node n) {
  Node constructor = n.getFirstChild();
  JSType type = getJSType(constructor).restrictByNotNullOrUndefined();
  if (type.isConstructor() || type.isEmptyType() || type.isUnknownType()) {
    FunctionType fnType = type.toMaybeFunctionType();
    if (fnType != null) {
      visitParameterList(t, n, fnType);
      JSType instanceType = fnType.getInstanceType();
      if (instanceType != null) {
        ensureTyped(t, n, instanceType);
      } else {
        report(t, n, NOT_A_CONSTRUCTOR);
      }
    } else {
      ensureTyped(t, n);
    }
  } else {
    report(t, n, NOT_A_CONSTRUCTOR);
    ensureTyped(t, n);
  }
}

void tryMinimizeExits(Node n, int exitType, String labelName) {

  // Just an 'exit'.
  if (matchingExitNode(n, exitType, labelName)) {
    NodeUtil.removeChild(n.getParent(), n);
    compiler.reportCodeChange();
    return;
  }

  // Just an 'if'.
  if (n.isIf()) {
    Node ifBlock = n.getFirstChild().getNext();
    tryMinimizeExits(ifBlock, exitType, labelName);
    Node elseBlock = ifBlock.getNext();
    if (elseBlock != null) {
      tryMinimizeExits(elseBlock, exitType, labelName);
    }
    return;
  }

  // Just a 'try/catch/finally'.
  if (n.isTry()) {
    Node tryBlock = n.getFirstChild();
    tryMinimizeExits(tryBlock, exitType, labelName);
    Node allCatchNodes = NodeUtil.getCatchBlock(n);
    if (NodeUtil.hasCatchHandler(allCatchNodes)) {
      Preconditions.checkState(allCatchNodes.hasOneChild());
      Node catchNode = allCatchNodes.getFirstChild();
      Node catchCodeBlock = catchNode.getLastChild();
      tryMinimizeExits(catchCodeBlock, exitType, labelName);
    }
    /* Don't try to minimize the exits of finally blocks, as this
     * can cause problems if it changes the completion type of the finally
     * block. See ECMA 262 Sections 8.9 & 12.14
     */
    if (NodeUtil.hasFinally(n)) {
      Node finallyBlock = n.getLastChild();
      tryMinimizeExits(finallyBlock, exitType, labelName);
    }
  }

  // Just a 'label'.
  if (n.isLabel()) {
    Node labelBlock = n.getLastChild();
    tryMinimizeExits(labelBlock, exitType, labelName);
  }

  // TODO(johnlenz): The last case of SWITCH statement?

  // The rest assumes a block with at least one child, bail on anything else.
  if (!n.isBlock() || n.getLastChild() == null) {
    return;
  }

  // Multiple if-exits can be converted in a single pass.
  // Convert "if (blah) break;  if (blah2) break; other_stmt;" to
  // become "if (blah); else { if (blah2); else { other_stmt; } }"
  // which will get converted to "if (!blah && !blah2) { other_stmt; }".
  for (Node c : n.children()) {

    // An 'if' block to process below.
    if (c.isIf()) {
      Node ifTree = c;
      Node trueBlock, falseBlock;

      // First, the true condition block.
      trueBlock = ifTree.getFirstChild().getNext();
      falseBlock = trueBlock.getNext();
      tryMinimizeIfBlockExits(trueBlock, falseBlock,
          ifTree, exitType, labelName);

      // Now the else block.
      // The if blocks may have changed, get them again.
      trueBlock = ifTree.getFirstChild().getNext();
      falseBlock = trueBlock.getNext();
      if (falseBlock != null) {
        tryMinimizeIfBlockExits(falseBlock, trueBlock,
            ifTree, exitType, labelName);
      }
    }

    if (c == n.getLastChild()) {
      break;
    }
  }

  // Now try to minimize the exits of the last child, if it is removed
  // look at what has become the last child.
  for (Node c = n.getLastChild(); c != null; c = n.getLastChild()) {
    tryMinimizeExits(c, exitType, labelName);
    // If the node is still the last child, we are done.
    if (c == n.getLastChild()) {
      break;
    }
  }
}

private void tryRemoveUnconditionalBranching(Node n) {
  /*
   * For each unconditional branching control flow node, check to see
   * if the ControlFlowAnalysis.computeFollowNode of that node is same as
   * the branching target. If it is, the branch node is safe to be removed.
   *
   * This is not as clever as MinimizeExitPoints because it doesn't do any
   * if-else conversion but it handles more complicated switch statements
   * much more nicely.
   */

  // If n is null the target is the end of the function, nothing to do.
  if (n == null) {
     return;
  }

  DiGraphNode<Node, Branch> gNode = cfg.getDirectedGraphNode(n);

  if (gNode == null) {
    return;
  }

  switch (n.getType()) {
    case Token.RETURN:
      if (n.hasChildren()) {
        break;
      }
    case Token.BREAK:
    case Token.CONTINUE:
      // We are looking for a control flow changing statement that always
      // branches to the same node. If after removing it control still
      // branches to the same node, it is safe to remove.
      List<DiGraphEdge<Node, Branch>> outEdges = gNode.getOutEdges();
      if (outEdges.size() == 1 &&
          // If there is a next node, this jump is not useless.
          (n.getNext() == null || n.getNext().isFunction())) {

        Preconditions.checkState(
            outEdges.get(0).getValue() == Branch.UNCOND);
        Node fallThrough = computeFollowing(n);
        Node nextCfgNode = outEdges.get(0).getDestination().getValue();
        if (nextCfgNode == fallThrough) {
          removeNode(n);
        }
      }
      break;
    default:
      break;
  }
}

static boolean isSimpleNumber(String s) {
  int len = s.length();
  for (int index = 0; index < len; index++) {
    char c = s.charAt(index);
    if (c < '0' || c > '9') {
      return false;
    }
  }
  return len > 0 && (s.charAt(0) != '0' || len == 1);
}

private void annotateCalls(Node n) {
  Preconditions.checkState(n.isCall());

  // Keep track of of the "this" context of a call.  A call without an
  // explicit "this" is a free call.
  Node first = n.getFirstChild();

  // ignore cast nodes.

  if (!NodeUtil.isGet(first)) {
    n.putBooleanProp(Node.FREE_CALL, true);
  }

  // Keep track of the context in which eval is called. It is important
  // to distinguish between "(0, eval)()" and "eval()".
  if (first.isName() &&
      "eval".equals(first.getString())) {
    first.putBooleanProp(Node.DIRECT_EVAL, true);
  }

  // Check if the function is being cast and remove the cast
  if (first.isCast()) {
    Node target = first.getFirstChild();
    n.replaceChild(first, target);
    n.mutateType(target.getType());
  }
}

private void inlineAliases(GlobalNamespace namespace) {
  // Invariant: All the names in the worklist meet condition (a).
  Deque<Name> workList = new ArrayDeque<Name>(namespace.getNameForest());
  while (!workList.isEmpty()) {
    Name name = workList.pop();

    // Don't attempt to inline a getter or setter property as a variable.
    if (name.type == Name.Type.GET || name.type == Name.Type.SET) {
      continue;
    }

    if (name.globalSets == 1 && name.localSets == 0 &&
        name.aliasingGets > 0) {
      // {@code name} meets condition (b). Find all of its local aliases
      // and try to inline them.
      List<Ref> refs = Lists.newArrayList(name.getRefs());
      for (Ref ref : refs) {
        if (ref.type == Type.ALIASING_GET && ref.scope.isLocal()) {
          // {@code name} meets condition (c). Try to inline it.
          if (inlineAliasIfPossible(ref, namespace)) {
            name.removeRef(ref);
          }
        }
      }
    }

    // Check if {@code name} has any aliases left after the
    // local-alias-inlining above.
    if ((name.type == Name.Type.OBJECTLIT ||
         name.type == Name.Type.FUNCTION) &&
        name.aliasingGets == 0 && name.props != null) {
      // All of {@code name}'s children meet condition (a), so they can be
      // added to the worklist.
      workList.addAll(name.props);
    }
  }
}

public static boolean isJSIdentifier(String s) {
  int length = s.length();

  if (length == 0 ||
      !Character.isJavaIdentifierStart(s.charAt(0))) {
    return false;
  }

  for (int i = 1; i < length; i++) {
    if (
        !Character.isJavaIdentifierPart(s.charAt(i))) {
      return false;
    }
  }

  return true;
}

private String getRemainingJSDocLine() {
  String result = stream.getRemainingJSDocLine();
  if (result != null) {
    result = result.trim();
  }
  return result;
}

public void process(Node externs, Node root) {
  NodeTraversal.traverse(compiler, externs, new ProcessExterns());
  NodeTraversal.traverse(compiler, root, new ProcessProperties());

  Set<String> reservedNames =
      new HashSet<String>(externedNames.size() + quotedNames.size());
  reservedNames.addAll(externedNames);
  reservedNames.addAll(quotedNames);

  int numRenamedPropertyNames = 0;
  int numSkippedPropertyNames = 0;
  Set<Property> propsByFreq = new TreeSet<Property>(FREQUENCY_COMPARATOR);
  for (Property p : propertyMap.values()) {
    if (!p.skipAmbiguating) {
      ++numRenamedPropertyNames;
      computeRelatedTypes(p.type);
      propsByFreq.add(p);
    } else {
      ++numSkippedPropertyNames;
      reservedNames.add(p.oldName);
    }
  }

  PropertyGraph graph = new PropertyGraph(Lists.newLinkedList(propsByFreq));
  GraphColoring<Property, Void> coloring =
      new GreedyGraphColoring<Property, Void>(graph, FREQUENCY_COMPARATOR);
  int numNewPropertyNames = coloring.color();

  NameGenerator nameGen = new NameGenerator(
      reservedNames, "", reservedCharacters);
  for (int i = 0; i < numNewPropertyNames; ++i) {
    colorMap.put(i, nameGen.generateNextName());
  }
  for (GraphNode<Property, Void> node : graph.getNodes()) {
    node.getValue().newName = colorMap.get(node.getAnnotation().hashCode());
    renamingMap.put(node.getValue().oldName, node.getValue().newName);
  }

  // Update the string nodes.
  for (Node n : stringNodesToRename) {
    String oldName = n.getString();
    Property p = propertyMap.get(oldName);
    if (p != null && p.newName != null) {
      Preconditions.checkState(oldName.equals(p.oldName));
      if (!p.newName.equals(oldName)) {
        n.setString(p.newName);
        compiler.reportCodeChange();
      }
    }
  }

  logger.info("Collapsed " + numRenamedPropertyNames + " properties into "
              + numNewPropertyNames + " and skipped renaming "
              + numSkippedPropertyNames + " properties.");
}

public boolean isIndependentOf(Property prop) {
  if (typesRelatedToSet.intersects(prop.typesSet)) {
    return false;
  }
  return !getRelated(prop.type).intersects(typesInSet);
}

private class Property {
  final String oldName;
  JSType type;
  String newName;
  int numOccurrences;
  boolean skipAmbiguating;
  JSTypeBitSet typesSet = new JSTypeBitSet(intForType.size());

  Property(String name) {
    this.oldName = name;

    // Properties with this suffix are handled in RenameProperties.
    if (name.startsWith(SKIP_PREFIX)) {
      skipAmbiguating = true;
    }
  }

private void addNonUnionType(JSType newType) {
  if (skipAmbiguating || isInvalidatingType(newType)) {
    skipAmbiguating = true;
    return;
  }

  if (type == null) {
    type = newType;
  } else {
    type = type.getLeastSupertype(newType);
  }
  typesSet.set(getIntForType(newType));
}

private void replaceReferencesToThis(Node node, String name) {
  if (NodeUtil.isFunction(node)) {
    return;
  }

  for (Node child : node.children()) {
    if (NodeUtil.isThis(child)) {
      Node newName = Node.newString(Token.NAME, name);
      node.replaceChild(child, newName);
    } else {
      replaceReferencesToThis(child, name);
    }
  }
}

private void addPossibleSignature(String name, Node node, NodeTraversal t) {
  boolean signatureAdded = false;
  if (node.getType() == Token.FUNCTION) {
    // The node we're looking at is a function, so we can add it directly
    addSignature(name, node, t.getSourceName());
    signatureAdded = true;
  } else if (node.getType() == Token.NAME) {
    String functionName = node.getString();
    Scope.Var v = t.getScope().getVar(functionName);
    if (v == null) {
      if (compiler.isIdeMode()) {
        return;
      } else {
        throw new IllegalStateException(
            "VarCheck should have caught this undefined function");
      }
    }
    Node function = v.getInitialValue();
    if (function != null &&
        function.getType() == Token.FUNCTION) {
      addSignature(name, function, v.getInputName());
      signatureAdded = true;
    }
  }
  if (!signatureAdded) {
    nonMethodProperties.add(name);
  }
}

class MakeDeclaredNamesUnique
    implements NodeTraversal.ScopedCallback {

  private Deque<Renamer> nameStack = new ArrayDeque<Renamer>();
  private final Renamer rootRenamer;

  MakeDeclaredNamesUnique() {
    this.rootRenamer = new ContextualRenamer();
  }

private static String getOrginalNameInternal(String name, int index) {
  return name.substring(0, index);
}

private static String getNameSuffix(String name, int index) {
  return name.substring(
      index + ContextualRenamer.UNIQUE_ID_SEPARATOR.length(),
      name.length());
}

public void visit(NodeTraversal t, Node node, Node parent) {
  if (node.getType() == Token.NAME) {
    String oldName = node.getString();
    if (containsSeparator(oldName)) {
      Scope scope = t.getScope();
      Var var = t.getScope().getVar(oldName);
      if (var == null || var.isGlobal()) {
    return;
  }

      if (nameMap.containsKey(var)) {
        node.setString(nameMap.get(var));
      } else {
        int index = indexOfSeparator(oldName);
        String newName = getOrginalNameInternal(oldName, index);
        String suffix = getNameSuffix(oldName, index);

  // Merge any names that were referenced but not declared in the current
  // scope.
  // If there isn't anything left in the stack we will be going into the
  // global scope: don't try to build a set of referenced names for the
  // global scope.
        boolean recurseScopes = false;
        if (!suffix.matches("\\d+")) {
          recurseScopes = true;
        }

/**
 * For the Var declared in the current scope determine if it is possible
 * to revert the name to its orginal form without conflicting with other
 * values.
 */
    // Check if the new name is valid and if it would cause conflicts.
        if (var.scope.isDeclared(newName, recurseScopes) ||
            !TokenStream.isJSIdentifier(newName)) {
          newName = oldName;
        } else {
          var.scope.declare(newName, var.nameNode, null, null);
      // Adding a reference to the new name to prevent either the parent
      // scopes or the current scope renaming another var to this new name.
          Node parentNode = var.getParentNode();
          if (parentNode.getType() == Token.FUNCTION &&
              parentNode == var.scope.getRootNode()) {
            var.getNameNode().setString(newName);
          }
          node.setString(newName);
      compiler.reportCodeChange();
    }

        nameMap.put(var, newName);

  }

    // Add all referenced names to the set so it is possible to check for
    // conflicts.
    // Store only references to candidate names in the node map.
    }
  }
}

public void addDeclaredName(String name) {
    if (global) {
      reserveName(name);
    } else {
      // It hasn't been declared locally yet, so increment the count.
      if (!declarations.containsKey(name)) {
        int id = incrementNameCount(name);
        String newName = null;
        if (id != 0) {
          newName = getUniqueName(name, id);
      }
      declarations.put(name, newName);
    }
  }
}

public void addDeclaredName(String name) {
  if (!declarations.containsKey(name)) {
    declarations.put(name, getUniqueName(name));
  }
}

private FlowScope traverseName(Node n, FlowScope scope) {
  String varName = n.getString();
  Node value = n.getFirstChild();
  JSType type = n.getJSType();
  if (value != null) {
    scope = traverse(value, scope);
    updateScopeForTypeChange(scope, n, n.getJSType() /* could be null */,
        getJSType(value));
    return scope;
  } else {
    StaticSlot<JSType> var = scope.getSlot(varName);
    if (var != null &&
        !(var.isTypeInferred() && unflowableVarNames.contains(varName))) {
      // There are two situations where we don't want to use type information
      // from the scope, even if we have it.

      // 1) The var is escaped in a weird way, e.g.,
      // function f() { var x = 3; function g() { x = null } (x); }

      // 2) We're reading type information from another scope for an
      // inferred variable.
      // var t = null; function f() { (t); }

        type = var.getType();
        if (type == null) {
          type = getNativeType(UNKNOWN_TYPE);
      }
    }
  }
  n.setJSType(type);
  return scope;
}

private FlowScope traverseName(Node n, FlowScope scope) {
  String varName = n.getString();
  Node value = n.getFirstChild();
  JSType type = n.getJSType();
  if (value != null) {
    scope = traverse(value, scope);
    updateScopeForTypeChange(scope, n, n.getJSType() /* could be null */,
        getJSType(value));
    return scope;
  } else {
    StaticSlot<JSType> var = scope.getSlot(varName);
    if (var != null &&
        !(var.isTypeInferred() && unflowableVarNames.contains(varName))) {
      // There are two situations where we don't want to use type information
      // from the scope, even if we have it.

      // 1) The var is escaped in a weird way, e.g.,
      // function f() { var x = 3; function g() { x = null } (x); }

      // 2) We're reading type information from another scope for an
      // inferred variable.
      // var t = null; function f() { (t); }

        type = var.getType();
        if (type == null) {
          type = getNativeType(UNKNOWN_TYPE);
      }
    }
  }
  n.setJSType(type);
  return scope;
}

public void visit(NodeTraversal t, Node n, Node parent) {
  switch (n.getType()) {
    case Token.WHILE:
      if (CONVERT_WHILE_TO_FOR) {
        Node expr = n.getFirstChild();
        n.setType(Token.FOR);
        n.addChildBefore(new Node(Token.EMPTY), expr);
        n.addChildAfter(new Node(Token.EMPTY), expr);
        reportCodeChange("WHILE node");
      }
      break;

  }
}

public void visit(NodeTraversal t, Node n, Node parent) {
  switch (n.getType()) {
    case Token.FOR:
      if (CONVERT_FOR_TO_WHILE) {
        Node expr = n.getFirstChild();
        n.setType(Token.WHILE);
        n.addChildBefore(new Node(Token.EMPTY), expr);
        n.addChildAfter(new Node(Token.EMPTY), expr);
        reportCodeChange("FOR node");
      }
      break;

  }
}

Node getNodeForCodeInsertion(JSModule module) {
  if (module == null) {
    if (inputs.length == 0) {
      throw new IllegalStateException("No inputs");
    }

    return inputs[0].getAstRoot(this);
  }

  List<CompilerInput> inputs = module.getInputs();
  if (inputs.size() > 0) {
    return inputs.get(0).getAstRoot(this);
  }
  for (JSModule m : getModuleGraph().getTransitiveDepsDeepestFirst(module)) {
    inputs = m.getInputs();
    if (inputs.size() > 0) {
      return inputs.get(0).getAstRoot(this);
    }
  }
  throw new IllegalStateException("Root module has no inputs");
}

static boolean canBeSideEffected(Node n, Set<String> knownConstants) {
  switch (n.getType()) {
    case Token.CALL:
    case Token.NEW:
      // Function calls or constructor can reference changed values.
      // TODO(johnlenz): Add some mechanism for determining that functions
      // are unaffected by side effects.
      return true;
    case Token.NAME:
      // Non-constant names values may have been changed.
      return !NodeUtil.isConstantName(n)
          && !knownConstants.contains(n.getString());

    // Properties on constant NAMEs can still be side-effected.
    case Token.GETPROP:
    case Token.GETELEM:
      return true;

      // Anonymous functions definitions are not changed by side-effects,
      // and named functions are not part of expressions.
  }

  for (Node c = n.getFirstChild(); c != null; c = c.getNext()) {
    if (canBeSideEffected(c, knownConstants)) {
      return true;
    }
  }

  return false;
}

public void enterScope(NodeTraversal t) {
  // TODO(user): We CAN do this in the global scope, just need to be
  // careful when something is exported. Liveness uses bit-vector for live
  // sets so I don't see compilation time will be a problem for running this
  // pass in the global scope.
  Scope scope = t.getScope();
  if (scope.isGlobal()) {
    return;
  }
  ControlFlowGraph<Node> cfg = t.getControlFlowGraph();

  LiveVariablesAnalysis liveness =
      new LiveVariablesAnalysis(cfg, scope, compiler);
  // If the function has exactly 2 params, mark them as escaped. This is
  // a work-around for an IE bug where it throws an exception if you
  // write to the parameters of the callback in a sort(). See:
  // http://code.google.com/p/closure-compiler/issues/detail?id=58
  liveness.analyze();

  UndiGraph<Var, Void> interferenceGraph =
      computeVariableNamesInterferenceGraph(
          t, cfg, liveness.getEscapedLocals());

  GraphColoring<Var, Void> coloring =
      new GreedyGraphColoring<Var, Void>(interferenceGraph,
          coloringTieBreaker);

  coloring.color();
  colorings.push(coloring);
}

private void initOptionsFromFlags(CompilerOptions options) {
  DiagnosticGroups diagnosticGroups = getDiagnosticGroups();

  diagnosticGroups.setWarningLevels(
      options, config.jscompError, CheckLevel.ERROR);
  diagnosticGroups.setWarningLevels(
      options, config.jscompWarning, CheckLevel.WARNING);
  diagnosticGroups.setWarningLevels(
      options, config.jscompOff, CheckLevel.OFF);

  createDefineReplacements(config.define, options);
}

private static void createDefineReplacements(List<String> definitions,
    CompilerOptions options) {
  // Parse the definitions
  for (String override : definitions) {
    String[] assignment = override.split("=", 2);
    String defName = assignment[0];

    if (defName.length() > 0) {
      if (assignment.length == 1) {
        options.setDefineToBooleanLiteral(defName, true);
        continue;
      } else {
        String defValue = assignment[1];

        if (defValue.equals("true")) {
          options.setDefineToBooleanLiteral(defName, true);
          continue;
        } else if (defValue.equals("false")) {
          options.setDefineToBooleanLiteral(defName, false);
          continue;
        } else if (defValue.length() > 1
            && ((defValue.charAt(0) == '\'' &&
                defValue.charAt(defValue.length() - 1) == '\'')
          )) {
          // If the value starts and ends with a single quote,
          // we assume that it's a string.
          String maybeStringVal =
              defValue.substring(1, defValue.length() - 1);
          if (maybeStringVal.indexOf(defValue.charAt(0)) == -1) {
            options.setDefineToStringLiteral(defName, maybeStringVal);
            continue;
          }
        } else {
          try {
            options.setDefineToDoubleLiteral(defName,
                Double.parseDouble(defValue));
            continue;
          } catch (NumberFormatException e) {
            // do nothing, it will be caught at the end
          }
        }
      }
    }

    throw new RuntimeException(
        "--define flag syntax invalid: " + override);
  }
}

private void trySimplify(Node parent, Node node) {
  if (node.getType() != Token.EXPR_RESULT) {
    return;
  }

  Node exprBody = node.getFirstChild();
  if (!NodeUtil.nodeTypeMayHaveSideEffects(exprBody)
  ) {
    changeProxy.replaceWith(parent, node, getSideEffectNodes(exprBody));
  }
}

