private void readObject(ObjectInputStream in) throws IOException, ClassNotFoundException {
    in.defaultReadObject();
    int size = in.readInt();
    buffer = new Object[size + 1];
    for (int i = 0; i < size; i++) {
        buffer[i] = in.readObject();
    }
    head = 0;
    tail = size;
}

private void writeObject(ObjectOutputStream out) throws IOException {
    out.defaultWriteObject();
    out.writeInt(size());
    for (Iterator it = iterator(); it.hasNext();) {
        out.writeObject(it.next());
    }
}

public boolean add(final Object obj) {
    if (obj == null) {
        throw new NullPointerException("Attempted to add null object to buffer");
    }

    if (size() + 1 >= buffer.length) {
        // copy contents to a new buffer array
        Object[] tmp = new Object[((buffer.length - 1) * 2) + 1];
        int j = 0;
        // move head to element zero in the new array
        for (int i = head; i != tail;) {
            tmp[j] = buffer[i];
            buffer[i] = null;

            j++;
            i = increment(i);
        }
        buffer = tmp;
        head = 0;
        tail = j;
    }

    buffer[tail] = obj;
    tail = increment(tail);
    return true;
}

public Object get() {
    if (isEmpty()) {
        throw new BufferUnderflowException("The buffer is already empty");
    }

    return buffer[head];
}

public Object remove() {
    if (isEmpty()) {
        throw new BufferUnderflowException("The buffer is already empty");
    }

    Object element = buffer[head];
    if (element != null) {
        buffer[head] = null;
        head = increment(head);
    }
    return element;
}

private int increment(int index) {
    index++;
    if (index >= buffer.length) {
        index = 0;
    }
    return index;
}

private int decrement(int index) {
    index--;
    if (index < 0) {
        index = buffer.length - 1;
    }
    return index;
}

public Iterator iterator() {
    return new Iterator() {

        private int index = head;
        private int lastReturnedIndex = -1;

        public boolean hasNext() {
            return index != tail;
        }

        public Object next() {
            if (!hasNext()) {
                throw new NoSuchElementException();
            }
            lastReturnedIndex = index;
            index = increment(index);
            return buffer[lastReturnedIndex];
        }

        public void remove() {
            if (lastReturnedIndex == -1) {
                throw new IllegalStateException();
            }

            // First element can be removed quickly
            if (lastReturnedIndex == head) {
                UnboundedFifoBuffer.this.remove();
                lastReturnedIndex = -1;
                return;
            }

            // Other elements require us to shift the subsequent elements
            int i = increment(lastReturnedIndex);
            while (i != tail) {
                buffer[decrement(i)] = buffer[i];
                i = increment(i);
            }

            lastReturnedIndex = -1;
            tail = decrement(tail);
            buffer[tail] = null;
            index = decrement(index);
        }

    };
}

