    root.parent = null;
    root.left = root;
    root.right = null;
    root.predecessor = root;

    size = 0;
    incrementModCount();
}

public void clear() {
    root.key = null;
    root.bitIndex = -1;
    root.value = null;

    root.parent = null;
    root.left = root;
    root.right = null;
    root.predecessor = root;

    size = 0;
    incrementModCount();
}

public CpioArchiveEntry getNextCPIOEntry() throws IOException {
    ensureOpen();
    if (this.cpioEntry != null) {
        closeArchiveEntry();
    }
    CpioArchiveEntry entry = readNextEntry();
    if (entry != null) {
        this.cpioEntry = entry;
        this.written = 0;
    }
    return this.cpioEntry;
}

private CpioArchiveEntry readNextEntry() throws IOException {
    byte[] header = new byte[HEADER_SIZE];
    int bytesRead = readFully(header);
    if (bytesRead != HEADER_SIZE) {
        return null;
    }
    CpioArchiveEntry entry = new CpioArchiveEntry();
    entry.setFormat((short) ((header[0] & 0xFF) << 8 | (header[1] & 0xFF)));
    switch (entry.getFormat()) {
        case FORMAT_NEW:
        case FORMAT_NEW_CRC:
            entry.setInode(readAsciiLong(8, 16));
            entry.setMode(readAsciiLong(8, 16));
            entry.setUID(readAsciiLong(8, 16));
            entry.setGID(readAsciiLong(8, 16));
            entry.setNumberOfLinks(readAsciiLong(8, 16));
            entry.setTime(readAsciiLong(8, 16));
            entry.setSize(readAsciiLong(8, 16));
            entry.setDeviceMaj(readAsciiLong(8, 16));
            entry.setDeviceMin(readAsciiLong(8, 16));
            entry.setRemoteDeviceMaj(readAsciiLong(8, 16));
            entry.setRemoteDeviceMin(readAsciiLong(8, 16));
            entry.setName(readCString());
            entry.setChksum(readAsciiLong(8, 16));
            break;
        case FORMAT_OLD_ASCII:
            entry.setDevice(readAsciiLong(6, 8));
            entry.setInode(readAsciiLong(6, 8));
            entry.setMode(readAsciiLong(6, 8));
            entry.setUID(readAsciiLong(6, 8));
            entry.setGID(readAsciiLong(6, 8));
            entry.setNumberOfLinks(readAsciiLong(6, 8));
            entry.setRemoteDevice(readAsciiLong(6, 8));
            entry.setTime(readAsciiLong(11, 8));
            entry.setName(readCString());
            entry.setSize(readAsciiLong(11, 8));
            break;
        case FORMAT_OLD_BINARY:
            boolean swapHalfWord = true;
            entry.setDevice(readBinaryLong(2, swapHalfWord));
            entry.setInode(readBinaryLong(2, swapHalfWord));
            entry.setMode(readBinaryLong(2, swapHalfWord));
            entry.setUID(readBinaryLong(2, swapHalfWord));
            entry.setGID(readBinaryLong(2, swapHalfWord));
            entry.setNumberOfLinks(readBinaryLong(2, swapHalfWord));
            entry.setRemoteDevice(readBinaryLong(2, swapHalfWord));
            entry.setTime(readBinaryLong(4, swapHalfWord));
            entry.setName(readCString());
            entry.setSize(readBinaryLong(4, swapHalfWord));
            break;
    }
    return entry;
}

private int readFully(byte[] b) throws IOException {
    int offset = 0;
    while (offset < b.length) {
        int bytesRead = in.read(b, offset, b.length - offset);
        if (bytesRead == -1) {
            return offset;
        }
        offset += bytesRead;
    }
    return offset;
}

private long readAsciiLong(int length, int radix) throws IOException {
    byte[] bytes = new byte[length];
    int bytesRead = readFully(bytes);
    if (bytesRead != length) {
        throw new EOFException();
    }
    String str = new String(bytes, StandardCharsets.US_ASCII);
    return Long.parseLong(str, radix);
}

private long readBinaryLong(int length, boolean swapHalfWord) throws IOException {
    byte[] bytes = new byte[length];
    int bytesRead = readFully(bytes);
    if (bytesRead != length) {
        throw new EOFException();
    }
    if (swapHalfWord) {
        for (int i = 0; i < length; i += 2) {
            byte tmp = bytes[i];
            bytes[i] = bytes[i + 1];
            bytes[i + 1] = tmp;
        }
    }
    return CpioUtil.byteArray2long(bytes, length);
}

private String readCString() throws IOException {
    ByteArrayOutputStream baos = new ByteArrayOutputStream();
    int b;
    while ((b = in.read()) != 0) {
        baos.write(b);
    }
    return baos.toString(StandardCharsets.US_ASCII);
}

private void ensureOpen() throws IOException {
    if (this.closed) {
        throw new IOException("Stream closed");
    }
}

private void closeArchiveEntry() throws IOException {
    if (this.cpioEntry.getSize() != this.written) {
        throw new IOException("invalid entry size (expected "
                + this.cpioEntry.getSize() + " but got " + this.written
                + " bytes)");
    }
    if ((this.cpioEntry.getFormat() | FORMAT_NEW_MASK) == FORMAT_NEW_MASK) {
        pad(this.cpioEntry.getSize(), 4);
    } else if ((this.cpioEntry.getFormat() | FORMAT_OLD_BINARY) == FORMAT_OLD_BINARY) {
        pad(this.cpioEntry.getSize(), 2);
    }
    if ((this.cpioEntry.getFormat() | FORMAT_NEW_CRC) == FORMAT_NEW_CRC) {
        if (this.crc != this.cpioEntry.getChksum()) {
            throw new IOException("CRC Error");
        }
    }
    this.cpioEntry = null;
    this.crc = 0;
    this.written = 0;
}

private void pad(long count, int border) throws IOException {
    long skip = count % border;
    if (skip > 0) {
        byte tmp[] = new byte[(int) (border - skip)];
        out.write(tmp);
    }
}

private void writeHeader(CpioArchiveEntry e) throws IOException {
    switch (e.getFormat()) {
    case FORMAT_NEW:
        out.write(MAGIC_NEW.getBytes());
        writeNewEntry(e);
        break;
    case FORMAT_NEW_CRC:
        out.write(MAGIC_NEW_CRC.getBytes());
        writeNewEntry(e);
        break;
    case FORMAT_OLD_ASCII:
        out.write(MAGIC_OLD_ASCII.getBytes());
        writeOldAsciiEntry(e);
        break;
    case FORMAT_OLD_BINARY:
        boolean swapHalfWord = true;
        writeBinaryLong(MAGIC_OLD_BINARY, 2, swapHalfWord);
        writeOldBinaryEntry(e, swapHalfWord);
        break;
    }
}

private void writeNewEntry(CpioArchiveEntry entry) throws IOException {
    writeAsciiLong(entry.getInode(), 8, 16);
    writeAsciiLong(entry.getMode(), 8, 16);
    writeAsciiLong(entry.getUID(), 8, 16);
    writeAsciiLong(entry.getGID(), 8, 16);
    writeAsciiLong(entry.getNumberOfLinks(), 8, 16);
    writeAsciiLong(entry.getTime(), 8, 16);
    writeAsciiLong(entry.getSize(), 8, 16);
    writeAsciiLong(entry.getDeviceMaj(), 8, 16);
    writeAsciiLong(entry.getDeviceMin(), 8, 16);
    writeAsciiLong(entry.getRemoteDeviceMaj(), 8, 16);
    writeAsciiLong(entry.getRemoteDeviceMin(), 8, 16);
    writeAsciiLong(entry.getName().length() + 1, 8, 16);
    writeAsciiLong(entry.getChksum(), 8, 16);
    writeCString(entry.getName());
    pad(entry.getHeaderSize() + entry.getName().length() + 1, 4);
}

private void writeOldAsciiEntry(CpioArchiveEntry entry) throws IOException {
    writeAsciiLong(entry.getDevice(), 6, 8);
    writeAsciiLong(entry.getInode(), 6, 8);
    writeAsciiLong(entry.getMode(), 6, 8);
    writeAsciiLong(entry.getUID(), 6, 8);
    writeAsciiLong(entry.getGID(), 6, 8);
    writeAsciiLong(entry.getNumberOfLinks(), 6, 8);
    writeAsciiLong(entry.getRemoteDevice(), 6, 8);
    writeAsciiLong(entry.getTime(), 11, 8);
    writeAsciiLong(entry.getName().length() + 1, 6, 8);
    writeAsciiLong(entry.getSize(), 11, 8);
    writeCString(entry.getName());
}

public class TarArchiveOutputStream extends ArchiveOutputStream {
    /** Fail if a long file name is required in the archive. */
    public static final int LONGFILE_ERROR = 0;

    /** Long paths will be truncated in the archive. */
    public static final int LONGFILE_TRUNCATE = 1;

    /** GNU tar extensions are used to store long file names in the archive. */
    public static final int LONGFILE_GNU = 2;

    private long      currSize;
    private String    currName;
    private long      currBytes;
    private final byte[]    recordBuf;
    private int       assemLen;
    private final byte[]    assemBuf;
    protected final TarBuffer buffer;
    private int       longFileMode = LONGFILE_ERROR;

    private boolean closed = false;

    /* Indicates if putArchiveEntry has been called without closeArchiveEntry */

    private final OutputStream out;

    /**
     * Constructor for TarInputStream.
     * @param os the output stream to use
     */
    public TarArchiveOutputStream(OutputStream os) {
        this(os, TarBuffer.DEFAULT_BLKSIZE, TarBuffer.DEFAULT_RCDSIZE);
    }

    @Override
    public void close() throws IOException {
        finish();
        out.close();
    }

    @Override
    public void finish() throws IOException {
        if (!closed) {
            // Finish writing the archive entries
            // ...
            closed = true;
        }
    }

public void finish() throws IOException {
    ensureOpen();

    if (this.finished) {
        return;
    }
    if (this.entry != null) {
        throw new IOException("This archives contains unclosed entries.");
    }
    this.entry = new CpioArchiveEntry(this.entryFormat);
    this.entry.setName(CPIO_TRAILER);
    this.entry.setNumberOfLinks(1);
    writeHeader(this.entry);
    closeArchiveEntry();
}

public void finish() throws IOException {
    if(haveUnclosedEntry) {
        throw new IOException("This archives contains unclosed entries.");
    }
    writeEOFRecord();
    writeEOFRecord();
}

public void finish() throws IOException {
    if(entry != null) {
        throw new IOException("This archives contains unclosed entries.");
    }

    cdOffset = written;
    for (Iterator i = entries.iterator(); i.hasNext(); ) {
        writeCentralFileHeader((ZipArchiveEntry) i.next());
    }
    cdLength = written - cdOffset;
    writeCentralDirectoryEnd();
    offsets.clear();
    entries.clear();
}

