/**
 * Skips the padding zeros written after the TRAILER!!! entry.
 */
private void skipRemainderOfLastBlock() throws IOException {
    long readFromLastBlock = getBytesRead() % blockSize;
    long remainingBytes = readFromLastBlock == 0 ? 0
        : blockSize - readFromLastBlock;
    while (remainingBytes > 0) {
        long skipped = skip(blockSize - readFromLastBlock);
        if (skipped <= 0) {
            break;
        }
        remainingBytes -= skipped;
    }
}

/**
 * Checks if the signature matches one of the following magic values:
 * 
 * Strings:
 *
 * "070701" - MAGIC_NEW
 * "070702" - MAGIC_NEW_CRC
 * "070707" - MAGIC_OLD_ASCII
 * 
 * Octal Binary value:
 * 
 * 070707 - MAGIC_OLD_BINARY (held as a short) = 0x71C7 or 0xC771
 */
public static boolean matches(byte[] signature, int length) {
    if (length < 6) {
        return false;
    }

    // Check binary values
    if (signature[0] == 0x71 && (signature[1] & 0xFF) == 0xc7) {
        return true;
    }
    if (signature[1] == 0x71 && (signature[0] & 0xFF) == 0xc7) {
        return true;
    }

    // Check Ascii (String) values
    // 3037 3037 30nn
    if (signature[0] != 0x30) {
        return false;
    }
    if (signature[1] != 0x37) {
        return false;
    }
    if (signature[2] != 0x30) {
        return false;
    }
    if (signature[3] != 0x37) {
        return false;
    }
    if (signature[4] != 0x30) {
        return false;
    }
    // Check last byte
    if (signature[5] == 0x31) {
        return true;
    }
    if (signature[5] == 0x32) {
        return true;
    }
    if (signature[5] == 0x37) {
        return true;
    }

    return false;
}

private void writeUint64(final DataOutput header, long value) throws IOException {
    int firstByte = 0;
    int mask = 0x80;
    int i;
    for (i = 0; i < 8; i++) {
        if (value < ((1L << ( 7  * (i + 1))))) {
            firstByte |= (value >>> (8 * i));
            break;
        }
        firstByte |= mask;
        mask >>>= 1;
    }
    header.write(firstByte);
    for (; i > 0; i--) {
        header.write((int) (0xff & value));
        value >>>= 8;
    }
}

private void writeBits(final DataOutput header, final BitSet bits, final int length) throws IOException {
    int cache = 0;
    int shift = 7;
    for (int i = 0; i < length; i++) {
        cache |= ((bits.get(i) ? 1 : 0) << shift);
        --shift;
        if (shift == 0) {
            header.write(cache);
            shift = 7;
            cache = 0;
        }
    }
    if (length > 0 && shift > 0) {
        header.write(cache);
    }
}

private class OutputStreamWrapper extends OutputStream {
