    public void write(final byte[] b) throws IOException {
        OutputStreamWrapper.this.write(b, 0, b.length);
    }

    @Override
    public void write(final byte[] b, final int off, final int len)
        throws IOException {
        file.write(b, off, len);
        compressedCrc32.update(b, off, len);
        fileBytesWritten += len;
    }

    @Override
    public void flush() throws IOException {
        // no reason to flush a RandomAccessFile
    }

    @Override
    public void close() throws IOException {
        // the file will be closed by the containing class's close method
    }
}

private int read0() throws IOException {
    if (this.in == null) {
        return -1;
    }

    int ch = this.in.read();
    if (ch == -1) {
        return -1;
    }

    this.bsBuff = (this.bsBuff << 8) | ch;
    this.bsLive += 8;

    if (this.bsLive >= 24) {
        this.currentChar = this.bsBuff >> (this.bsLive - 24);
        this.bsLive -= 24;
    } else {
        this.currentChar = -1;
    }

    return this.currentChar;
}

static class LZMADecoder extends CoderBase {
    @Override
    InputStream decode(final InputStream in, final Coder coder,
            byte[] password) throws IOException {
        byte propsByte = coder.properties[0];
        long dictSize = coder.properties[1];
        for (int i = 1; i < 4; i++) {
            dictSize |= (coder.properties[i + 1] << (8 * i));
        }
        if (dictSize > LZMAInputStream.DICT_SIZE_MAX) {
            throw new IOException("Dictionary larger than 4GiB maximum size");
        }
        return new LZMAInputStream(in, -1, propsByte, (int) dictSize);
    }

