public ZipArchiveEntry getNextZipEntry() throws IOException {
    if (current.entry == null) {
        return null;
    }
    if (current.entry.getCompressedSize() == ArchiveEntry.SIZE_UNKNOWN) {
        throw new IOException("Compressed size is unknown for bzip2, implode, etc.");
    }
    if (current.entry.getMethod() == ZipMethod.UNSHRINKING.getCode()) {
        current.in = new UnshrinkingInputStream(new BoundedInputStream(in, current.entry.getCompressedSize()));
    } else if (current.entry.getMethod() == ZipMethod.IMPLODING.getCode()) {
        current.in = new ExplodingInputStream(
                current.entry.getGeneralPurposeBit().getSlidingDictionarySize(),
                current.entry.getGeneralPurposeBit().getNumberOfShannonFanoTrees(),
                new BoundedInputStream(in, current.entry.getCompressedSize()));
    } else if (current.entry.getMethod() == ZipMethod.BZIP2.getCode()) {
        current.in = new BZip2CompressorInputStream(new BoundedInputStream(in, current.entry.getCompressedSize()));
    }
    current.entry = null;
    return current.entry;
}

@Override
public int read() throws IOException {
    int current = super.read();
    if (current == '\n' || (current == '\r' && lastChar != '\r')) {
        lineCounter++;
    }
    lastChar = current;
    return lastChar;
}

@Override
public int read(char[] buf, int offset, int length) throws IOException {
    if (length == 0) {
        return 0;
    }

    int len = super.read(buf, offset, length);

    if (len > 0) {
        for (int i = offset; i < offset + len; i++) {
            char ch = buf[i];
            if (ch == '\n' || (ch == '\r' && (i > 0 ? buf[i-1] : lastChar) != '\r')) {
                lineCounter++;                        
            }
        }

        lastChar = buf[offset + len - 1];

    } else if (len == -1) {
        lastChar = END_OF_STREAM;
    }

    return len;
}

@Override
public String readLine() throws IOException {
    String line = super.readLine();

    if (line != null) {
        if (line.length() > 0) {
            lastChar = line.charAt(line.length() - 1);
        }
        lineCounter++;
    } else {
        lastChar = END_OF_STREAM;
    }

    return line;
}

public String get(final String name) {
    if (mapping == null) {
        throw new IllegalStateException(
                "No header mapping was specified, the record values can't be accessed by name");
    }
    final Integer index = mapping.get(name);
    if (index == null || index >= values.length) {
        throw new IllegalArgumentException("Header name '" + name + "' does not correspond to a value in the record");
    }
    return index != null ? values[index.intValue()] : null;
}

/**
 * Handle an escape sequence.
 * The current character must be the escape character.
 * On return, the next character is available by calling {@link ExtendedBufferedReader#getLastChar()}
 * on the input stream.
 * 
 * @return the unescaped character (as an int) or {@link END_OF_STREAM} if char following the escape is invalid. 
 * @throws IOException if there is a problem reading the stream or the end of stream is detected: 
 * the escape character is not allowed at end of stream
 */
int readEscape() throws IOException {
    // the escape char has just been read (normally a backslash)
    final int c = in.read();
    switch (c) {
    case 'r':
        return CR;
    case 'n':
        return LF;
    case 't':
        return TAB;
    case 'b':
        return BACKSPACE;
    case 'f':
        return FF;
    case CR:
    case LF:
    case FF: // TODO is this correct?
    case TAB: // TODO is this correct? Do tabs need to be escaped?
    case BACKSPACE: // TODO is this correct?
        return c;
    case END_OF_STREAM:
        throw new IOException("EOF whilst processing escape sequence");
    default:
        // Now check for meta-characters
        if (c == 'u') {
            // Handle Unicode escape sequence
            int unicodeValue = 0;
            for (int i = 0; i < 4; i++) {
                int hexValue = Character.digit((char) in.read(), 16);
                if (hexValue == -1) {
                    throw new IOException("Invalid Unicode escape sequence");
                }
                unicodeValue = (unicodeValue << 4) | hexValue;
            }
            return unicodeValue;
        }
        // indicate unexpected char - available from in.getLastChar()
        return c;
    }
}

