            if (c == LF) {
                c = 'n';
            } else if (c == CR) {
                c = 'r';
            }

            out.append(escape);
            out.append(c);

            start = pos + 1; // start on the current char after this one
        }

        pos++;
    }

    // write last segment
    if (pos > start) {
        out.append(value, start, pos);
    }
}

