public Map<String, String> toMap() {
    final Map<String, String> map = new HashMap<>(values.length);
    if (mapping != null) {
        for (final Entry<String, Integer> entry : mapping.entrySet()) {
            final int col = entry.getValue().intValue();
            if (col < values.length) {
                map.put(entry.getKey(), values[col]);
            }
        }
    }
    return map;
}

private Map<String, Integer> initializeHeader() throws IOException {
    Map<String, Integer> hdrMap = null;
    final String[] formatHeader = this.format.getHeader();
    if (formatHeader != null) {
        hdrMap = new LinkedHashMap<String, Integer>();

        String[] header = null;
        if (formatHeader.length == 0) {
            // read the header from the first line of the file
            final CSVRecord nextRecord = this.nextRecord();
            if (nextRecord != null) {
                header = nextRecord.values();
            }
        } else {
            if (this.format.getSkipHeaderRecord()) {
                this.nextRecord();
            }
            header = formatHeader;
        }

        // build the name to index mappings
        if (header != null) {
            for (int i = 0; i < header.length; i++) {
                String columnName = header[i];
                if (hdrMap.containsKey(columnName)) {
                    throw new IOException("Duplicate column name found: " + columnName);
                }
                hdrMap.put(columnName, Integer.valueOf(i));
            }
        }
    }
    return hdrMap;
}

public static final CSVFormat newFormat(final char delimiter) {
    if (isLineBreak(delimiter)) {
        throw new IllegalArgumentException("The delimiter cannot be a line break");
    }
    return new CSVFormat(delimiter, null, null, null, null, false, false, null, null, null, false);
}

private CSVFormat(final char delimiter, final Character quoteChar,
        final Quote quotePolicy, final Character commentStart,
        final Character escape, final boolean ignoreSurroundingSpaces,
        final boolean ignoreEmptyLines, final String recordSeparator,
        final String nullString, final String[] header, final boolean skipHeaderRecord) {
    if (isLineBreak(delimiter)) {
        throw new IllegalArgumentException("The delimiter cannot be a line break");
    }
    this.delimiter = delimiter;
    this.quoteChar = quoteChar;
    this.quotePolicy = quotePolicy;
    this.commentStart = commentStart;
    this.escape = escape;
    this.ignoreSurroundingSpaces = ignoreSurroundingSpaces;
    this.ignoreEmptyLines = ignoreEmptyLines;
    this.recordSeparator = recordSeparator;
    this.nullString = nullString;
    if (header == null) {
        this.header = null;
    } else {
        Set<String> set = new HashSet<String>(header.length);
        set.addAll(Arrays.asList(header));
        if (set.size() != header.length) {
            throw new IllegalArgumentException("The header contains duplicate names: " + Arrays.toString(header));
        }
        this.header = header.clone();
    }
    this.skipHeaderRecord = skipHeaderRecord;
}

public Map<String, String> toMap() {
    if (mapping == null) {
        return new HashMap<String, String>();
    }
    return putIn(new HashMap<String, String>(values.length));
}

public CSVPrinter(final Appendable out, final CSVFormat format) throws IOException {
    Assertions.notNull(out, "out");
    Assertions.notNull(format, "format");

    this.out = out;
    this.format = format;
    this.format.validate();
    // Add header printing logic here
    if (format.getHeader() != null) {
        printRecord(format.getHeader());
    }
}

public CSVParser(final Reader reader, final CSVFormat format) throws IOException {
    Assertions.notNull(reader, "reader");
    Assertions.notNull(format, "format");

    this.format = format;
    this.lexer = new Lexer(format, new ExtendedBufferedReader(reader));
    this.headerMap = this.initializeHeader();
}

private void addRecordValue() {
    final String input = this.reusableToken.content.toString();
    final String nullString = this.format.getNullString();
    if (nullString == null) {
        this.record.add(input);
    } else {
        this.record.add(input.equalsIgnoreCase(nullString) ? null : input);
    }
}

/**
