public static final TypeAdapter<Vehicle> VEHICLE = new TypeAdapter<Vehicle>() {
    @Override
    public Vehicle read(JsonReader in) throws IOException {
        if (in.peek() == JsonToken.NULL) {
            in.nextNull();
            return null;
        }

        // Deserialize the JSON string to a JsonObject
        JsonObject jsonObject = in.beginObject();
        String type = jsonObject.get("type").getAsString();

        // Create the appropriate object based on the type
        Vehicle vehicle = null;
        if ("Car".equals(type)) {
            vehicle = new Car();
        } else if ("Truck".equals(type)) {
            vehicle = new Truck();
        }

        // Read the properties of the vehicle
        vehicle.readFromJson(jsonObject);
        in.endObject();
        return vehicle;
    }

    @Override
    public void write(JsonWriter out, Vehicle value) throws IOException {
        if (value == null) {
            out.nullValue();
            return;
        }

        // Write the type of the vehicle
        out.beginObject();
        out.name("type");
        out.value(value.getType());

        // Write the properties of the vehicle
        value.writeToJson(out);
        out.endObject();
    }
};

public static final TypeAdapterFactory VEHICLE_FACTORY = newFactoryForMultipleTypes(Vehicle.class, Car.class, Truck.class, VEHICLE);

/**
 * Returns true if the current array or object has another element.
 */
public boolean hasNext() throws IOException {
  int p = peeked;
  if (p == PEEKED_NONE) {
    p = doPeek();
  }
  return p != PEEKED_END_OBJECT && p != PEEKED_END_ARRAY;
}

/**
 * Returns the type of the next token without consuming it.
 */
public JsonToken peek() throws IOException {
  int p = peeked;
  if (p == PEEKED_NONE) {
    p = doPeek();
  }

  switch (p) {
  case PEEKED_BEGIN_OBJECT:
    return JsonToken.BEGIN_OBJECT;
  case PEEKED_END_OBJECT:
    return JsonToken.END_OBJECT;
  case PEEKED_BEGIN_ARRAY:
    return JsonToken.BEGIN_ARRAY;
  case PEEKED_END_ARRAY:
    return JsonToken.END_ARRAY;
  case PEEKED_SINGLE_QUOTED_NAME:
  case PEEKED_DOUBLE_QUOTED_NAME:
  case PEEKED_UNQUOTED_NAME:
    return JsonToken.NAME;
  case PEEKED_TRUE:
  case PEEKED_FALSE:
    return JsonToken.BOOLEAN;
  case PEEKED_NULL:
    return JsonToken.NULL;
  case PEEKED_SINGLE_QUOTED:
  case PEEKED_DOUBLE_QUOTED:
  case PEEKED_UNQUOTED:
  case PEEKED_BUFFERED:
    return JsonToken.STRING;
  case PEEKED_LONG:
  case PEEKED_NUMBER:
    return JsonToken.NUMBER;
  case PEEKED_EOF:
    return JsonToken.END_DOCUMENT;
  default:
    throw new AssertionError();
  }
}

/**
 * Encodes the property name.
 *
 * @param name the name of the forthcoming value. May not be null.
 * @return this writer.
 */
public JsonWriter name(String name) throws IOException {
  if (name == null) {
    throw new NullPointerException("name == null");
  }
  if (deferredName != null) {
    throw new IllegalStateException();
  }
  if (stackSize == 0) {
    throw new IllegalStateException("JsonWriter is closed.");
  }
  deferredName = name;
  return this;
}

/**
 * Encodes {@code value}.
 *
 * @param value the literal string value, or null to encode a null literal.
 * @return this writer.
 */
public JsonWriter value(String value) throws IOException {
  if (value == null) {
    return nullValue();
  }
  writeDeferredName();
  beforeValue(false);
  string(value);
  return this;
}

    public static Date parse(String date, ParsePosition pos) throws ParseException {
        Exception fail = null;
        try {
            int offset = pos.getIndex();

            // extract year
            int year = parseInt(date, offset, offset += 4);
            if (checkOffset(date, offset, '-')) {
                offset += 1;
            }

            // extract month
            int month = parseInt(date, offset, offset += 2);
            if (checkOffset(date, offset, '-')) {
                offset += 1;
            }

            // extract day
            int day = parseInt(date, offset, offset += 2);
            // default time value
            int hour = 0;
            int minutes = 0;
            int seconds = 0;
            int milliseconds = 0; // always use 0 otherwise returned date will include millis of current time

            // if the value has no time component (and no time zone), we are done
            boolean hasT = checkOffset(date, offset, 'T');

            if (!hasT && (date.length() <= offset)) {
                Calendar calendar = new GregorianCalendar(year, month - 1, day);

                pos.setIndex(offset);
                return calendar.getTime();
            }

            if (hasT) {

                // extract hours, minutes, seconds and milliseconds
                hour = parseInt(date, offset += 1, offset += 2);
                if (checkOffset(date, offset, ':')) {
                    offset += 1;
                }

                minutes = parseInt(date, offset, offset += 2);
                if (checkOffset(date, offset, ':')) {
                    offset += 1;
                }
                // second and milliseconds can be optional
                if (date.length() > offset) {
                    char c = date.charAt(offset);
                    if (c != 'Z' && c != '+' && c != '-') {
                        seconds = parseInt(date, offset, offset += 2);
                        if (seconds > 59 && seconds < 63) seconds = 59; // truncate up to 3 leap seconds
                        // milliseconds can be optional in the format
                        if (checkOffset(date, offset, '.')) {
                            offset += 1;
                            int endOffset = indexOfNonDigit(date, offset + 1); // assume at least one digit
                            int parseEndOffset = Math.min(endOffset, offset + 3); // parse up to 3 digits
                            int fraction = parseInt(date, offset, parseEndOffset);
                            // compensate for "missing" digits
                            switch (parseEndOffset - offset) { // number of digits parsed
                            case 2:
                                milliseconds = fraction * 10;
                                break;
                            case 1:
                                milliseconds = fraction * 100;
                                break;
                            default:
                                milliseconds = fraction;
                            }
                            offset = endOffset;
                        }
                    }
                }
            }

            // extract timezone
            if (date.length() <= offset) {
                throw new IllegalArgumentException("No time zone indicator");
            }

            TimeZone timezone = null;
            char timezoneIndicator = date.charAt(offset);

            if (timezoneIndicator == 'Z') {
                timezone = TIMEZONE_UTC;
                offset += 1;
            } else if (timezoneIndicator == '+' || timezoneIndicator == '-') {
                String timezoneOffset = date.substring(offset);

                // When timezone has no minutes, we should append it, valid timezones are, for example: +00:00, +0000 and +00

                offset += timezoneOffset.length();
                // 18-Jun-2015, tatu: Minor simplification, skip offset of "+0000"/"+00:00"
                if ("+0000".equals(timezoneOffset) || "+00:00".equals(timezoneOffset)) {
                    timezone = TIMEZONE_UTC;
                } else {
                    // 18-Jun-2015, tatu: Looks like offsets only work from GMT, not UTC...
                    //    not sure why, but that's the way it looks. Further, Javadocs for
                    //    `java.util.TimeZone` specifically instruct use of GMT as base for
                    //    custom timezones... odd.
                    String timezoneId = "GMT" + timezoneOffset;
//                    String timezoneId = "UTC" + timezoneOffset;

                    timezone = TimeZone.getTimeZone(timezoneId);

                    String act = timezone.getID();
                    if (!act.equals(timezoneId)) {
                        /* 22-Jan-2015, tatu: Looks like canonical version has colons, but we may be given
                         *    one without. If so, don't sweat.
                         *   Yes, very inefficient. Hopefully not hit often.
                         *   If it becomes a perf problem, add 'loose' comparison instead.
                         */
                        String cleaned = act.replace(":", "");
                        if (!cleaned.equals(timezoneId)) {
                            throw new IndexOutOfBoundsException("Mismatching time zone indicator: "+timezoneId+" given, resolves to "
                                    +timezone.getID());
                        }
                    }
                }
            } else {
                throw new IndexOutOfBoundsException("Invalid time zone indicator '" + timezoneIndicator+"'");
            }

            Calendar calendar = new GregorianCalendar(timezone);
            calendar.setLenient(false);
            calendar.set(Calendar.YEAR, year);
            calendar.set(Calendar.MONTH, month - 1);
            calendar.set(Calendar.DAY_OF_MONTH, day);
            calendar.set(Calendar.HOUR_OF_DAY, hour);
            calendar.set(Calendar.MINUTE, minutes);
            calendar.set(Calendar.SECOND, seconds);
            calendar.set(Calendar.MILLISECOND, milliseconds);

            pos.setIndex(offset);
            return calendar.getTime();
            // If we get a ParseException it'll already have the right message/offset.
            // Other exception types can convert here.
        } catch (IndexOutOfBoundsException e) {
            fail = e;
        } catch (NumberFormatException e) {
            fail = e;
        } catch (IllegalArgumentException e) {
            fail = e;
        }
        String input = (date == null) ? null : ('"' + date + "'");
        String msg = fail.getMessage();
        if (msg == null || msg.isEmpty()) {
            msg = "("+fail.getClass().getName()+")";
        }
        ParseException ex = new ParseException("Failed to parse date [" + input + "]: " + msg, pos.getIndex());
        ex.initCause(fail);
        throw ex;
    }

public <T> TypeAdapter<T> create(Gson gson, TypeToken<T> targetType) {
  JsonAdapter annotation = targetType.getRawType().getAnnotation(JsonAdapter.class);
  if (annotation == null) {
    return null;
  }
  return getTypeAdapter(constructorConstructor, gson, targetType, annotation);
}

static TypeAdapter<?> getTypeAdapter(ConstructorConstructor constructorConstructor, Gson gson,
    TypeToken<?> fieldType, JsonAdapter annotation) {
  Class<?> value = annotation.value();
  TypeAdapter<?> typeAdapter;
  if (TypeAdapter.class.isAssignableFrom(value)) {
    Class<TypeAdapter<?>> typeAdapterClass = (Class<TypeAdapter<?>>) value;
    typeAdapter = constructorConstructor.get(TypeToken.get(typeAdapterClass)).construct();
  } else if (TypeAdapterFactory.class.isAssignableFrom(value)) {
    Class<TypeAdapterFactory> typeAdapterFactory = (Class<TypeAdapterFactory>) value;
    typeAdapter = constructorConstructor.get(TypeToken.get(typeAdapterFactory))
        .construct()
        .create(gson, fieldType);
  } else {
    throw new IllegalArgumentException(
        "@JsonAdapter value must be TypeAdapter or TypeAdapterFactory reference.");
  }
  typeAdapter = typeAdapter.nullSafe();
  return typeAdapter;
}

