private final int _outputRawMultiByteChar(int ch, char[] cbuf, int inputOffset, int inputEnd)
    throws IOException
    {
        // Let's handle surrogates gracefully (as 4 byte output):
        if (ch >= SURR1_FIRST) {
            if (ch <= SURR2_LAST) { // yes, outside of BMP
                // Do we have second part?
                if (inputOffset >= inputEnd || cbuf == null) { // nope... have to note down
                    _reportError("Split surrogate on writeRaw() input (last character)");
                }
                _outputSurrogates(ch, cbuf[inputOffset]);
                return inputOffset+1;
            }
        }
        final byte[] bbuf = _outputBuffer;
        bbuf[_outputTail++] = (byte) (0xe0 | (ch >> 12));
        bbuf[_outputTail++] = (byte) (0x80 | ((ch >> 6) & 0x3f));
        bbuf[_outputTail++] = (byte) (0x80 | (ch & 0x3f));
        return inputOffset;
    }

private final void _outputSurrogates(int surr1, int surr2) throws IOException
    {
        int c = _decodeSurrogate(surr1, surr2);
        if ((_outputTail + 4) > _outputEnd) {
            _flushBuffer();
        }
        final byte[] bbuf = _outputBuffer;
        bbuf[_outputTail++] = (byte) (0xf0 | (c >> 18));
        bbuf[_outputTail++] = (byte) (0x80 | ((c >> 12) & 0x3f));
        bbuf[_outputTail++] = (byte) (0x80 | ((c >> 6) & 0x3f));
        bbuf[_outputTail++] = (byte) (0x80 | (c & 0x3f));
    }

private final int _outputMultiByteChar(int ch, int outputPtr) throws IOException
    {
        byte[] bbuf = _outputBuffer;
        if (ch >= SURR1_FIRST && ch <= SURR2_LAST) { // yes, outside of BMP; add an escape
            // 23-Nov-2015, tatu: As per [core#223], may or may not want escapes;
            //   it would be added here... but as things are, we do not have proper
            //   access yet...
//            if (Feature.ESCAPE_UTF8_SURROGATES.enabledIn(_features)) {
                bbuf[outputPtr++] = BYTE_BACKSLASH;
                bbuf[outputPtr++] = BYTE_u;

                bbuf[outputPtr++] = HEX_CHARS[(ch >> 12) & 0xF];
                bbuf[outputPtr++] = HEX_CHARS[(ch >> 8) & 0xF];
                bbuf[outputPtr++] = HEX_CHARS[(ch >> 4) & 0xF];
                bbuf[outputPtr++] = HEX_CHARS[ch & 0xF];
//            } else { ... }
        } else {
            bbuf[outputPtr++] = (byte) (0xe0 | (ch >> 12));
            bbuf[outputPtr++] = (byte) (0x80 | ((ch >> 6) & 0x3f));
            bbuf[outputPtr++] = (byte) (0x80 | (ch & 0x3f));
        }
        return outputPtr;
    }

private final void _flushBuffer() throws IOException
    {
        int len = _outputTail;
        if (len > 0) {
            _outputTail = 0;
            _outputStream.write(_outputBuffer, 0, len);
        }
    }

/**
 * Method that can be called to write a binary object as an embedded object.
 * This method will write the binary data as a JSON object with a single field
 * named "binaryData" containing the base64 encoded binary data.
 *
 * @param object The binary object to write.
 * @throws IOException If an I/O error occurs.
 */
public void writeEmbeddedObject(Object object) throws IOException {
    if (object instanceof byte[]) {
        writeStartObject();
        writeFieldName("binaryData");
        writeBinary((byte[]) object);
        writeEndObject();
    } else {
        throw new JsonGenerationException("Unsupported type for writeEmbeddedObject: " + object.getClass().getName(), this);
    }
}

/**
 * Method that can be called to write a ByteBuffer as an embedded object.
 * This method will write the ByteBuffer data as a JSON object with a single field
 * named "binaryData" containing the base64 encoded binary data.
 *
 * @param object The ByteBuffer to write.
 * @throws IOException If an I/O error occurs.
 */
public void writeEmbeddedObject(Object object) throws IOException {
    if (object instanceof ByteBuffer) {
        ByteBuffer buffer = (ByteBuffer) object;
        byte[] bytes = new byte[buffer.remaining()];
        buffer.get(bytes);
        writeStartObject();
        writeFieldName("binaryData");
        writeBinary(bytes);
        writeEndObject();
    } else {
        throw new JsonGenerationException("Unsupported type for writeEmbeddedObject: " + object.getClass().getName(), this);
    }
}

