@Override
public Date parse(String dateStr) throws ParseException {
    dateStr = dateStr.trim();
    ParsePosition pos = new ParsePosition(0);
    Date result = parse(dateStr, pos);
    if (result != null) {
        return result;
    }

    StringBuilder sb = new StringBuilder();
    for (String f : ALL_FORMATS) {
        if (sb.length() > 0) {
            sb.append("\", \"");
        } else {
            sb.append('"');
        }
        sb.append(f);
    }
    sb.append('"');
    throw new ParseException
        (String.format("Can not parse date \"%s\": not compatible with any of standard forms (%s)",
                       dateStr, sb.toString()), pos.getErrorIndex());
}

@Override
public Date parse(String dateStr, ParsePosition pos)
{
    if (looksLikeISO8601(dateStr)) {
        return parseAsISO8601(dateStr, pos);
    }
    int i = dateStr.length();
    while (--i >= 0) {
        char ch = dateStr.charAt(i);
        if (ch < '0' || ch > '9') {
            if (i > 0 || ch != '-') {
                break;
            }
        }
    }
    if (i < 0) {
        if (dateStr.charAt(0) == '-' || NumberInput.inLongRange(dateStr, false)) {
            return new Date(Long.parseLong(dateStr));
        }
    }
    return parseAsRFC1123(dateStr, pos);
}

public static Value from(TokenBuffer buffer) {
    JsonParser jp = buffer.asParser();
    try {
        if (jp.nextToken() != JsonToken.START_OBJECT) {
            throw new JsonParseException(jp, "Expected START_OBJECT but found " + jp.currentToken());
        }
        // Read the fields
        int a = jp.nextIntValue(0);
        jp.nextToken(); // consume FIELD_NAME
        jp.nextToken(); // consume VALUE_NULL
        jp.nextToken(); // consume END_OBJECT
        return new Value(a, null);
    } catch (IOException e) {
        throw new RuntimeException("Error deserializing Value", e);
    } finally {
        jp.close();
    }
}

