/**
 * Factory method that can be used if type information is passed
 * as Java typing returned from <code>getGenericXxx</code> methods
 * (usually for a return or argument type).
 */
protected JavaType _constructType(Type type, TypeBindings context)
{
    JavaType resultType;

    // simple class?
    if (type instanceof Class<?>) {
        resultType = _fromClass((Class<?>) type, context);
    }
    // But if not, need to start resolving.
    else if (type instanceof ParameterizedType) {
        resultType = _fromParamType((ParameterizedType) type, context);
    }
    else if (type instanceof JavaType) { // [Issue#116]
        return (JavaType) type;
    }
    else if (type instanceof GenericArrayType) {
        resultType = _fromArrayType((GenericArrayType) type, context);
    }
    else if (type instanceof TypeVariable<?>) {
        resultType = _fromVariable((TypeVariable<?>) type, context);
    }
    else if (type instanceof WildcardType) {
        resultType = _fromWildcard((WildcardType) type, context);
    } else {
        // sanity check
        throw new IllegalArgumentException("Unrecognized Type: "+((type == null) ? "[null]" : type.toString()));
    }
    /* [JACKSON-521]: Need to allow TypeModifiers to alter actual type; however,
     * for now only call for simple types (i.e. not for arrays, map or collections).
     * Can be changed in future it necessary
     */
    if (_modifiers != null && !resultType.isContainerType()) {
        for (TypeModifier mod : _modifiers) {
            resultType = mod.modifyType(resultType, type, context, this);
        }
    }
    return resultType;
}

public boolean isCachable() {
    /* As per [databind#735], existence of value or key deserializer (only passed
     * if annotated to use non-standard one) should also prevent caching.
     */
    return (_valueTypeDeserializer == null)
            && (_keyDeserializer == null)
            && (_ignorableProperties == null);
}

@Override
public ReadableObjectId findObjectId(Object id, ObjectIdGenerator<?> gen, ObjectIdResolver resolverType)
{
    /* 02-Apr-2015, tatu: As per [databind#742] should allow 'null', similar to how
     *   missing id already works.
     */

    final ObjectIdGenerator.IdKey key = gen.key(id);

    if (_objectIds == null) {
        _objectIds = new LinkedHashMap<ObjectIdGenerator.IdKey,ReadableObjectId>();
    } else {
        ReadableObjectId entry = _objectIds.get(key);
        if (entry != null) {
            return entry;
        }
    }

    // Not seen yet, must create entry and configure resolver.
    ObjectIdResolver resolver = null;

    if (_objectIdResolvers == null) {
        _objectIdResolvers = new ArrayList<ObjectIdResolver>(8);
    } else {
        for (ObjectIdResolver res : _objectIdResolvers) {
            if (res.canUseFor(resolverType)) {
                resolver = res;
                break;
            }
        }
    }

    if (resolver == null) {
        resolver = resolverType.newForDeserialization(this);
        // 19-Dec-2014, tatu: For final 2.5.0, remove temporary (2.4.x) work-around
        //   needed to clear state between calls.
        // !!! 18-Jun-2014, pgelinas: Temporary fix for [#490] until real
        //    fix (for jackson-annotations, SimpleObjectIdResolver) can be added.
        /*
        if (resolverType.getClass() == SimpleObjectIdResolver.class) {
            resolver = new SimpleObjectIdResolver();
        }
        */
        _objectIdResolvers.add(resolver);
    }

    ReadableObjectId entry = new ReadableObjectId(key);
    entry.setResolver(resolver);
    _objectIds.put(key, entry);
    return entry;
}

    @Override
    public void deserializeAndSet(JsonParser jp, DeserializationContext ctxt,
            Object instance) throws IOException
    {
        deserializeSetAndReturn(jp, ctxt, instance);
    }

    @Override
    public Object deserializeSetAndReturn(JsonParser jp,
    		DeserializationContext ctxt, Object instance) throws IOException
    {
        // note: no null checks (unlike usually); deserializer should fail if one found
        Object id = _valueDeserializer.deserialize(jp, ctxt);

        /* 02-Apr-2015, tatu: Actually, as per [databind#742], let it be;
         *  missing or null id is needed for some cases, such as cases where id
         *  will be generated externally, at a later point, and is not available
         *  quite yet. Typical use case is with DB inserts.
         */

        ReadableObjectId roid = ctxt.findObjectId(id, _objectIdReader.generator, _objectIdReader.resolver);
        roid.bindItem(instance);
        // also: may need to set a property value as well
        SettableBeanProperty idProp = _objectIdReader.idProperty;
        if (idProp != null) {
            return idProp.setAndReturn(instance, id);
        }
        return instance;
    }

    @Override
    public void set(Object instance, Object value) throws IOException {
        setAndReturn(instance, value);
    }

    @Override
    public Object setAndReturn(Object instance, Object value) throws IOException
    {
        SettableBeanProperty idProp = _objectIdReader.idProperty;
        if (idProp == null) {
            throw new UnsupportedOperationException(
                    "Should not call set() on ObjectIdProperty that has no SettableBeanProperty");
        }
        return idProp.setAndReturn(instance, value);
    }
}

public DataA deserialize(JsonParser jp, DeserializationContext ctxt)
        throws JsonProcessingException, IOException {
    assert (jp.getCurrentToken() == JsonToken.START_OBJECT);
    JsonNode node = jp.getCodec().readTree(jp);

    DataA da = new DataA();
    da.i = node.get("i").asInt();
    da.j = node.get("j").asInt();
    return da;
}

@Override
public void serialize(Object value, JsonGenerator gen, SerializerProvider provider) throws IOException
{
    Object delegateValue = convertValue(value);
    // should we accept nulls?
    if (delegateValue == null) {
        provider.defaultSerializeNull(gen);
        return;
    }

    //original code:
    //_delegateSerializer.serialize(delegateValue, gen, provider);

    JsonSerializer<Object> delegateSerializer;
    if (_delegateSerializer instanceof UnknownSerializer) {
        delegateSerializer =  provider.findValueSerializer(delegateValue.getClass());
    } else {
        delegateSerializer = _delegateSerializer;
    }

    delegateSerializer.serialize(delegateValue, gen, provider);
}

public boolean add(Annotation ann) {
    if (_annotations == null) {
        _annotations = new HashMap<Class<? extends Annotation>,Annotation>();
    }
    if (_annotations.containsKey(ann.annotationType())) {
        return false;
    }
    _annotations.put(ann.annotationType(), ann);
    return true;
}

