protected Object deserializeWithExternalTypeId(JsonParser p, DeserializationContext ctxt,
        Object bean)
    throws IOException
    {
        final Class<?> activeView = _needViewProcesing ? ctxt.getActiveView() : null;
        final ExternalTypeHandler ext = _externalTypeIdHandler.start();

        for (JsonToken t = p.getCurrentToken(); t == JsonToken.FIELD_NAME; t = p.nextToken()) {
            String propName = p.getCurrentName();
            t = p.nextToken();
            SettableBeanProperty prop = _beanProperties.find(propName);
            if (prop != null) { // normal case
                // [JACKSON-831]: may have property AND be used as external type id:
                if (t.isScalarValue()) {
                    ext.handleTypePropertyValue(p, ctxt, propName, bean);
                }
                if (activeView != null && !prop.visibleInView(activeView)) {
                    p.skipChildren();
                    continue;
                }
                try {
                    prop.deserializeAndSet(p, ctxt, bean);
                } catch (Exception e) {
                    wrapAndThrow(e, bean, propName, ctxt);
                }
                continue;
            }
            // ignorable things should be ignored
            if (_ignorableProps != null && _ignorableProps.contains(propName)) {
                handleIgnoredProperty(p, ctxt, bean, propName);
                continue;
            }
            // but others are likely to be part of external type id thingy...
            if (ext.handlePropertyValue(p, ctxt, propName, bean)) {
                continue;
            }
            // if not, the usual fallback handling:
            if (_anySetter != null) {
                try {
                    _anySetter.deserializeAndSet(p, ctxt, bean, propName);
                } catch (Exception e) {
                    wrapAndThrow(e, bean, propName, ctxt);
                }
                continue;
            }
            // Unknown: let's call handler method
            handleUnknownProperty(p, ctxt, bean, propName);
        }
        // and when we get this far, let's try finalizing the deal:
        return ext.complete(p, ctxt, bean);
    }

protected Object deserializeUsingPropertyBasedWithExternalTypeId(JsonParser p, DeserializationContext ctxt)
        throws IOException
    {
        final ExternalTypeHandler ext = _externalTypeIdHandler.start();
        final PropertyBasedCreator creator = _propertyBasedCreator;
        PropertyValueBuffer buffer = creator.startBuilding(p, ctxt, _objectIdReader);

        TokenBuffer tokens = new TokenBuffer(p);
        tokens.writeStartObject();

        JsonToken t = p.getCurrentToken();
        for (; t == JsonToken.FIELD_NAME; t = p.nextToken()) {
            String propName = p.getCurrentName();
            p.nextToken(); // to point to value
            // creator property?
            SettableBeanProperty creatorProp = creator.findCreatorProperty(propName);
            if (creatorProp != null) {
                // first: let's check to see if this might be part of value with external type id:
                // 11-Sep-2015, tatu: Important; do NOT pass buffer as last arg, but null,
                //   since it is not the bean
                if (ext.handlePropertyValue(p, ctxt, propName, buffer)) {
                    ;
                } else {
                    // Last creator property to set?
                    if (buffer.assignParameter(creatorProp, _deserializeWithErrorWrapping(p, ctxt, creatorProp))) {
                        t = p.nextToken(); // to move to following FIELD_NAME/END_OBJECT
                        Object bean;
                        try {
                            bean = creator.build(ctxt, buffer);
                        } catch (Exception e) {
                            wrapAndThrow(e, _beanType.getRawClass(), propName, ctxt);
                            continue; // never gets here
                        }
                        // if so, need to copy all remaining tokens into buffer
                        while (t == JsonToken.FIELD_NAME) {
                            p.nextToken(); // to skip name
                            tokens.copyCurrentStructure(p);
                            t = p.nextToken();
                        }
                        if (bean.getClass() != _beanType.getRawClass()) {
                            // !!! 08-Jul-2011, tatu: Could theoretically support; but for now
                            //   it's too complicated, so bail out
                            throw ctxt.mappingException("Can not create polymorphic instances with unwrapped values");
                        }
                        return ext.complete(p, ctxt, bean);
                    }
                }
                continue;
            }
            // Object Id property?
            if (buffer.readIdProperty(propName)) {
                continue;
            }
            // regular property? needs buffering
            SettableBeanProperty prop = _beanProperties.find(propName);
            if (prop != null) {
                buffer.bufferProperty(prop, prop.deserialize(p, ctxt));
                continue;
            }
            // external type id (or property that depends on it)?
            if (ext.handlePropertyValue(p, ctxt, propName, null)) {
                continue;
            }
            /* As per [JACKSON-313], things marked as ignorable should not be
             * passed to any setter
             */
            if (_ignorableProps != null && _ignorableProps.contains(propName)) {
                handleIgnoredProperty(p, ctxt, handledType(), propName);
                continue;
            }
            // "any property"?
            if (_anySetter != null) {
                buffer.bufferAnyProperty(_anySetter, propName, _anySetter.deserialize(p, ctxt));
            }
        }

        // We hit END_OBJECT; resolve the pieces:
        try {
            return ext.complete(p, ctxt, buffer, creator);
        } catch (Exception e) {
            wrapInstantiationProblem(e, ctxt);
            return null; // never gets here
        }
    }

@Override
public JsonNode deserialize(JsonParser p, DeserializationContext ctxt) throws IOException
{
    switch (p.getCurrentTokenId()) {
    case JsonTokenId.ID_START_OBJECT:
        return deserializeObject(p, ctxt, ctxt.getNodeFactory());
    case JsonTokenId.ID_START_ARRAY:
        return deserializeArray(p, ctxt, ctxt.getNodeFactory());
    default:
        return deserializeAny(p, ctxt, ctxt.getNodeFactory());
    }
}

@Override
public JsonNode deserialize(JsonParser p, DeserializationContext ctxt) throws IOException
{
    if (p.getCurrentToken() == JsonToken.START_OBJECT) {
        p.nextToken();
        return deserializeObject(p, ctxt, ctxt.getNodeFactory());
    }
    // 23-Sep-2015, tatu: Ugh. We may also be given END_OBJECT (similar to FIELD_NAME),
    //    if caller has advanced to the first token of Object, but for empty Object
    if (p.getCurrentToken() == JsonToken.FIELD_NAME) {
        return deserializeObject(p, ctxt, ctxt.getNodeFactory());
    }
    throw ctxt.mappingException(ObjectNode.class);
 }

@Override
public JsonNode deserialize(JsonParser p, DeserializationContext ctxt) throws IOException
{
    if (p.isExpectedStartArrayToken()) {
        return deserializeArray(p, ctxt, ctxt.getNodeFactory());
    }
    throw ctxt.mappingException(ArrayNode.class);
}

public boolean handleTypePropertyValue(JsonParser jp, DeserializationContext ctxt,
        String propName, Object bean)
    throws IOException
{
    Integer I = _nameToPropertyIndex.get(propName);
    if (I == null) {
        return false;
    }
    int index = I.intValue();
    ExtTypedProperty prop = _properties[index];
    if (!prop.hasTypePropertyName(propName)) {
        return false;
    }
    String typeId = jp.getText();
    // note: can NOT skip child values (should always be String anyway)
    boolean canDeserialize = (bean != null) && (_tokens[index] != null);
    // Minor optimization: deserialize properties as soon as we have all we need:
    if (canDeserialize) {
        _deserializeAndSet(jp, ctxt, bean, index, typeId);
        // clear stored data, to avoid deserializing+setting twice:
        _tokens[index] = null;
    } else {
        _typeIds[index] = typeId;
    }
    return true;
}

public boolean handlePropertyValue(JsonParser jp, DeserializationContext ctxt,
        String propName, Object bean) throws IOException
{
    Integer I = _nameToPropertyIndex.get(propName);
    if (I == null) {
        return false;
    }
    int index = I.intValue();
    ExtTypedProperty prop = _properties[index];
    boolean canDeserialize;
    if (prop.hasTypePropertyName(propName)) {
        _typeIds[index] = jp.getText();
        jp.skipChildren();
        canDeserialize = (bean != null) && (_tokens[index] != null);
    } else {
        @SuppressWarnings("resource")
        TokenBuffer tokens = new TokenBuffer(jp);
        tokens.copyCurrentStructure(jp);
        _tokens[index] = tokens;
        canDeserialize = (bean != null) && (_typeIds[index] != null);
    }
    /* Minor optimization: let's deserialize properties as soon as
     * we have all pertinent information:
     */
    if (canDeserialize) {
        String typeId = _typeIds[index];
        // clear stored data, to avoid deserializing+setting twice:
        _typeIds[index] = null;
        _deserializeAndSet(jp, ctxt, bean, index, typeId);
        _tokens[index] = null;
    }
    return true;
}

public Object complete(JsonParser p, DeserializationContext ctxt, Object bean)
    throws IOException
{
    for (int i = 0, len = _properties.length; i < len; ++i) {
        String typeId = _typeIds[i];
        if (typeId == null) {
            TokenBuffer tokens = _tokens[i];
            // let's allow missing both type and property (may already have been set, too)
            // but not just one
            if (tokens == null) {
                continue;
            }
            // [databind#118]: Need to mind natural types, for which no type id
            // will be included.
            JsonToken t = tokens.firstToken();
            if (t != null && t.isScalarValue()) {
                JsonParser buffered = tokens.asParser(p);
                buffered.nextToken();
                SettableBeanProperty extProp = _properties[i].getProperty();
                Object result = TypeDeserializer.deserializeIfNatural(buffered, ctxt, extProp.getType());
                if (result != null) {
                    extProp.set(bean, result);
                    continue;
                }
                // 26-Oct-2012, tatu: As per [databind#94], must allow use of 'defaultImpl'
                if (!_properties[i].hasDefaultType()) {
                    throw ctxt.mappingException("Missing external type id property '%s'",
                            _properties[i].getTypePropertyName());                                
                }
                typeId = _properties[i].getDefaultTypeId();
            }
        } else if (_tokens[i] == null) {
            SettableBeanProperty prop = _properties[i].getProperty();
            throw ctxt.mappingException("Missing property '%s' for external type id '%s'",
                    prop.getName(), _properties[i].getTypePropertyName());
        }
        _deserializeAndSet(p, ctxt, bean, i, typeId);
    }
    return bean;
}

public Object complete(JsonParser jp, DeserializationContext ctxt,
        PropertyValueBuffer buffer, PropertyBasedCreator creator)
    throws IOException
{
    // first things first: deserialize all data buffered:
    final int len = _properties.length;
    Object[] values = new Object[len];
    for (int i = 0; i < len; ++i) {
        String typeId = _typeIds[i];
        if (typeId == null) {
            // let's allow missing both type and property (may already have been set, too)
            if (_tokens[i] == null) {
                continue;
            }
            // but not just one
            // 26-Oct-2012, tatu: As per [Issue#94], must allow use of 'defaultImpl'
            if (!_properties[i].hasDefaultType()) {
                throw ctxt.mappingException("Missing external type id property '%s'",
                        _properties[i].getTypePropertyName());
            }
            typeId = _properties[i].getDefaultTypeId();
        } else if (_tokens[i] == null) {
            SettableBeanProperty prop = _properties[i].getProperty();
            throw ctxt.mappingException("Missing property '%s' for external type id '%s'",
                    prop.getName(), _properties[i].getTypePropertyName());
        }
        values[i] = _deserialize(jp, ctxt, i, typeId);
    }
    // second: fill in creator properties:
    for (int i = 0; i < len; ++i) {
        SettableBeanProperty prop = _properties[i].getProperty();
        if (creator.findCreatorProperty(prop.getName()) != null) {
            buffer.assignParameter(prop, values[i]);
        }
    }
    Object bean = creator.build(ctxt, buffer);
    // third: assign non-creator properties
    for (int i = 0; i < len; ++i) {
        SettableBeanProperty prop = _properties[i].getProperty();
        if (creator.findCreatorProperty(prop.getName()) == null) {
            prop.set(bean, values[i]);
        }
    }
    return bean;
}

@SuppressWarnings("resource")
protected final Object _deserialize(JsonParser p, DeserializationContext ctxt,
        int index, String typeId) throws IOException
{
    JsonParser p2 = _tokens[index].asParser(p);
    JsonToken t = p2.nextToken();
    // 29-Sep-2015, tatu: As per [databind#942], nulls need special support

    TokenBuffer merged = new TokenBuffer(p);
    merged.writeStartArray();
    merged.writeString(typeId);
    merged.copyCurrentStructure(p2);
    merged.writeEndArray();

    // needs to point to START_OBJECT (or whatever first token is)
    JsonParser mp = merged.asParser(p);
    mp.nextToken();
    return _properties[index].getProperty().deserialize(mp, ctxt);
}

@SuppressWarnings("resource")
protected final void _deserializeAndSet(JsonParser p, DeserializationContext ctxt,
        Object bean, int index, String typeId) throws IOException
{
    /* Ok: time to mix type id, value; and we will actually use "wrapper-array"
     * style to ensure we can handle all kinds of JSON constructs.
     */
    JsonParser p2 = _tokens[index].asParser(p);
    JsonToken t = p2.nextToken();
    // 29-Sep-2015, tatu: As per [databind#942], nulls need special support
    TokenBuffer merged = new TokenBuffer(p);
    merged.writeStartArray();
    merged.writeString(typeId);

    merged.copyCurrentStructure(p2);
    merged.writeEndArray();
    // needs to point to START_OBJECT (or whatever first token is)
    JsonParser mp = merged.asParser(p);
    mp.nextToken();
    _properties[index].getProperty().deserializeAndSet(mp, ctxt, bean);
}

public JsonParser asParser(ObjectCodec codec) {
    return new Parser(_first, codec, _hasNativeTypeIds, _hasNativeObjectIds);
}

public JsonParser asParser(JsonParser src) {
    Parser p = new Parser(_first, src.getCodec(), _hasNativeTypeIds, _hasNativeObjectIds);
    p.setLocation(src.getTokenLocation());
    return p;
}

    protected Object deserialize(JsonParser p, DeserializationContext ctxt) throws IOException {
        switch (p.getCurrentTokenId()) {
        case JsonTokenId.ID_START_OBJECT:
        case JsonTokenId.ID_FIELD_NAME:
            // 28-Oct-2015, tatu: [databind#989] We may also be given END_OBJECT (similar to FIELD_NAME),
            //    if caller has advanced to the first token of Object, but for empty Object
            if (_mapDeserializer != null) {
                return _mapDeserializer.deserialize(p, ctxt);
            }
            return mapObject(p, ctxt);
        case JsonTokenId.ID_START_ARRAY:
            if (ctxt.isEnabled(DeserializationFeature.USE_JAVA_ARRAY_FOR_JSON_ARRAY)) {
                return mapArrayToArray(p, ctxt);
            }
            if (_listDeserializer != null) {
                return _listDeserializer.deserialize(p, ctxt);
            }
            return mapArray(p, ctxt);
        case JsonTokenId.ID_EMBEDDED_OBJECT:
            return p.getEmbeddedObject();
        case JsonTokenId.ID_STRING:
            if (_stringDeserializer != null) {
                return _stringDeserializer.deserialize(p, ctxt);
            }
            return p.getText();

        case JsonTokenId.ID_NUMBER_INT:
            if (_numberDeserializer != null) {
                return _numberDeserializer.deserialize(p, ctxt);
            }
            /* Caller may want to get all integral values returned as {@link java.math.BigInteger},
             * or {@link java.lang.Long} for consistency
             */
            if (ctxt.hasSomeOfFeatures(F_MASK_INT_COERCIONS)) {
                return _coerceIntegral(p, ctxt);
            }
            return p.getNumberValue(); // should be optimal, whatever it is

        case JsonTokenId.ID_NUMBER_FLOAT:
            if (_numberDeserializer != null) {
                return _numberDeserializer.deserialize(p, ctxt);
            }
            /* [JACKSON-72]: need to allow overriding the behavior regarding
             *   which type to use
             */
            if (ctxt.isEnabled(DeserializationFeature.USE_BIG_DECIMAL_FOR_FLOATS)) {
                return p.getDecimalValue();
            }
            return p.getDoubleValue();

        case JsonTokenId.ID_TRUE:
            return Boolean.TRUE;
        case JsonTokenId.ID_FALSE:
            return Boolean.FALSE;

        case JsonTokenId.ID_NULL: // should not get this but...
            return null;

//        case JsonTokenId.ID_END_ARRAY: // invalid
        default:
        }
        throw ctxt.mappingException(Object.class);
    }

protected Object deserializeWithType(JsonParser p, DeserializationContext ctxt, TypeDeserializer typeDeserializer) throws IOException {
    switch (p.getCurrentTokenId()) {
    // First: does it look like we had type id wrapping of some kind?
    case JsonTokenId.ID_START_ARRAY:
    case JsonTokenId.ID_START_OBJECT:
    case JsonTokenId.ID_FIELD_NAME:
        /* Output can be as JSON Object, Array or scalar: no way to know
         * a this point:
         */
        return typeDeserializer.deserializeTypedFromAny(p, ctxt);

    case JsonTokenId.ID_EMBEDDED_OBJECT:
        return p.getEmbeddedObject();

    /* Otherwise we probably got a "native" type (ones that map
     * naturally and thus do not need or use type ids)
     */
    case JsonTokenId.ID_STRING:
        if (_stringDeserializer != null) {
            return _stringDeserializer.deserialize(p, ctxt);
        }
        return p.getText();

    case JsonTokenId.ID_NUMBER_INT:
        if (_numberDeserializer != null) {
            return _numberDeserializer.deserialize(p, ctxt);
        }
        // May need coercion to "bigger" types:
        if (ctxt.hasSomeOfFeatures(F_MASK_INT_COERCIONS)) {
            return _coerceIntegral(p, ctxt);
        }
        return p.getNumberValue(); // should be optimal, whatever it is

    case JsonTokenId.ID_NUMBER_FLOAT:
        if (_numberDeserializer != null) {
            return _numberDeserializer.deserialize(p, ctxt);
        }
        if (ctxt.isEnabled(DeserializationFeature.USE_BIG_DECIMAL_FOR_FLOATS)) {
            return p.getDecimalValue();
        }
        return Double.valueOf(p.getDoubleValue());

    case JsonTokenId.ID_TRUE:
        return Boolean.TRUE;
    case JsonTokenId.ID_FALSE:
        return Boolean.FALSE;

    case JsonTokenId.ID_NULL: // should not get this far really but...
        return null;
    default:
    }
    throw ctxt.mappingException(Object.class);
}

protected Object mapObject(JsonParser p, DeserializationContext ctxt) throws IOException {
    String key1;

    JsonToken t = p.getCurrentToken();

    if (t == JsonToken.START_OBJECT) {
        key1 = p.nextFieldName();
    } else if (t == JsonToken.FIELD_NAME) {
        key1 = p.getCurrentName();
    } else {
        if (t != JsonToken.END_OBJECT) {
            throw ctxt.mappingException(handledType(), p.getCurrentToken());
        }
        key1 = null;
    }
    if (key1 == null) {
        // empty map might work; but caller may want to modify... so better just give small modifiable
        return new LinkedHashMap<String,Object>(2);
    }
    // minor optimization; let's handle 1 and 2 entry cases separately
    // 24-Mar-2015, tatu: Ideally, could use one of 'nextXxx()' methods, but for
    //   that we'd need new method(s) in JsonDeserializer. So not quite yet.
    p.nextToken();
    Object value1 = deserialize(p, ctxt);

    String key2 = p.nextFieldName();
    if (key2 == null) { // has to be END_OBJECT, then
        // single entry; but we want modifiable
        LinkedHashMap<String, Object> result = new LinkedHashMap<String, Object>(2);
        result.put(key1, value1);
        return result;
    }
    p.nextToken();
    Object value2 = deserialize(p, ctxt);

    String key = p.nextFieldName();

    if (key == null) {
        LinkedHashMap<String, Object> result = new LinkedHashMap<String, Object>(4);
        result.put(key1, value1);
        result.put(key2, value2);
        return result;
    }
    // And then the general case; default map size is 16
    LinkedHashMap<String, Object> result = new LinkedHashMap<String, Object>();
    result.put(key1, value1);
    result.put(key2, value2);

    do {
        p.nextToken();
        result.put(key, deserialize(p, ctxt));
    } while ((key = p.nextFieldName()) != null);
    return result;
}

protected Object mapArray(JsonParser jp, DeserializationContext ctxt) throws IOException {
    // Minor optimization to handle small lists (default size for ArrayList is 10)
    if (jp.nextToken()  == JsonToken.END_ARRAY) {
        return new ArrayList<Object>(2);
    }
    Object value = deserialize(jp, ctxt);
    if (jp.nextToken()  == JsonToken.END_ARRAY) {
        ArrayList<Object> l = new ArrayList<Object>(2);
        l.add(value);
        return l;
    }
    Object value2 = deserialize(jp, ctxt);
    if (jp.nextToken()  == JsonToken.END_ARRAY) {
        ArrayList<Object> l = new ArrayList<Object>(2);
        l.add(value);
        l.add(value2);
        return l;
    }
    ObjectBuffer buffer = ctxt.leaseObjectBuffer();
    Object[] values = buffer.resetAndStart();
    int ptr = 0;
    values[ptr++] = value;
    values[ptr++] = value2;
    int totalSize = ptr;
    do {
        value = deserialize(jp, ctxt);
        ++totalSize;
        if (ptr >= values.length) {
            values = buffer.appendCompletedChunk(values);
            ptr = 0;
        }
        values[ptr++] = value;
    } while (jp.nextToken() != JsonToken.END_ARRAY);
    // let's create full array then
    ArrayList<Object> result = new ArrayList<Object>(totalSize);
    buffer.completeAndClearBuffer(values, ptr, result);
    return result;
}

protected Object mapArrayToArray(JsonParser jp, DeserializationContext ctxt) throws IOException {
    // Minor optimization to handle small lists (default size for ArrayList is 10)
    if (jp.nextToken()  == JsonToken.END_ARRAY) {
        return NO_OBJECTS;
    }
    ObjectBuffer buffer = ctxt.leaseObjectBuffer();
    Object[] values = buffer.resetAndStart();
    int ptr = 0;
    do {
        Object value = deserialize(jp, ctxt);
        if (ptr >= values.length) {
            values = buffer.appendCompletedChunk(values);
            ptr = 0;
        }
        values[ptr++] = value;
    } while (jp.nextToken() != JsonToken.END_ARRAY);
    return buffer.completeAndClearBuffer(values, ptr);
}

@Override
public String findEnumValue(Enum<?> value)
{
    // 11-Jun-2015, tatu: As per [databind#677], need to allow explicit naming.
    //   Unfortunately can not quite use standard AnnotatedClass here (due to various
    //   reasons, including odd representation JVM uses); has to do for now
    try {
        // We know that values are actually static fields with matching name so:
        Field f = value.getClass().getField(value.name());
        if (f != null) {
            JsonProperty prop = f.getAnnotation(JsonProperty.class);
            if (prop != null) {
                String n = prop.value();
                if (n != null && !n.isEmpty()) {
                    return n;
                }
            }
        }
    } catch (SecurityException e) {
        // 17-Sep-2015, tatu: Anything we could/should do here?
    } catch (NoSuchFieldException e) {
        // 17-Sep-2015, tatu: should not really happen. But... can we do anything?
    }
    return value.name();
}

