    if (prop != null) {
      int ix = prop.index();
      if (ix != JsonProperty.INDEX_UNKNOWN) {
           return Integer.valueOf(ix);
      }
    }
    return null;
}

@Override
public String findPropertyDefaultValue(Annotated ann) {
    JsonProperty prop = _findAnnotation(ann, JsonProperty.class);
    if (prop == null) {
        return null;
    }
    String str = prop.defaultValue();
    // Since annotations do not allow nulls, need to assume empty means "none"
    return str.isEmpty() ? null : str;
}

} else if (value instanceof BigInteger) {
    g.writeNumber((BigInteger) value);

/* These shouldn't match (as there are more specific ones),
 * but just to be sure:
 */
} else if (value instanceof Integer) {
    g.writeNumber(value.intValue());
} else if (value instanceof Long) {
    g.writeNumber(value.longValue());
} else if (value instanceof Double) {
    g.writeNumber(value.doubleValue());
} else if (value instanceof Float) {
    g.writeNumber(value.floatValue());
} else if ((value instanceof Byte) || (value instanceof Short)) {
    g.writeNumber(value.intValue()); // doesn't need to be cast to smaller numbers
} else {
    // We'll have to use fallback "untyped" number write method
    g.writeNumber(value.toString());
}

