protected T _deserialize(String value, DeserializationContext ctxt) throws IOException {
    if (value == null || value.trim().isEmpty()) {
        return _deserializeFromEmptyString();
    }
    Exception cause = null;
    try {
        T result = _deserialize(value, ctxt);
        if (result != null) {
            return result;
        }
    } catch (IllegalArgumentException iae) {
        cause = iae;
    }
    String msg = "not a valid textual representation";
    if (cause != null) {
        String m2 = cause.getMessage();
        if (m2 != null) {
            msg = msg + ", problem: "+m2;
        }
    }
    JsonMappingException e = ctxt.weirdStringException(value, _valueClass, msg);
    if (cause != null) {
        e.initCause(cause);
    }
    throw e;
}

@Override
public Object deserializeSetAndReturn(JsonParser p,
		DeserializationContext ctxt, Object instance) throws IOException
{
    Object id = _valueDeserializer.deserialize(p, ctxt);
    /* 02-Apr-2015, tatu: Actually, as per [databind#742], let it be;
     *  missing or null id is needed for some cases, such as cases where id
     *  will be generated externally, at a later point, and is not available
     *  quite yet. Typical use case is with DB inserts.
     */
    // note: no null checks (unlike usually); deserializer should fail if one found
    if (id == null) {
        return null;
    }
    ReadableObjectId roid = ctxt.findObjectId(id, _objectIdReader.generator, _objectIdReader.resolver);
    roid.bindItem(instance);
    // also: may need to set a property value as well
    SettableBeanProperty idProp = _objectIdReader.idProperty;
    if (idProp != null) {
        return idProp.setAndReturn(instance, id);
    }
    return instance;
}

