public void remove(SettableBeanProperty propToRm)
{
    ArrayList<SettableBeanProperty> props = new ArrayList<SettableBeanProperty>(_size);
    String key = getPropertyName(propToRm);
    boolean found = false;

    for (int i = 1, end = _hashArea.length; i < end; i += 2) {
        SettableBeanProperty prop = (SettableBeanProperty) _hashArea[i];
        if (prop == null) {
            continue;
        }
        if (!found) {
            // 09-Jan-2017, tatu: Important: must check name slot and NOT property name,
            //   as only former is lower-case in case-insensitive case
            found = key.equals(prop.getName());
            if (found) {
                // need to leave a hole here
                _propsInOrder[_findFromOrdered(prop)] = null;
                continue;
            }
        }
        props.add(prop);
    }
    if (!found) {
        throw new NoSuchElementException("No entry '"+propToRm.getName()+"' found, can't remove");
    }
    init(props);
}

public static StdKeyDeserializer forType(Class<?> raw)
{
    int kind;

    // first common types:
    if (raw == String.class || raw == Object.class) {
        return StringKD.forType(raw);
    } else if (raw == CharSequence.class) {
        return new StdKeyDeserializer(TYPE_CHARSEQUENCE, raw);
    } else if (raw == UUID.class) {
        kind = TYPE_UUID;
    } else if (raw == Integer.class) {
        kind = TYPE_INT;
    } else if (raw == Long.class) {
        kind = TYPE_LONG;
    } else if (raw == Date.class) {
        kind = TYPE_DATE;
    } else if (raw == Calendar.class) {
        kind = TYPE_CALENDAR;
    // then less common ones...
    } else if (raw == Boolean.class) {
        kind = TYPE_BOOLEAN;
    } else if (raw == Byte.class) {
        kind = TYPE_BYTE;
    } else if (raw == Character.class) {
        kind = TYPE_CHAR;
    } else if (raw == Short.class) {
        kind = TYPE_SHORT;
    } else if (raw == Float.class) {
        kind = TYPE_FLOAT;
    } else if (raw == Double.class) {
        kind = TYPE_DOUBLE;
    } else if (raw == URI.class) {
        kind = TYPE_URI;
    } else if (raw == URL.class) {
        kind = TYPE_URL;
    } else if (raw == Class.class) {
        kind = TYPE_CLASS;
    } else if (raw == Locale.class) {
        FromStringDeserializer<?> deser = FromStringDeserializer.findDeserializer(Locale.class);
        return new StdKeyDeserializer(TYPE_LOCALE, raw, deser);
    } else if (raw == Currency.class) {
        FromStringDeserializer<?> deser = FromStringDeserializer.findDeserializer(Currency.class);
        return new StdKeyDeserializer(TYPE_CURRENCY, raw, deser);
    } else {
        return null;
    }
    return new StdKeyDeserializer(kind, raw);
}

protected Object _parse(String key, DeserializationContext ctxt) throws Exception
{
    switch (_kind) {
    case TYPE_CHARSEQUENCE:
        return key;
    case TYPE_BOOLEAN:
        if ("true".equals(key)) {
            return Boolean.TRUE;
        }
        if ("false".equals(key)) {
            return Boolean.FALSE;
        }
        throw ctxt.weirdKeyException(_keyClass, key, "value not 'true' or 'false'");
    case TYPE_BYTE:
        {
            int value = _parseInt(key);
            // as per [JACKSON-804], allow range up to 255, inclusive
            if (value < Byte.MIN_VALUE || value > 255) {
                throw ctxt.weirdKeyException(_keyClass, key, "overflow, value can not be represented as 8-bit value");
            }
            return Byte.valueOf((byte) value);
        }
    case TYPE_SHORT:
        {
            int value = _parseInt(key);
            if (value < Short.MIN_VALUE || value > Short.MAX_VALUE) {
                throw ctxt.weirdKeyException(_keyClass, key, "overflow, value can not be represented as 16-bit value");
            }
            return Short.valueOf((short) value);
        }
    case TYPE_CHAR:
        if (key.length() == 1) {
            return Character.valueOf(key.charAt(0));
        }
        throw ctxt.weirdKeyException(_keyClass, key, "can only convert 1-character Strings");
    case TYPE_INT:
        return _parseInt(key);

    case TYPE_LONG:
        return _parseLong(key);

    case TYPE_FLOAT:
        // Bounds/range checks would be tricky here, so let's not bother even trying...
        return Float.valueOf((float) _parseDouble(key));
    case TYPE_DOUBLE:
        return _parseDouble(key);
    case TYPE_LOCALE:
        try {
            return _deser._deserialize(key, ctxt);
        } catch (IOException e) {
            throw ctxt.weirdKeyException(_keyClass, key, "unable to parse key as locale");
        }
    case TYPE_CURRENCY:
        try {
            return _deser._deserialize(key, ctxt);
        } catch (IOException e) {
            throw ctxt.weirdKeyException(_keyClass, key, "unable to parse key as currency");
        }
    case TYPE_DATE:
        return ctxt.parseDate(key);
    case TYPE_CALENDAR:
        java.util.Date date = ctxt.parseDate(key);
        return (date == null)  ? null : ctxt.constructCalendar(date);
    case TYPE_UUID:
        return UUID.fromString(key);
    case TYPE_URI:
        return URI.create(key);
    case TYPE_URL:
        return new URL(key);
    case TYPE_CLASS:
        try {
            return ctxt.findClass(key);
        } catch (Exception e) {
            throw ctxt.weirdKeyException(_keyClass, key, "unable to parse key as Class");
        }
    }
    return null;
}

