        } catch (Exception e) {
            ClassUtil.unwrapAndThrowAsIAE(e, "Failed to instantiate class "+_creator.getDeclaringClass().getName()+", problem: "+e.getMessage());
            value = null;
        }
        _valueDeserializer.deserialize(jp, ctxt, value);
    }
    set(bean, value);
}

