protected void serializeFields(Object bean, JsonGenerator gen, SerializerProvider provider)
    throws IOException
{
    final BeanPropertyWriter[] props;
    if (_filteredProps != null && provider.getActiveView() != null) {
        props = _filteredProps;
    } else {
        props = _props;
    }
    int i = 0;
    try {
        for (final int len = props.length; i < len; ++i) {
            BeanPropertyWriter prop = props[i];
            if (prop != null) { // can have nulls in filtered list
                prop.serializeAsField(bean, gen, provider);
            }
        }
        if (_anyGetterWriter != null) {
            _anyGetterWriter.getAndSerialize(bean, gen, provider);
        }
    } catch (Exception e) {
        String name = (i == props.length) ? "[anySetter]" : props[i].getName();
        wrapAndThrow(provider, e, bean, name);
    } catch (StackOverflowError e) {
        // Minimize call depth since we are close to fail:
        //JsonMappingException mapE = JsonMappingException.from(gen, "Infinite recursion (StackOverflowError)", e);
        JsonMappingException mapE = new JsonMappingException(gen, "Infinite recursion (StackOverflowError)", e);
        String name = (i == props.length) ? "[anySetter]" : props[i].getName();
        mapE.prependPath(new JsonMappingException.Reference(bean, name));
        throw mapE;
    }
}

/**
 * Alternative serialization method that gets called when there is a
 * {@link PropertyFilter} that needs to be called to determine
 * which properties are to be serialized (and possibly how)
 */
protected void serializeFieldsFiltered(Object bean, JsonGenerator gen,
        SerializerProvider provider)
    throws IOException, JsonGenerationException
{
    /* note: almost verbatim copy of "serializeFields"; copied (instead of merged)
     * so that old method need not add check for existence of filter.
     */
    final BeanPropertyWriter[] props;
    if (_filteredProps != null && provider.getActiveView() != null) {
        props = _filteredProps;
    } else {
        props = _props;
    }
    final PropertyFilter filter = findPropertyFilter(provider, _propertyFilterId, bean);
    // better also allow missing filter actually..
    if (filter == null) {
        serializeFields(bean, gen, provider);
        return;
    }
    int i = 0;
    try {
        for (final int len = props.length; i < len; ++i) {
            BeanPropertyWriter prop = props[i];
            if (prop != null) { // can have nulls in filtered list
                filter.serializeAsField(bean, gen, provider, prop);
            }
        }
        if (_anyGetterWriter != null) {
            _anyGetterWriter.getAndFilter(bean, gen, provider, filter);
        }
    } catch (Exception e) {
        String name = (i == props.length) ? "[anySetter]" : props[i].getName();
        wrapAndThrow(provider, e, bean, name);
    } catch (StackOverflowError e) {
        // Minimize call depth since we are close to fail:
        //JsonMappingException mapE = JsonMappingException.from(gen, "Infinite recursion (StackOverflowError)", e);
        JsonMappingException mapE = new JsonMappingException(gen, "Infinite recursion (StackOverflowError)", e);
        String name = (i == props.length) ? "[anySetter]" : props[i].getName();
        mapE.prependPath(new JsonMappingException.Reference(bean, name));
        throw mapE;
    }
}

protected void _collectAndResolve(AnnotatedClass annotatedType, NamedType namedType,
        MapperConfig<?> config, AnnotationIntrospector ai,
        HashMap<NamedType, NamedType> collectedSubtypes)
{
    if (!namedType.hasName()) {
        String name = ai.findTypeName(annotatedType);
        if (name != null) {
            namedType = new NamedType(namedType.getType(), name);
        }
    }

    // First things first: is base type itself included?
    if (collectedSubtypes.containsKey(namedType)) {
        // if so, no recursion; however, may need to update name?
        if (namedType.hasName()) {
            NamedType prev = collectedSubtypes.get(namedType);
            if (!prev.hasName()) {
                collectedSubtypes.put(namedType, namedType);
            }
        }
        return;
    }
    // if it wasn't, add and check subtypes recursively
    collectedSubtypes.put(namedType, namedType);
    Collection<NamedType> st = ai.findSubtypes(annotatedType);
    if (st != null && !st.isEmpty()) {
        for (NamedType subtype : st) {
            AnnotatedClass subtypeClass = AnnotatedClassResolver.resolveWithoutSuperTypes(config,
                    subtype.getType());
            _collectAndResolve(subtypeClass, subtype, config, ai, collectedSubtypes);
        }
    }
}

protected void _collectAndResolveByTypeId(AnnotatedClass annotatedType, NamedType namedType,
        MapperConfig<?> config,
        Set<Class<?>> typesHandled, Map<String,NamedType> byName)
{
    final AnnotationIntrospector ai = config.getAnnotationIntrospector();
    if (!namedType.hasName()) {
        String name = ai.findTypeName(annotatedType);
        if (name != null) {
            namedType = new NamedType(namedType.getType(), name);
        }
    }
    if (namedType.hasName()) {
        byName.put(namedType.getName(), namedType);
    }

    // only check subtypes if this type hadn't yet been handled
    if (typesHandled.add(namedType.getType())) {
        Collection<NamedType> st = ai.findSubtypes(annotatedType);
        if (st != null && !st.isEmpty()) {
            for (NamedType subtype : st) {
                AnnotatedClass subtypeClass = AnnotatedClassResolver.resolveWithoutSuperTypes(config,
                        subtype.getType());
                _collectAndResolveByTypeId(subtypeClass, subtype, config, typesHandled, byName);
            }
        }
    }
}

protected Collection<NamedType> _combineNamedAndUnnamed(Class<?> rawBase,
        Set<Class<?>> typesHandled, Map<String,NamedType> byName)
{
    ArrayList<NamedType> result = new ArrayList<NamedType>(byName.values());

    // Ok, so... we will figure out which classes have no explicitly assigned name,
    // by removing Classes from Set. And for remaining classes, add an anonymous
    // marker
    for (NamedType t : byName.values()) {
        typesHandled.remove(t.getType());
    }
    for (Class<?> cls : typesHandled) {
        // 27-Apr-2017, tatu: [databind#1616] Do not add base type itself unless
        //     it is concrete (or has explicit type name)
        if ((cls == rawBase) && Modifier.isAbstract(cls.getModifiers())) {
            continue;
        }
        result.add(new NamedType(cls));
    }
    return result;
}

@Override
public JavaType refineSerializationType(final MapperConfig<?> config,
        final Annotated a, final JavaType baseType) throws JsonMappingException
{
    JavaType type = baseType;
    final TypeFactory tf = config.getTypeFactory();

    final JsonSerialize jsonSer = _findAnnotation(a, JsonSerialize.class);

    // Ok: start by refining the main type itself; common to all types

    final Class<?> serClass = (jsonSer == null) ? null : _classIfExplicit(jsonSer.as());
    if (serClass != null) {
        if (type.hasRawClass(serClass)) {
            // 30-Nov-2015, tatu: As per [databind#1023], need to allow forcing of
            //    static typing this way
            type = type.withStaticTyping();
        } else {
            Class<?> currRaw = type.getRawClass();
            try {
                // 11-Oct-2015, tatu: For deser, we call `TypeFactory.constructSpecializedType()`,
                //   may be needed here too in future?
                if (serClass.isAssignableFrom(currRaw)) { // common case
                    type = tf.constructGeneralizedType(type, serClass);
                } else if (currRaw.isAssignableFrom(serClass)) { // specialization, ok as well
                    type = tf.constructSpecializedType(type, serClass);
                    // 27-Apr-2017, tatu: [databind#1592] ignore primitive<->wrapper refinements
                } else {
                    throw new JsonMappingException(null,
                            String.format("Can not refine serialization type %s into %s; types not related",
                                    type, serClass.getName()));
                }
            } catch (IllegalArgumentException iae) {
                throw new JsonMappingException(null,
                        String.format("Failed to widen type %s with annotation (value %s), from '%s': %s",
                                type, serClass.getName(), a.getName(), iae.getMessage()),
                                iae);
            }
        }
    }
    // Then further processing for container types

    // First, key type (for Maps, Map-like types):
    if (type.isMapLikeType()) {
        JavaType keyType = type.getKeyType();
        final Class<?> keyClass = (jsonSer == null) ? null : _classIfExplicit(jsonSer.keyAs());
        if (keyClass != null) {
            if (keyType.hasRawClass(keyClass)) {
                keyType = keyType.withStaticTyping();
            } else {
                Class<?> currRaw = keyType.getRawClass();
                try {
                    // 19-May-2016, tatu: As per [databind#1231], [databind#1178] may need to actually
                    //   specialize (narrow) type sometimes, even if more commonly opposite
                    //   is needed.
                    if (keyClass.isAssignableFrom(currRaw)) { // common case
                        keyType = tf.constructGeneralizedType(keyType, keyClass);
                    } else if (currRaw.isAssignableFrom(keyClass)) { // specialization, ok as well
                        keyType = tf.constructSpecializedType(keyType, keyClass);
                        // 27-Apr-2017, tatu: [databind#1592] ignore primitive<->wrapper refinements
                    } else {
                        throw new JsonMappingException(null,
                                String.format("Can not refine serialization key type %s into %s; types not related",
                                        keyType, keyClass.getName()));
                    }
                } catch (IllegalArgumentException iae) {
                    throw new JsonMappingException(null,
                            String.format("Failed to widen key type of %s with concrete-type annotation (value %s), from '%s': %s",
                                    type, keyClass.getName(), a.getName(), iae.getMessage()),
                                    iae);
                }
            }
            type = ((MapLikeType) type).withKeyType(keyType);
        }
    }

    JavaType contentType = type.getContentType();
    if (contentType != null) { // collection[like], map[like], array, reference
        // And then value types for all containers:
       final Class<?> contentClass = (jsonSer == null) ? null : _classIfExplicit(jsonSer.contentAs());
       if (contentClass != null) {
           if (contentType.hasRawClass(contentClass)) {
               contentType = contentType.withStaticTyping();
           } else {
               // 03-Apr-2016, tatu: As per [databind#1178], may need to actually
               //   specialize (narrow) type sometimes, even if more commonly opposite
               //   is needed.
               Class<?> currRaw = contentType.getRawClass();
               try {
                   if (contentClass.isAssignableFrom(currRaw)) { // common case
                       contentType = tf.constructGeneralizedType(contentType, contentClass);
                   } else if (currRaw.isAssignableFrom(contentClass)) { // specialization, ok as well
                       contentType = tf.constructSpecializedType(contentType, contentClass);
                       // 27-Apr-2017, tatu: [databind#1592] ignore primitive<->wrapper refinements
                   } else {
                       throw new JsonMappingException(null,
                               String.format("Can not refine serialization content type %s into %s; types not related",
                                       contentType, contentClass.getName()));
                   }
               } catch (IllegalArgumentException iae) { // shouldn't really happen
                   throw new JsonMappingException(null,
                           String.format("Internal error: failed to refine value type of %s with concrete-type annotation (value %s), from '%s': %s",
                                   type, contentClass.getName(), a.getName(), iae.getMessage()),
                                   iae);
               }
           }
           type = type.withContentType(contentType);
       }
    }
    return type;
}

@Override
public T deserialize(JsonParser p, DeserializationContext ctxt) throws IOException
{
    // 22-Sep-2012, tatu: For 2.1, use this new method, may force coercion:
    String text = p.getValueAsString();
    if (text != null) { // has String representation
        if (text.length() == 0 || (text = text.trim()).length() == 0) {
            // 04-Feb-2013, tatu: Usually should become null; but not always
            return _deserializeFromEmptyString();
        }
        Exception cause = null;
        try {
            // 19-May-2017, tatu: Used to require non-null result (assuming `null`
            //    indicated error; but that seems wrong. Should be able to return
            //    `null` as value.
            if (_deserialize(text, ctxt) != null) {
                return _deserialize(text, ctxt);
            }
        } catch (IllegalArgumentException iae) {
            cause = iae;
        } catch (MalformedURLException me) {
            cause = me;
        }
        String msg = "not a valid textual representation";
        if (cause != null) {
            String m2 = cause.getMessage();
            if (m2 != null) {
                msg = msg + ", problem: "+m2;
            }
        }
        // 05-May-2016, tatu: Unlike most usage, this seems legit, so...
        JsonMappingException e = ctxt.weirdStringException(text, _valueClass, msg);
        if (cause != null) {
            e.initCause(cause);
        }
        // BEGIN SOLUTION
        for (DeserializationProblemHandler handler : ctxt.getDeserializationProblemHandlers()) {
            Object result = handler.handleWeirdStringValue(ctxt, _valueClass, text, msg);
            if (result != null) {
                return (T) result;
            }
        }
        // END SOLUTION
        throw e;
        // nothing to do here, yet? We'll fail anyway
    }
    JsonToken t = p.getCurrentToken();
    // [databind#381]
    if (t == JsonToken.START_ARRAY) {
        return _deserializeFromArray(p, ctxt);
    }
    if (t == JsonToken.VALUE_EMBEDDED_OBJECT) {
        // Trivial cases; null to null, instance of type itself returned as is
        Object ob = p.getEmbeddedObject();
        if (ob == null) {
            return null;
        }
        if (_valueClass.isAssignableFrom(ob.getClass())) {
            return (T) ob;
        }
        return _deserializeEmbedded(ob, ctxt);
    }
    return (T) ctxt.handleUnexpectedToken(_valueClass, p);
}

