static Document parseByteData(ByteBuffer byteData, String charsetName, String baseUri, Parser parser) {
    String docData;
    Document doc = null;
    if (charsetName == null) { // determine from meta. safe parse as UTF-8
        // look for <meta http-equiv="Content-Type" content="text/html;charset=gb2312"> or HTML5 <meta charset="gb2312">
        docData = Charset.forName(defaultCharset).decode(byteData).toString();
        doc = parser.parseInput(docData, baseUri);
        Element meta = doc.select("meta[http-equiv=content-type], meta[charset]").first();
        if (meta != null) { // if not found, will keep utf-8 as best attempt
            String foundCharset = meta.hasAttr("http-equiv") ? getCharsetFromContentType(meta.attr("content")) : meta.attr("charset");
            if (foundCharset != null && foundCharset.length() != 0 && !foundCharset.equals(defaultCharset)) { // need to re-decode
                charsetName = foundCharset;
                byteData.rewind();
                docData = Charset.forName(foundCharset).decode(byteData).toString();
                doc = null;
            }
        }
    } else { // specified by content type header (or by user on file load)
        Validate.notEmpty(charsetName, "Must set charset arg to character set of file to parse. Set to null to attempt to detect from HTML");
        docData = Charset.forName(charsetName).decode(byteData).toString();
    }
    if (doc == null) {
        // there are times where there is a spurious byte-order-mark at the start of the text. Shouldn't be present
        // in utf-8. If after decoding, there is a BOM, strip it; otherwise will cause the parser to go straight
        // into head mode

        doc = parser.parseInput(docData, baseUri);
        doc.outputSettings().charset(charsetName);
    }
    return doc;
}

Evaluator parse() {
    tq.consumeWhitespace();

    if (tq.matchesAny(combinators)) { // if starts with a combinator, use root as elements
        evals.add(new StructuralEvaluator.Root());
        combinator(tq.consume());
    } else {
        findElements();
    }

    while (!tq.isEmpty()) {
        // hierarchy and extras
        boolean seenWhite = tq.consumeWhitespace();

        if (tq.matchChomp(",")) {
            CombiningEvaluator.Or or = new CombiningEvaluator.Or(evals);
            evals.clear();
            evals.add(or);
            while (!tq.isEmpty()) {
                String subQuery = tq.chompTo(",");
                or.add(parse(subQuery));
            }
        } else if (tq.matchesAny(combinators)) {
            combinator(tq.consume());
        } else if (seenWhite) {
            combinator(' ');
        } else { // E.class, E#id, E[attr] etc. AND
            findElements(); // take next el, #. etc off queue
        }
    }

    if (evals.size() == 1)
        return evals.get(0);

    return new CombiningEvaluator.And(evals);
}

private void combinator(char combinator) {
    tq.consumeWhitespace();
    String subQuery = consumeSubQuery(); // support multi > childs
    Evaluator e;

    if (evals.size() == 1)
        e = evals.get(0);
    else
        e = new CombiningEvaluator.And(evals);
    evals.clear();
    Evaluator f = parse(subQuery);

    if (combinator == '>')
        evals.add(new CombiningEvaluator.And(f, new StructuralEvaluator.ImmediateParent(e)));
    else if (combinator == ' ')
        evals.add(new CombiningEvaluator.And(f, new StructuralEvaluator.Parent(e)));
    else if (combinator == '+')
        evals.add(new CombiningEvaluator.And(f, new StructuralEvaluator.ImmediatePreviousSibling(e)));
    else if (combinator == '~')
        evals.add(new CombiningEvaluator.And(f, new StructuralEvaluator.PreviousSibling(e)));
    else
        throw new Selector.SelectorParseException("Unknown combinator: " + combinator);
}

public Elements siblingElements() {
    if (parent() == null) {
        return new Elements();
    }
    return parent().children();
}

public Element nextElementSibling() {
    if (parent() == null) {
        return null;
    }
    List<Element> siblings = parent().children();
    Integer index = indexInList(this, siblings);
    Validate.notNull(index);
    if (siblings.size() > index+1)
        return siblings.get(index+1);
    else
        return null;
}

public Element previousElementSibling() {
    if (parent() == null) {
        return null;
    }
    List<Element> siblings = parent().children();
    Integer index = indexInList(this, siblings);
    Validate.notNull(index);
    if (index > 0)
        return siblings.get(index-1);
    else
        return null;
}

public Node previousSibling() {
    if (parentNode == null) {
        return null;
    }
    List<Node> siblings = parentNode.childNodes;
    Integer index = siblingIndex();
    Validate.notNull(index);
    if (index > 0)
        return siblings.get(index-1);
    else
        return null;
}

Character consumeCharacterReference(Character additionalAllowedCharacter, boolean inAttribute) {
    if (reader.isEmpty())
        return null;
    if (additionalAllowedCharacter != null && additionalAllowedCharacter == reader.current())
        return null;
    if (reader.matchesAny('\t', '\n', '\f', ' ', '<', '&'))
        return null;

    reader.mark();
    if (reader.matchConsume("#")) { // numbered
        boolean isHexMode = reader.matchConsumeIgnoreCase("X");
        String numRef = isHexMode ? reader.consumeHexSequence() : reader.consumeDigitSequence();
        if (numRef.length() == 0) { // didn't match anything
            characterReferenceError("numeric reference with no numerals");
            reader.rewindToMark();
            return null;
        }
        if (!reader.matchConsume(";"))
            characterReferenceError("missing semicolon"); // missing semi
        int charval = -1;
        try {
            int base = isHexMode ? 16 : 10;
            charval = Integer.valueOf(numRef, base);
        } catch (NumberFormatException e) {
        } // skip
        if (charval == -1 || (charval >= 0xD800 && charval <= 0xDFFF) || charval > 0x10FFFF) {
            characterReferenceError("character outside of valid range");
            return replacementChar;
        } else {
            // todo: implement number replacement table
            // todo: check for extra illegal unicode points as parse errors
            return (char) charval;
        }
    } else { // named
        // get as many letters and digits as possible, and look for matching entities. unconsume backwards till a match is found
        String nameRef = reader.consumeLetterDigitSequence();
        String origNameRef = new String(nameRef); // for error reporting. nameRef gets chomped looking for matches
        boolean looksLegit = reader.matches(';');
        boolean found = false;
        while (nameRef.length() > 0 && !found) {
            if (Entities.isNamedEntity(nameRef))
                found = true;
            else {
                nameRef = nameRef.substring(0, nameRef.length()-1);
                reader.unconsume();
            }
        }
        if (!found) {
            if (looksLegit) // named with semicolon
                characterReferenceError(String.format("invalid named referenece '%s'", origNameRef));
            reader.rewindToMark();
            return null;
        }
        if (inAttribute && (reader.matchesLetter() || reader.matchesDigit() || reader.matchesAny('=', '-', '_'))) {
            // don't want that to match
            reader.rewindToMark();
            return null;
        }
        if (!reader.matchConsume(";"))
            characterReferenceError("missing semicolon"); // missing semi
        return Entities.getCharacterByName(nameRef);
    }
}

void read(Tokeniser t, CharacterReader r) {
    if (r.matchesLetter()) {
        String name = r.consumeLetterSequence();
        t.tagPending.appendTagName(name.toLowerCase());
        t.dataBuffer.append(name);
        r.advance();
        return;
    }

    if (t.isAppropriateEndTagToken() && !r.isEmpty()) {
        char c = r.consume();
        switch (c) {
            case '\t':
            case '\n':
            case '\f':
            case ' ':
                t.transition(BeforeAttributeName);
                break;
            case '/':
                t.transition(SelfClosingStartTag);
                break;
            case '>':
                t.emitTagPending();
                t.transition(Data);
                break;
            default:
                t.dataBuffer.append(c);
                anythingElse(t, r);
                break;
        }
    } else {
        anythingElse(t, r);
    }
}

public Document clean(Document dirtyDocument) {
    Validate.notNull(dirtyDocument);

    Document clean = Document.createShell(dirtyDocument.baseUri());
    if (dirtyDocument.body() != null) {
