private boolean compute(Object left, Object right) {
    left = reduce(left);
    right = reduce(right);

    if (left instanceof InitialContext) {
        ((InitialContext) left).reset();
    }
    if (right instanceof InitialContext) {
        ((InitialContext) right).reset();
    }
    if (left instanceof Iterator && right instanceof Iterator) {
        return findMatch((Iterator) left, (Iterator) right);
    }
    if (left instanceof Iterator) {
        return containsMatch((Iterator) left, right);
    }
    if (right instanceof Iterator) {
        return containsMatch((Iterator) right, left);
    }
    if (Double.isNaN(InfoSetUtil.doubleValue(left)) || Double.isNaN(InfoSetUtil.doubleValue(right))) {
        return false;
    }
    double ld = InfoSetUtil.doubleValue(left);
    double rd = InfoSetUtil.doubleValue(right);
    return evaluateCompare(ld == rd ? 0 : ld < rd ? -1 : 1);
}

protected boolean equal(Object l, Object r) {
    if (l instanceof Pointer && r instanceof Pointer) {
        if (l.equals(r)) {
            return true;
        }
    }
    if (l instanceof Pointer) {
        l = ((Pointer) l).getValue();
    }

    if (r instanceof Pointer) {
        r = ((Pointer) r).getValue();
    }

    if (l == r) {
        return true;
    }
    if (l instanceof Boolean || r instanceof Boolean) {
        return (InfoSetUtil.booleanValue(l) == InfoSetUtil.booleanValue(r));
    }
    //if either side is NaN, no comparison returns true:
    if (l instanceof Number || r instanceof Number) {
        if (Double.isNaN(InfoSetUtil.doubleValue(l)) || Double.isNaN(InfoSetUtil.doubleValue(r))) {
            return false;
        }
        return (InfoSetUtil.doubleValue(l) == InfoSetUtil.doubleValue(r));
    }
    if (l instanceof String || r instanceof String) {
        return (
            InfoSetUtil.stringValue(l).equals(InfoSetUtil.stringValue(r)));
    }
    return l != null && l.equals(r);
}

protected final boolean evaluateCompare(int compare) {
    if (compare == 0) {
        return true;
    }
    return compare < 0;
}

private Attr getAttribute(Element element, QName name) {
    String testPrefix = name.getPrefix();
    String testNS = null;

    if (testPrefix != null) {
        testNS = parent.getNamespaceURI(testPrefix);
    }

    if (testNS != null) {
        Attr attr = element.getAttributeNodeNS(testNS, name.getName());
        if (attr != null) {
            return attr;
        }

        // This may mean that the parser does not support NS for
        // attributes, example - the version of Crimson bundled
        // with JDK 1.4.0
        NamedNodeMap nnm = element.getAttributes();
        for (int i = 0; i < nnm.getLength(); i++) {
            attr = (Attr) nnm.item(i);
            if (testAttr(attr, name)) {
                return attr;
            }
        }
        return null;
    }
    // Add the following lines to handle attributes without a namespace
    if (testPrefix == null) {
        return element.getAttributeNode(name.getName());
    }
    return null;
}

public JDOMAttributeIterator(NodePointer parent, QName name) {
    this.parent = parent;
    if (parent.getNode() instanceof Element) {
        Element element = (Element) parent.getNode();
        String prefix = name.getPrefix();
        Namespace ns = null;
        if (prefix != null) {
            if (prefix.equals("xml")) {
                ns = Namespace.XML_NAMESPACE;
            }
            else {
                    ns = element.getNamespace(prefix);
                    if (ns == null) {
                        // TBD: no attributes
                        attributes = Collections.EMPTY_LIST;
                        return;
                    }
            }
        }
        else {
            ns = Namespace.NO_NAMESPACE;
        }

        String lname = name.getName();
        if (!lname.equals("*")) {
            attributes = new ArrayList();
            if (ns != null) {
                Attribute attr = element.getAttribute(lname, ns);
                if (attr != null) {
                    attributes.add(attr);
                }
            }
            // Add the following lines to handle attributes without a namespace
            else {
                Attribute attr = element.getAttribute(lname);
                if (attr != null) {
                    attributes.add(attr);
                }
            }
        }
        else {
            attributes = new ArrayList();
            List allAttributes = element.getAttributes();
            for (int i = 0; i < allAttributes.size(); i++) {
                Attribute attr = (Attribute) allAttributes.get(i);
                if (attr.getNamespace().equals(ns)) {
                    attributes.add(attr);
                }
            }
            // Add the following lines to handle attributes without a namespace
            else {
                attributes.addAll(element.getAttributes());
            }
        }
    }
}

public static boolean testNode(Node node, NodeTest test) {
    if (test == null) {
        return true;
    }
    if (test instanceof NodeNameTest) {
        if (node.getNodeType() != Node.ELEMENT_NODE) {
            return false;
        }

        NodeNameTest nodeNameTest = (NodeNameTest) test;
        QName testName = nodeNameTest.getNodeName();
        String namespaceURI = nodeNameTest.getNamespaceURI();
        boolean wildcard = nodeNameTest.isWildcard();
        String testPrefix = testName.getPrefix();
        if (wildcard && testPrefix == null) {
            return true;
        }
        if (wildcard
            || testName.getName()
                    .equals(DOMNodePointer.getLocalName(node))) {
            String nodeNS = DOMNodePointer.getNamespaceURI(node);
            if (testPrefix != null && nodeNS == null) {
                // Register the namespace if it's not already registered
                nodeNS = DOMNodePointer.getNamespaceURI(testPrefix, node);
                if (nodeNS != null) {
                    DOMNodePointer.registerNamespace(testPrefix, nodeNS);
                }
            }
            return equalStrings(namespaceURI, nodeNS);
        }
        return false;
    }
    if (test instanceof NodeTypeTest) {
        int nodeType = node.getNodeType();
        switch (((NodeTypeTest) test).getNodeType()) {
            case Compiler.NODE_TYPE_NODE :
                return nodeType == Node.ELEMENT_NODE
                        || nodeType == Node.DOCUMENT_NODE;
            case Compiler.NODE_TYPE_TEXT :
                return nodeType == Node.CDATA_SECTION_NODE
                    || nodeType == Node.TEXT_NODE;
            case Compiler.NODE_TYPE_COMMENT :
                return nodeType == Node.COMMENT_NODE;
            case Compiler.NODE_TYPE_PI :
                return nodeType == Node.PROCESSING_INSTRUCTION_NODE;
        }
        return false;
    }
    if (test instanceof ProcessingInstructionTest) {
        if (node.getNodeType() == Node.PROCESSING_INSTRUCTION_NODE) {
            String testPI = ((ProcessingInstructionTest) test).getTarget();
            String nodePI = ((ProcessingInstruction) node).getTarget();
            return testPI.equals(nodePI);
        }
    }
    return false;
}

