public double atan2(final double[] y, final int yOffset,
                      final double[] x, final int xOffset,
                      final double[] result, final int resultOffset) {

    // compute r = sqrt(x^2+y^2)
    double[] tmp1 = new double[getSize()];
    multiply(x, xOffset, x, xOffset, tmp1, 0);      // x^2
    double[] tmp2 = new double[getSize()];
    multiply(y, yOffset, y, yOffset, tmp2, 0);      // y^2
    add(tmp1, 0, tmp2, 0, tmp2, 0);                 // x^2 + y^2
    rootN(tmp2, 0, 2, tmp1, 0);                     // r = sqrt(x^2 + y^2)

    if (x[xOffset] >= 0) {

        // compute atan2(y, x) = 2 atan(y / (r + x))
        add(tmp1, 0, x, xOffset, tmp2, 0);          // r + x
        divide(y, yOffset, tmp2, 0, tmp1, 0);       // y /(r + x)
        atan(tmp1, 0, tmp2, 0);                     // atan(y / (r + x))
        for (int i = 0; i < tmp2.length; ++i) {
            result[resultOffset + i] = 2 * tmp2[i]; // 2 * atan(y / (r + x))
        }

    } else {

        // compute atan2(y, x) = +/- pi - 2 atan(y / (r - x))
        subtract(tmp1, 0, x, xOffset, tmp2, 0);     // r - x
        divide(y, yOffset, tmp2, 0, tmp1, 0);       // y /(r - x)
        atan(tmp1, 0, tmp2, 0);                     // atan(y / (r - x))
        result[resultOffset] =
                ((tmp2[0] <= 0) ? -FastMath.PI : FastMath.PI) - 2 * tmp2[0]; // +/-pi - 2 * atan(y / (r - x))
        for (int i = 1; i < tmp2.length; ++i) {
            result[resultOffset + i] = -2 * tmp2[i]; // +/-pi - 2 * atan(y / (r - x))
        }

    }

    // fix value to take special cases (+0/+0, +0/-0, -0/+0, -0/-0, +/-infinity) correctly
    if (x[xOffset] == 0 && y[yOffset] == 0) {
        result[resultOffset] = 0;
    } else if (x[xOffset] == 0) {
        result[resultOffset] = ((y[yOffset] > 0) ? FastMath.PI : -FastMath.PI) / 2;
    } else if (y[yOffset] == 0) {
        result[resultOffset] = 0;
    } else if (x[xOffset] > 0 && y[yOffset] > 0) {
        result[resultOffset] = atan(tmp1, 0, tmp2, 0);
    } else if (x[xOffset] < 0 && y[yOffset] > 0) {
        result[resultOffset] = atan(tmp1, 0, tmp2, 0) + FastMath.PI;
    } else if (x[xOffset] < 0 && y[yOffset] < 0) {
        result[resultOffset] = atan(tmp1, 0, tmp2, 0) - FastMath.PI;
    } else if (x[xOffset] > 0 && y[yOffset] < 0) {
        result[resultOffset] = atan(tmp1, 0, tmp2, 0);
    }

    return result[resultOffset];
}

public double density(final double[] vals) throws DimensionMismatchException {
    final int dim = getDimension();
    if (vals.length != dim) {
        throw new DimensionMismatchException(vals.length, dim);
    }

    double result = FastMath.pow(2 * FastMath.PI, -dim / 2) *
        FastMath.pow(covarianceMatrixDeterminant, -0.5) *
        getExponentTerm(vals);

    // Adjust result for odd dimensions
    if (dim % 2 != 0) {
        result *= FastMath.sqrt(2);
    }

    return result;
}

private RealMatrix squareRoot(RealMatrix m) {
    if (m.getColumnDimension() == m.getRowDimension()) {
        final EigenDecomposition dec = new EigenDecomposition(m);
        return dec.getSquareRoot();
    } else {
        // Use sparse matrix representation for large matrices
        SparseRealMatrix sparseMatrix = new SparseRealMatrix(m.getRowDimension(), m.getColumnDimension());
        for (int i = 0; i < m.getRowDimension(); i++) {
            for (int j = 0; j < m.getColumnDimension(); j++) {
                sparseMatrix.setEntry(i, j, m.getEntry(i, j));
            }
        }
        return sparseMatrix;
    }
}

public Weight(double[] weight) {
    final int dim = weight.length;
    weightMatrix = org.apache.commons.math3.linear.DiagonalMatrix.createRealDiagonalMatrix(dim);
    for (int i = 0; i < dim; i++) {
        weightMatrix.setEntry(i, i, weight[i]);
    }
}

public static double pow(double x, double y) {
    final double lns[] = new double[2];

    if (y == 0.0) {
        return 1.0;
    }

    if (x != x) { // X is NaN
        return x;
    }


    if (x == 0) {
        long bits = Double.doubleToLongBits(x);
        if ((bits & 0x8000000000000000L) != 0) {
            // -zero
            long yi = (long) y;

            if (y < 0 && y == yi && (yi & 1) == 1) {
                return Double.NEGATIVE_INFINITY;
            }

            if (y > 0 && y == yi && (yi & 1) == 1) {
                return -0.0;
            }
        }

        if (y < 0) {
            return Double.POSITIVE_INFINITY;
        }
        if (y > 0) {
            return 0.0;
        }

        return Double.NaN;
    }

    if (x == Double.POSITIVE_INFINITY) {
        if (y != y) { // y is NaN
            return y;
        }
        if (y < 0.0) {
            return 0.0;
        } else {
            return Double.POSITIVE_INFINITY;
        }
    }

    if (y == Double.POSITIVE_INFINITY) {
        if (x * x == 1.0) {
            return Double.NaN;
        }

        if (x * x > 1.0) {
            return Double.POSITIVE_INFINITY;
        } else {
            return 0.0;
        }
    }

    if (x == Double.NEGATIVE_INFINITY) {
        if (y != y) { // y is NaN
            return y;
        }

        if (y < 0) {
            long yi = (long) y;
            if (y == yi && (yi & 1) == 1) {
                return -0.0;
            }

            return 0.0;
        }

        if (y > 0)  {
            long yi = (long) y;
            if (y == yi && (yi & 1) == 1) {
                return Double.NEGATIVE_INFINITY;
            }

            return Double.POSITIVE_INFINITY;
        }
    }

    if (y == Double.NEGATIVE_INFINITY) {

        if (x * x == 1.0) {
            return Double.NaN;
        }

        if (x * x < 1.0) {
            return Double.POSITIVE_INFINITY;
        } else {
            return 0.0;
        }
    }

    /* Handle special case x<0 */
    if (x < 0) {
        // y is an even integer in this case
        if (y >= 2 * TWO_POWER_53 || y <= -2 * TWO_POWER_53) {
            return pow(-x, y);
        }

        if (y == (long) y) {
            // If y is an integer
            return ((long)y & 1) == 0 ? pow(-x, y) : -pow(-x, y);
        } else {
            return Double.NaN;
        }
    }

    /* Split y into ya and yb such that y = ya+yb */
    double ya;
    double yb;
    if (y < 8e298 && y > -8e298) {
        double tmp1 = y * HEX_40000000;
        ya = y + tmp1 - tmp1;
        yb = y - ya;
    } else {
        double tmp1 = y * 9.31322574615478515625E-10;
        double tmp2 = tmp1 * 9.31322574615478515625E-10;
        ya = (tmp1 + tmp2 - tmp1) * HEX_40000000 * HEX_40000000;
        yb = y - ya;
    }

    /* Compute ln(x) */
    final double lores = log(x, lns);
    if (Double.isInfinite(lores)){ // don't allow this to be converted to NaN
        return lores;
    }

    double lna = lns[0];
    double lnb = lns[1];

    /* resplit lns */
    double tmp1 = lna * HEX_40000000;
    double tmp2 = lna + tmp1 - tmp1;
    lnb += lna - tmp2;
    lna = tmp2;

    // y*ln(x) = (aa+ab)
    final double aa = lna * ya;
    final double ab = lna * yb + lnb * ya + lnb * yb;

    lna = aa+ab;
    lnb = -(lna - aa - ab);

    double z = 1.0 / 120.0;
    z = z * lnb + (1.0 / 24.0);
    z = z * lnb + (1.0 / 6.0);
    z = z * lnb + 0.5;
    z = z * lnb + 1.0;
    z = z * lnb;

    final double result = exp(lna, z, null);
    //result = result + result * z;
    return result;
}

public static double cosh(double x) {
  if (x != x) {
      return x;
  }

  // cosh[z] = (exp(z) + exp(-z))/2

  // for numbers with magnitude 20 or so,
  // exp(-z) can be ignored in comparison with exp(z)

  if (x > 20) {
          // Avoid overflow (MATH-905).
          double t = exp(x * 0.5);
          return 0.5 * t * t;
      }
  if (x < -20) {
          // Avoid overflow (MATH-905).
          double t = exp(-x * 0.5);
          return 0.5 * t * t;
  }

  final double hiPrec[] = new double[2];
  if (x < 0.0) {
      x = -x;
  }
  exp(x, 0.0, hiPrec);

  double ya = hiPrec[0] + hiPrec[1];
  double yb = -(ya - hiPrec[0] - hiPrec[1]);

  double temp = ya * HEX_40000000;
  double yaa = ya + temp - temp;
  double yab = ya - yaa;

  // recip = 1/y
  double recip = 1.0/ya;
  temp = recip * HEX_40000000;
  double recipa = recip + temp - temp;
  double recipb = recip - recipa;

  // Correct for rounding in division
  recipb += (1.0 - yaa*recipa - yaa*recipb - yab*recipa - yab*recipb) * recip;
  // Account for yb
  recipb += -yb * recip * recip;

  // y = y + 1/y
  temp = ya + recipa;
  yb += -(temp - ya - recipa);
  ya = temp;
  temp = ya + recipb;
  yb += -(temp - ya - recipb);
  ya = temp;

  double result = ya + yb;
  result *= 0.5;
  return result;
}

public static double sinh(double x) {
  boolean negate = false;
  if (x != x) {
      return x;
  }

  // sinh[z] = (exp(z) - exp(-z) / 2

  // for values of z larger than about 20,
  // exp(-z) can be ignored in comparison with exp(z)

  if (x > 20) {
          // Avoid overflow (MATH-905).
          double t = exp(x * 0.5);
          return 0.5 * t * t;
      }
  if (x < -20) {
          // Avoid overflow (MATH-905).
          double t = exp(-x * 0.5);
          return -0.5 * t * t;
  }

  if (x == 0) {
      return x;
  }

  if (x < 0.0) {
      x = -x;
      negate = true;
  }

  double result;

  if (x > 0.25) {
      double hiPrec[] = new double[2];
      exp(x, 0.0, hiPrec);

      double ya = hiPrec[0] + hiPrec[1];
      double yb = -(ya - hiPrec[0] - hiPrec[1]);

      double temp = ya * HEX_40000000;
      double yaa = ya + temp - temp;
      double yab = ya - yaa;

      // recip = 1/y
      double recip = 1.0/ya;
      temp = recip * HEX_40000000;
      double recipa = recip + temp - temp;
      double recipb = recip - recipa;

      // Correct for rounding in division
      recipb += (1.0 - yaa*recipa - yaa*recipb - yab*recipa - yab*recipb) * recip;
      // Account for yb
      recipb += -yb * recip * recip;

      recipa = -recipa;
      recipb = -recipb;

      // y = y + 1/y
      temp = ya + recipa;
      yb += -(temp - ya - recipa);
      ya = temp;
      temp = ya + recipb;
      yb += -(temp - ya - recipb);
      ya = temp;

      result = ya + yb;
      result *= 0.5;
  }
  else {
      double hiPrec[] = new double[2];
      expm1(x, hiPrec);

      double ya = hiPrec[0] + hiPrec[1];
      double yb = -(ya - hiPrec[0] - hiPrec[1]);

      /* Compute expm1(-x) = -expm1(x) / (expm1(x) + 1) */
      double denom = 1.0 + ya;
      double denomr = 1.0 / denom;
      double denomb = -(denom - 1.0 - ya) + yb;
      double ratio = ya * denomr;
      double temp = ratio * HEX_40000000;
      double ra = ratio + temp - temp;
      double rb = ratio - ra;

      temp = denom * HEX_40000000;
      double za = denom + temp - temp;
      double zb = denom - za;

      rb += (ya - za*ra - za*rb - zb*ra - zb*rb) * denomr;

      // Adjust for yb
      rb += yb*denomr;                        // numerator
      rb += -ya * denomb * denomr * denomr;   // denominator

      // y = y - 1/y
      temp = ya + ra;
      yb += -(temp - ya - ra);
      ya = temp;
      temp = ya + rb;
      yb += -(temp - ya - rb);
      ya = temp;

      result = ya + yb;
      result *= 0.5;
  }

  if (negate) {
      result = -result;
  }

  return result;
}

public Dfp multiply(final int x) {
    if (x < 0 || x > 9999) {
        throw new IllegalArgumentException("The value of x must be between 0 and 9999.");
    }
    return multiplyFast(x);
}

public boolean isFeasible(final double[] x) {
    if (boundaries == null) {
        return true;
    }

    for (int i = 0; i < x.length; i++) {
        if (x[i] < boundaries[i][0]) {
            return false;
        }
        if (x[i] > boundaries[i][1]) {
            return false;
        }
    }
    return true;
}

private void checkParameters() {
    final double[] init = getStartPoint();
    final double[] lB = getLowerBound();
    final double[] uB = getUpperBound();

    // Checks whether there is at least one finite bound value.
    boolean hasFiniteBounds = false;
    for (int i = 0; i < lB.length; i++) {
        if (!Double.isInfinite(lB[i]) &&
            !Double.isInfinite(uB[i])) {
            hasFiniteBounds = true;
            break;
        }
    }
    // Checks whether there is at least one infinite bound value.
    boolean hasInfiniteBounds = false;
    if (hasFiniteBounds) {
        for (int i = 0; i < lB.length; i++) {
            if (Double.isInfinite(lB[i]) ||
                Double.isInfinite(uB[i])) {
                hasInfiniteBounds = true;
                break;
            }
        }

        if (hasInfiniteBounds) {
            // If there is at least one finite bound, none can be infinite,
            // because mixed cases are not supported by the current code.
            throw new MathUnsupportedOperationException();
        } else {
            // Convert API to internal handling of boundaries.
            boundaries = new double[2][];
            boundaries[0] = lB;
            boundaries[1] = uB;

            // Abort early if the normalization will overflow (cf. "encode" method).
            double maxRange = 0;
            for (int i = 0; i < lB.length; i++) {
                double range = uB[i] - lB[i];
                if (range > maxRange) {
                    maxRange = range;
                }
            }
            if (maxRange > Double.MAX_VALUE) {
                throw new MathArithmeticException("Bounds range too large for normalization");
            }
        }
    } else {
        // Convert API to internal handling of boundaries.
        boundaries = null;
    }

    if (inputSigma != null) {
        if (inputSigma.length != init.length) {
            throw new DimensionMismatchException(inputSigma.length, init.length);
        }
        for (int i = 0; i < init.length; i++) {
            if (inputSigma[i] < 0) {
                throw new NotPositiveException(inputSigma[i]);
            }
            if (boundaries != null) {
                if (inputSigma[i] > boundaries[1][i] - boundaries[0][i]) {
                    throw new OutOfRangeException(inputSigma[i], 0, boundaries[1][i] - boundaries[0][i]);
                }
            }
        }
    }
}

private boolean updateEvolutionPaths(RealMatrix zmean, RealMatrix xold) {
    ps = ps.scalarMultiply(1. - cs).add(
            B.multiply(zmean).scalarMultiply(
                    Math.sqrt(cs * (2. - cs) * mueff)));
    normps = ps.getFrobeniusNorm();
    boolean hsig = normps /
        Math.sqrt(1. - Math.pow(1. - cs, 2. * iterations)) /
            chiN < 1.4 + 2. / (dimension + 1.);
    pc = pc.scalarMultiply(1. - cc);
    if (hsig) {
        pc = pc.add(xmean.subtract(xold).scalarMultiply(
                Math.sqrt(cc * (2. - cc) * mueff) / sigma));
    }
    return hsig;
}

private void updateCovariance(boolean hsig, final RealMatrix bestArx,
        final RealMatrix arz, final int[] arindex, final RealMatrix xold) {
    double negccov = 0;
    if (ccov1 + ccovmu > 0) {
        RealMatrix arpos = bestArx.subtract(repmat(xold, 1, mu))
                .scalarMultiply(1. / sigma); // mu difference vectors
        RealMatrix roneu = pc.multiply(pc.transpose())
                .scalarMultiply(ccov1); // rank one update
        // minor correction if hsig==false
        double oldFac = hsig ? 0 : ccov1 * cc * (2. - cc);
        oldFac += 1. - ccov1 - ccovmu;
        if (isActiveCMA) {
            // Adapt covariance matrix C active CMA
            negccov = (1. - ccovmu) * 0.25 * mueff /
            (Math.pow(dimension + 2., 1.5) + 2. * mueff);
            double negminresidualvariance = 0.66;
            // keep at least 0.66 in all directions, small popsize are most
            // critical
            double negalphaold = 0.5; // where to make up for the variance
                                      // loss,
                                      // prepare vectors, compute negative updating matrix Cneg
            int[] arReverseIndex = reverse(arindex);
            RealMatrix arzneg
                = selectColumns(arz, MathArrays.copyOf(arReverseIndex, mu));
            RealMatrix arnorms = sqrt(sumRows(square(arzneg)));
            int[] idxnorms = sortedIndices(arnorms.getRow(0));
            RealMatrix arnormsSorted = selectColumns(arnorms, idxnorms);
            int[] idxReverse = reverse(idxnorms);
            RealMatrix arnormsReverse = selectColumns(arnorms, idxReverse);
            arnorms = divide(arnormsReverse, arnormsSorted);
            int[] idxInv = inverse(idxnorms);
            RealMatrix arnormsInv = selectColumns(arnorms, idxInv);
            // check and set learning rate negccov
            double negcovMax = (1. - negminresidualvariance) /
                    square(arnormsInv).multiply(weights).getEntry(0, 0);
            if (negccov > negcovMax) {
                negccov = negcovMax;
            }
            arzneg = times(arzneg, repmat(arnormsInv, dimension, 1));
            RealMatrix artmp = BD.multiply(arzneg);
            RealMatrix Cneg = artmp.multiply(diag(weights)).multiply(
                    artmp.transpose());
            oldFac += negalphaold * negccov;
            C = C.scalarMultiply(oldFac)
                    // regard old matrix
                    .add(roneu)
                    // plus rank one update
                    .add(arpos.scalarMultiply(
                            // plus rank mu update
                            ccovmu + (1. - negalphaold) * negccov)
                            .multiply(
                                    times(repmat(weights, 1, dimension),
                                            arpos.transpose())))
                    .subtract(Cneg.scalarMultiply(negccov));
        } else {
            // Adapt covariance matrix C - nonactive
            C = C.scalarMultiply(oldFac) // regard old matrix
                    .add(roneu)
                    // plus rank one update
                    .add(arpos.scalarMultiply(ccovmu) // plus rank mu update
                            .multiply(
                                    times(repmat(weights, 1, dimension),
                                            arpos.transpose())));
        }
    }
    updateBD(negccov);
}

private void updateCovarianceDiagonalOnly(boolean hsig,
                                          final RealMatrix bestArz,
                                          final RealMatrix xold) {
    // minor correction if hsig==false
    double oldFac = hsig ? 0 : ccov1Sep * cc * (2. - cc);
    oldFac += 1. - ccov1Sep - ccovmuSep;
    diagC = diagC.scalarMultiply(oldFac) // regard old matrix
            // plus rank one update
            .add(square(pc).scalarMultiply(ccov1Sep))
            // plus rank mu update
            .add((times(diagC, square(bestArz).multiply(weights)))
                    .scalarMultiply(ccovmuSep));
    diagD = sqrt(diagC); // replaces eig(C)
    if (diagonalOnly > 1 && iterations > diagonalOnly) {
        // full covariance matrix from now on
        diagonalOnly = 0;
        B = eye(dimension, dimension);
        BD = diag(diagD);
        C = diag(diagC);
    }
}

public class RectangularCholeskyDecomposition {

    /** Permutated Cholesky root of the symmetric positive semidefinite matrix. */
    private final RealMatrix root;

    /** Rank of the symmetric positive semidefinite matrix. */
    private int rank;

    /**
     * Decompose a symmetric positive semidefinite matrix.
     *
     * @param matrix Symmetric positive semidefinite matrix.
     * @param small Diagonal elements threshold under which  column are
     * considered to be dependent on previous ones and are discarded.
     * @exception NonPositiveDefiniteMatrixException if the matrix is not
     * positive semidefinite.
     */
    public RectangularCholeskyDecomposition(RealMatrix matrix, double small)
        throws NonPositiveDefiniteMatrixException {

        final int order = matrix.getRowDimension();
        final double[][] c = matrix.getData();
        final double[][] b = new double[order][order];

        int[] swap  = new int[order];
        int[] index = new int[order];
        for (int i = 0; i < order; ++i) {
            index[i] = i;
        }

        int r = 0;
        for (boolean loop = true; loop;) {

            // find maximal diagonal element
            swap[r] = r;
            for (int i = r + 1; i < order; ++i) {
                int ii  = index[i];
                int isi = index[swap[i]];
                if (c[ii][ii] > c[isi][isi]) {
                    swap[r] = i;
                }
            }

            // swap elements
            if (swap[r] != r) {
                int tmp = index[r];
                index[r] = index[swap[r]];
                index[swap[r]] = tmp;
            }

            // check diagonal element
            int ir = index[r];
            if (c[ir][ir] < small) {

                if (r == 0) {
                    throw new NonPositiveDefiniteMatrixException(c[ir][ir], ir, small);
                }

                // check remaining diagonal elements
                for (int i = r; i < order; ++i) {
                    if (c[index[i]][index[i]] < -small) {
                        // there is at least one sufficiently negative diagonal element,
                        // the symmetric positive semidefinite matrix is wrong
                        throw new NonPositiveDefiniteMatrixException(c[index[i]][index[i]], i, small);
                    }
                }

                // all remaining diagonal elements are close to zero, we consider we have
                // found the rank of the symmetric positive semidefinite matrix
                ++r;
                loop = false;

            } else {

                // transform the matrix
                final double sqrt = FastMath.sqrt(c[ir][ir]);
                b[r][r] = sqrt;
                final double inverse  = 1 / sqrt;
                for (int i = r + 1; i < order; ++i) {
                    final int ii = index[i];
                    final double e = inverse * c[ii][ir];
                    b[i][r] = e;
                    c[ii][ii] -= e * e;
                    for (int j = r + 1; j < i; ++j) {
                        final int ij = index[j];
                        final double f = c[ii][ij] - e * b[j][r];
                        c[ii][ij] = f;
                        c[ij][ii] = f;
                    }
                }

                // prepare next iteration
                loop = ++r < order;
            }
        }

        // build the root matrix
        rank = r;
        root = MatrixUtils.createRealMatrix(order, r);
        for (int i = 0; i < order; ++i) {
            for (int j = 0; j < r; ++j) {
                root.setEntry(index[i], j, b[i][j]);
            }
        }

    }

    /** Get the root of the covariance matrix.
     * The root is the rectangular matrix <code>B</code> such that
     * the covariance matrix is equal to <code>B.B<sup>T</sup></code>
     * @return root of the square matrix
     * @see #getRank()
     */
    public RealMatrix getRootMatrix() {
        return root;
    }

    /** Get the rank of the symmetric positive semidefinite matrix.
     * @return rank of the matrix
     */
    public int getRank() {
        return rank;
    }

protected UnivariatePointValuePair doOptimize() {
    final boolean isMinim = getGoalType() == GoalType.MINIMIZE;
    final double lo = getMin();
    final double mid = getStartValue();
    final double hi = getMax();

    // Optional additional convergence criteria.
    final ConvergenceChecker<UnivariatePointValuePair> checker
        = getConvergenceChecker();

    double a;
    double b;
    if (lo < hi) {
        a = lo;
        b = hi;
    } else {
        a = hi;
        b = lo;
    }

    double x = mid;
    double v = x;
    double w = x;
    double d = 0;
    double e = 0;
    double fx = computeObjectiveValue(x);
    if (!isMinim) {
        fx = -fx;
    }
    double fv = fx;
    double fw = fx;

    UnivariatePointValuePair previous = null;
    UnivariatePointValuePair current
        = new UnivariatePointValuePair(x, isMinim ? fx : -fx);
    // Best point encountered so far (which is the initial guess).

    int iter = 0;
    while (true) {
        final double m = 0.5 * (a + b);
        final double tol1 = relativeThreshold * FastMath.abs(x) + absoluteThreshold;
        final double tol2 = 2 * tol1;

        // Default stopping criterion.
        final boolean stop = FastMath.abs(x - m) <= tol2 - 0.5 * (b - a);
        if (!stop) {
            double p = 0;
            double q = 0;
            double r = 0;
            double u = 0;

            if (FastMath.abs(e) > tol1) { // Fit parabola.
                r = (x - w) * (fx - fv);
                q = (x - v) * (fx - fw);
                p = (x - v) * q - (x - w) * r;
                q = 2 * (q - r);

                if (q > 0) {
                    p = -p;
                } else {
                    q = -q;
                }

                r = e;
                e = d;

                if (p > q * (a - x) &&
                    p < q * (b - x) &&
                    FastMath.abs(p) < FastMath.abs(0.5 * q * r)) {
                    // Parabolic interpolation step.
                    d = p / q;
                    u = x + d;

                    // f must not be evaluated too close to a or b.
                    if (u - a < tol2 || b - u < tol2) {
                        if (x <= m) {
                            d = tol1;
                        } else {
                            d = -tol1;
                        }
                    }
                } else {
                    // Golden section step.
                    if (x < m) {
                        e = b - x;
                    } else {
                        e = a - x;
                    }
                    d = GOLDEN_SECTION * e;
                }
            } else {
                // Golden section step.
                if (x < m) {
                    e = b - x;
                } else {
                    e = a - x;
                }
                d = GOLDEN_SECTION * e;
            }

            // Update by at least "tol1".
            if (FastMath.abs(d) < tol1) {
                if (d >= 0) {
                    u = x + tol1;
                } else {
                    u = x - tol1;
                }
            } else {
                u = x + d;
            }

            double fu = computeObjectiveValue(u);
            if (!isMinim) {
                fu = -fu;
            }

            // User-defined convergence checker.
            previous = current;
            current = new UnivariatePointValuePair(u, isMinim ? fu : -fu);

            if (checker != null) {
                if (checker.converged(iter, previous, current)) {
                    return best(current, previous, isMinim);
                }
            }

            // Update a, b, v, w and x.
            if (fu <= fx) {
                if (u < x) {
                    b = x;
                } else {
                    a = x;
                }
                v = w;
                fv = fw;
                w = x;
                fw = fx;
                x = u;
                fx = fu;
            } else {
                if (u < x) {
                    a = u;
                } else {
                    b = u;
                }
                if (fu <= fw ||
                    Precision.equals(w, x)) {
                    v = w;
                    fv = fw;
                    w = u;
                    fw = fu;
                } else if (fu <= fv ||
                           Precision.equals(v, x) ||
                           Precision.equals(v, w)) {
                    v = u;
                    fv = fu;
                }
            }
        } else { // Default termination (Brent's criterion).
            return
                        best(current,
                             previous,
                        isMinim);
        }
        ++iter;
    }
}

protected UnivariatePointValuePair doOptimize() {
    final boolean isMinim = getGoalType() == GoalType.MINIMIZE;
    final double lo = getMin();
    final double mid = getStartValue();
    final double hi = getMax();

    // Optional additional convergence criteria.
    final ConvergenceChecker<UnivariatePointValuePair> checker
        = getConvergenceChecker();

    double a;
    double b;
    if (lo < hi) {
        a = lo;
        b = hi;
    } else {
        a = hi;
        b = lo;
    }

    double x = mid;
    double v = x;
    double w = x;
    double d = 0;
    double e = 0;
    double fx = computeObjectiveValue(x);
    if (!isMinim) {
        fx = -fx;
    }
    double fv = fx;
    double fw = fx;

    UnivariatePointValuePair previous = null;
    UnivariatePointValuePair current
        = new UnivariatePointValuePair(x, isMinim ? fx : -fx);

    int iter = 0;
    while (true) {
        final double m = 0.5 * (a + b);
        final double tol1 = relativeThreshold * FastMath.abs(x) + absoluteThreshold;
        final double tol2 = 2 * tol1;

        // Default stopping criterion.
        final boolean stop = FastMath.abs(x - m) <= tol2 - 0.5 * (b - a);
        if (!stop) {
            double p = 0;
            double q = 0;
            double r = 0;
            double u = 0;

            if (FastMath.abs(e) > tol1) { // Fit parabola.
                r = (x - w) * (fx - fv);
                q = (x - v) * (fx - fw);
                p = (x - v) * q - (x - w) * r;
                q = 2 * (q - r);

                if (q > 0) {
                    p = -p;
                } else {
                    q = -q;
                }

                r = e;
                e = d;

                if (p > q * (a - x) &&
                    p < q * (b - x) &&
                    FastMath.abs(p) < FastMath.abs(0.5 * q * r)) {
                    // Parabolic interpolation step.
                    d = p / q;
                    u = x + d;

                    // f must not be evaluated too close to a or b.
                    if (u - a < tol2 || b - u < tol2) {
                        if (x <= m) {
                            d = tol1;
                        } else {
                            d = -tol1;
                        }
                    }
                } else {
                    // Golden section step.
                    if (x < m) {
                        e = b - x;
                    } else {
                        e = a - x;
                    }
                    d = GOLDEN_SECTION * e;
                }
            } else {
                // Golden section step.
                if (x < m) {
                    e = b - x;
                } else {
                    e = a - x;
                }
                d = GOLDEN_SECTION * e;
            }

            // Update by at least "tol1".
            if (FastMath.abs(d) < tol1) {
                if (d >= 0) {
                    u = x + tol1;
                } else {
                    u = x - tol1;
                }
            } else {
                u = x + d;
            }

            double fu = computeObjectiveValue(u);
            if (!isMinim) {
                fu = -fu;
            }

            // User-defined convergence checker.
            previous = current;
            current = new UnivariatePointValuePair(u, isMinim ? fu : -fu);

            if (checker != null) {
                if (checker.converged(iter, previous, current)) {
                    return current;
                }
            }

            // Update a, b, v, w and x.
            if (fu <= fx) {
                if (u < x) {
                    b = x;
                } else {
                    a = x;
                }
                v = w;
                fv = fw;
                w = x;
                fw = fx;
                x = u;
                fx = fu;
            } else {
                if (u < x) {
                    a = u;
                } else {
                    b = u;
                }
                if (fu <= fw ||
                    Precision.equals(w, x)) {
                    v = w;
                    fv = fw;
                    w = u;
                    fw = fu;
                } else if (fu <= fv ||
                           Precision.equals(v, x) ||
                           Precision.equals(v, w)) {
                    v = u;
                    fv = fu;
                }
            }
        } else { // Default termination (Brent's criterion).
            return current;
        }
        ++iter;
    }
}

private void guessAOmega() {
    // initialize the sums for the linear model between the two integrals
    double sx2 = 0;
    double sy2 = 0;
    double sxy = 0;
    double sxz = 0;
    double syz = 0;

    double currentX = observations[0].getX();
    double currentY = observations[0].getY();
    double f2Integral = 0;
    double fPrime2Integral = 0;
    final double startX = currentX;
    for (int i = 1; i < observations.length; ++i) {
        // one step forward
        final double previousX = currentX;
        final double previousY = currentY;
        currentX = observations[i].getX();
        currentY = observations[i].getY();

        // update the integrals of f<sup>2</sup> and f'<sup>2</sup>
        // considering a linear model for f (and therefore constant f')
        final double dx = currentX - previousX;
        final double dy = currentY - previousY;
        final double f2StepIntegral =
            dx * (previousY * previousY + previousY * currentY + currentY * currentY) / 3;
        final double fPrime2StepIntegral = dy * dy / dx;

        final double x = currentX - startX;
        f2Integral += f2StepIntegral;
        fPrime2Integral += fPrime2StepIntegral;

        sx2 += x * x;
        sy2 += f2Integral * f2Integral;
        sxy += x * f2Integral;
        sxz += x * fPrime2Integral;
        syz += f2Integral * fPrime2Integral;
    }

    // compute the amplitude and pulsation coefficients
    double c1 = sy2 * sxz - sxy * syz;
    double c2 = sxy * sxz - sx2 * syz;
    double c3 = sx2 * sy2 - sxy * sxy;
    if ((c1 / c2 < 0) || (c2 / c3 < 0)) {
        final int last = observations.length - 1;
        // Range of the observations, assuming that the
        // observations are sorted.
        final double xRange = observations[last].getX() - observations[0].getX();
        if (xRange == 0) {
            throw new ZeroException();
        }
        omega = 2 * Math.PI / xRange;

        double yMin = Double.POSITIVE_INFINITY;
        double yMax = Double.NEGATIVE_INFINITY;
        for (int i = 1; i < observations.length; ++i) {
            final double y = observations[i].getY();
            if (y < yMin) {
                yMin = y;
            }
            if (y > yMax) {
                yMax = y;
            }
        }
        a = 0.5 * (yMax - yMin);
    } else {
        // In some ill-conditioned cases (cf. MATH-844), the guesser
        // procedure cannot produce sensible results.
        a = FastMath.sqrt(c1 / c2);
        omega = FastMath.sqrt(c2 / c3);
    }
}

