public double doubleValue() {
    BigInteger bigNumerator = this.numerator;
    BigInteger bigDenominator = this.denominator;
    int scale = Math.min(bigNumerator.bitLength(), bigDenominator.bitLength());
    BigInteger shiftedNumerator = bigNumerator.shiftRight(scale);
    BigInteger shiftedDenominator = bigDenominator.shiftRight(scale);
    double result = shiftedNumerator.doubleValue() / shiftedDenominator.doubleValue();
    return result;
}

public float floatValue() {
    BigInteger bigNumerator = this.numerator;
    BigInteger bigDenominator = this.denominator;
    int scale = Math.min(bigNumerator.bitLength(), bigDenominator.bitLength());
    BigInteger shiftedNumerator = bigNumerator.shiftRight(scale);
    BigInteger shiftedDenominator = bigDenominator.shiftRight(scale);
    float result = shiftedNumerator.floatValue() / shiftedDenominator.floatValue();
    return result;
}

public Complex tan() {
    if (isNaN) {
        return NaN;
    }

    double real2 = 2.0 * real;
    double imaginary2 = 2.0 * imaginary;
    double d = FastMath.cos(real2) + FastMath.cosh(imaginary2);

    if (Double.isInfinite(d)) {
        return createComplex(signum(real), 0.0);
    }

    return createComplex(FastMath.sin(real2) / d,
                         FastMath.sinh(imaginary2) / d);
}

public Complex tanh() {
    if (isNaN) {
        return NaN;
    }
    double real2 = 2.0 * real;
    double imaginary2 = 2.0 * imaginary;
    double d = FastMath.cosh(real2) + FastMath.cos(imaginary2);

    if (Double.isInfinite(d)) {
        return createComplex(signum(real), 0.0);
    }

    return createComplex(FastMath.sinh(real2) / d,
                         FastMath.sin(imaginary2) / d);
}

public double integrate(final ExpandableStatefulODE equations, final double t)
    throws MathIllegalStateException, MathIllegalArgumentException {

  sanityChecks(equations, t);
  setEquations(equations);
  final boolean forward = t > equations.getTime();

  // create some internal working arrays
  final double[] y0  = equations.getCompleteState();
  final double[] y = y0.clone();
  final int stages = c.length + 1;
  final double[][] yDotK = new double[stages][y.length];
  final double[] yTmp    = y0.clone();
  final double[] yDotTmp = new double[y.length];

  // set up an interpolator sharing the integrator arrays
  final RungeKuttaStepInterpolator interpolator = (RungeKuttaStepInterpolator) prototype.copy();
  interpolator.reinitialize(this, yTmp, yDotK, forward,
                            equations.getPrimaryMapper(), equations.getSecondaryMappers());
  interpolator.storeTime(equations.getTime());

  // set up integration control objects
  stepStart         = equations.getTime();
  double  hNew      = 0;
  boolean firstTime = true;
  initIntegration(equations.getTime(), y0, t);

  // main integration loop
  isLastStep = false;
  do {

    interpolator.shift();

    // iterate over step size, ensuring local normalized error is smaller than 1
    double error = 10;
    while (error >= 1.0) {

      if (firstTime || !fsal) {
        // first stage
        computeDerivatives(stepStart, y, yDotK[0]);
      }

      if (firstTime) {
        final double[] scale = new double[mainSetDimension];
        if (vecAbsoluteTolerance == null) {
            for (int i = 0; i < scale.length; ++i) {
              scale[i] = scalAbsoluteTolerance + scalRelativeTolerance * FastMath.abs(y[i]);
            }
        } else {
            for (int i = 0; i < scale.length; ++i) {
              scale[i] = vecAbsoluteTolerance[i] + vecRelativeTolerance[i] * FastMath.abs(y[i]);
            }
        }
        hNew = initializeStep(forward, getOrder(), scale,
                              stepStart, y, yDotK[0], yTmp, yDotK[1]);
        firstTime = false;
      }

      stepSize = hNew;

      // next stages
      for (int k = 1; k < stages; ++k) {

        for (int j = 0; j < y0.length; ++j) {
          double sum = a[k-1][0] * yDotK[0][j];
          for (int l = 1; l < k; ++l) {
            sum += a[k-1][l] * yDotK[l][j];
          }
          yTmp[j] = y[j] + stepSize * sum;
        }

        computeDerivatives(stepStart + c[k-1] * stepSize, yTmp, yDotK[k]);

      }

      // estimate the state at the end of the step
      for (int j = 0; j < y0.length; ++j) {
        double sum    = b[0] * yDotK[0][j];
        for (int l = 1; l < stages; ++l) {
          sum    += b[l] * yDotK[l][j];
        }
        yTmp[j] = y[j] + stepSize * sum;
      }

      // estimate the error at the end of the step
      error = estimateError(yDotK, y, yTmp, stepSize);
      if (error >= 1.0) {
        // reject the step and attempt to reduce error by stepsize control
        final double factor =
            FastMath.min(maxGrowth,
                         FastMath.max(minReduction, safety * FastMath.pow(error, exp)));
        hNew = filterStep(stepSize * factor, forward, false);
      }

    }

    // local error is small enough: accept the step, trigger events and step handlers
    interpolator.storeTime(stepStart + stepSize);
    System.arraycopy(yTmp, 0, y, 0, y0.length);
    System.arraycopy(yDotK[stages - 1], 0, yDotTmp, 0, y0.length);
    stepStart = acceptStep(interpolator, y, yDotTmp, t);
    System.arraycopy(y, 0, yTmp, 0, y.length);

    if (!isLastStep) {

        // prepare next step
        interpolator.storeTime(stepStart);

        if (fsal) {
            // save the last evaluation for the next step
            System.arraycopy(yDotTmp, 0, yDotK[0], 0, y0.length);
        }

        // stepsize control for next step
        final double factor =
            FastMath.min(maxGrowth, FastMath.max(minReduction, safety * FastMath.pow(error, exp)));
        final double  scaledH    = stepSize * factor;
        final double  nextT      = stepStart + scaledH;
        final boolean nextIsLast = forward ? (nextT >= t) : (nextT <= t);
        hNew = filterStep(scaledH, forward, nextIsLast);

        final double  filteredNextT      = stepStart + hNew;
        final boolean filteredNextIsLast = forward ? (filteredNextT >= t) : (filteredNextT <= t);
        if (filteredNextIsLast) {
            hNew = t - stepStart;
        }

    }

  } while (!isLastStep);

  // dispatch results
  equations.setTime(stepStart);
  equations.setCompleteState(y);

  resetInternalState();

}

protected double doSolve() {

    // prepare arrays with the first points
    final double[] x = new double[maximalOrder + 1];
    final double[] y = new double[maximalOrder + 1];
    x[0] = getMin();
    x[1] = getStartValue();
    x[2] = getMax();
    verifySequence(x[0], x[1], x[2]);

    // evaluate initial guess
    y[1] = computeObjectiveValue(x[1]);
    if (Precision.equals(y[1], 0.0, 1)) {
        // return the initial guess if it is a perfect root.
        return x[1];
    }

    // evaluate first  endpoint
    y[0] = computeObjectiveValue(x[0]);
    if (Precision.equals(y[0], 0.0, 1)) {
        // return the first endpoint if it is a perfect root.
        return x[0];
    }

    int nbPoints;
    int signChangeIndex;
    if (y[0] * y[1] < 0) {

        // reduce interval if it brackets the root
        nbPoints        = 2;
        signChangeIndex = 1;

    } else {

        // evaluate second endpoint
        y[2] = computeObjectiveValue(x[2]);
        if (Precision.equals(y[2], 0.0, 1)) {
            // return the second endpoint if it is a perfect root.
            return x[2];
        }

        if (y[1] * y[2] < 0) {
            // use all computed point as a start sampling array for solving
            nbPoints        = 3;
            signChangeIndex = 2;
        } else {
            throw new NoBracketingException(x[0], x[2], y[0], y[2]);
        }

    }

    // prepare a work array for inverse polynomial interpolation
    final double[] tmpX = new double[x.length];

    // current tightest bracketing of the root
    double xA    = x[signChangeIndex - 1];
    double yA    = y[signChangeIndex - 1];
    double absYA = FastMath.abs(yA);
    int agingA   = 0;
    double xB    = x[signChangeIndex];
    double yB    = y[signChangeIndex];
    double absYB = FastMath.abs(yB);
    int agingB   = 0;

    // search loop
    while (true) {

        // check convergence of bracketing interval
        final double xTol = getAbsoluteAccuracy() +
                            getRelativeAccuracy() * FastMath.max(FastMath.abs(xA), FastMath.abs(xB));
        if (((xB - xA) <= xTol) || (FastMath.max(absYA, absYB) < getFunctionValueAccuracy())) {
            switch (allowed) {
            case ANY_SIDE :
                return absYA < absYB ? xA : xB;
            case LEFT_SIDE :
                return xA;
            case RIGHT_SIDE :
                return xB;
            case BELOW_SIDE :
                return (yA <= 0) ? xA : xB;
            case ABOVE_SIDE :
                return (yA <  0) ? xB : xA;
            default :
                // this should never happen
                throw new MathInternalError(null);
            }
        }

        // target for the next evaluation point
        double targetY;
        if (agingA >= MAXIMAL_AGING) {
            // we keep updating the high bracket, try to compensate this
            targetY = -REDUCTION_FACTOR * yB;
        } else if (agingB >= MAXIMAL_AGING) {
            // we keep updating the low bracket, try to compensate this
            targetY = -REDUCTION_FACTOR * yA;
        } else {
            // bracketing is balanced, try to find the root itself
            targetY = 0;
        }

        // make a few attempts to guess a root,
        double nextX;
        int start = 0;
        int end   = nbPoints;
        do {

            // guess a value for current target, using inverse polynomial interpolation
            System.arraycopy(x, start, tmpX, start, end - start);
            nextX = guessX(targetY, tmpX, y, start, end);

            if (!((nextX > xA) && (nextX < xB))) {
                // the guessed root is not strictly inside of the tightest bracketing interval

                // the guessed root is either not strictly inside the interval or it
                // is a NaN (which occurs when some sampling points share the same y)
                // we try again with a lower interpolation order
                if (signChangeIndex - start >= end - signChangeIndex) {
                    // we have more points before the sign change, drop the lowest point
                    ++start;
                } else {
                    // we have more points after sign change, drop the highest point
                    --end;
                }

                // we need to do one more attempt
                nextX = Double.NaN;

            }

        } while (Double.isNaN(nextX) && (end - start > 1));

        if (Double.isNaN(nextX)) {
            // fall back to bisection
            nextX = xA + 0.5 * (xB - xA);
            start = signChangeIndex - 1;
            end   = signChangeIndex;
        }

        // evaluate the function at the guessed root
        final double nextY = computeObjectiveValue(nextX);
        if (Precision.equals(nextY, 0.0, 1)) {
            // we have found an exact root, since it is not an approximation
            // we don't need to bother about the allowed solutions setting
            return nextX;
        }

        if ((nbPoints > 2) && (end - start != nbPoints)) {

            // we have been forced to ignore some points to keep bracketing,
            // they are probably too far from the root, drop them from now on
            nbPoints = end - start;
            System.arraycopy(x, start, x, 0, nbPoints);
            System.arraycopy(y, start, y, 0, nbPoints);
            signChangeIndex -= start;

        } else  if (nbPoints == x.length) {

            // we have to drop one point in order to insert the new one
            nbPoints--;

            // keep the tightest bracketing interval as centered as possible
            if (signChangeIndex >= (x.length + 1) / 2) {
                // we drop the lowest point, we have to shift the arrays and the index
                System.arraycopy(x, 1, x, 0, nbPoints);
                System.arraycopy(y, 1, y, 0, nbPoints);
                --signChangeIndex;
            }

        }

        // insert the last computed point
        //(by construction, we know it lies inside the tightest bracketing interval)
        System.arraycopy(x, signChangeIndex, x, signChangeIndex + 1, nbPoints - signChangeIndex);
        x[signChangeIndex] = nextX;
        System.arraycopy(y, signChangeIndex, y, signChangeIndex + 1, nbPoints - signChangeIndex);
        y[signChangeIndex] = nextY;
        ++nbPoints;

        // update the bracketing interval
        if (nextY * yA <= 0) {
            // the sign change occurs before the inserted point
            xB = nextX;
            yB = nextY;
            absYB = FastMath.abs(yB);
            ++agingA;
            agingB = 0;
        } else {
            // the sign change occurs after the inserted point
            xA = nextX;
            yA = nextY;
            absYA = FastMath.abs(yA);
            agingA = 0;
            ++agingB;

            // update the sign change index
            signChangeIndex++;

        }

    }

}

public double evaluate(final double[] values, final double[] weights,
                       final double mean, final int begin, final int length) {

    double var = Double.NaN;

    if (test(values, weights, begin, length)) {
        if (length == 1) {
            var = 0.0;
        } else if (length > 1) {
            double accum = 0.0;
            double dev = 0.0;
            double accum2 = 0.0;
            for (int i = begin; i < begin + length; i++) {
                dev = values[i] - mean;
                accum += weights[i] * (dev * dev);
                accum2 += weights[i] * dev;
            }

            double sumWts = 0;
            for (int i = 0; i < weights.length; i++) {
                sumWts += weights[i];
            }

            if (isBiasCorrected) {
                var = (accum - (accum2 * accum2 / sumWts)) / (sumWts - 1.0);
            } else {
                var = (accum - (accum2 * accum2 / sumWts)) / sumWts;
            }
        }
    }
    return var;
}

