public static double distance(int[] p1, int[] p2) {
  if (p1 == null || p2 == null || p1.length != p2.length) {
      throw new IllegalArgumentException("Invalid input points");
  }
  int sum = 0;
  for (int i = 0; i < p1.length; i++) {
      final int dp = p1[i] - p2[i];
      sum += dp * dp;
  }
  return Math.sqrt(sum);
}

private boolean flipIfWarranted(final int n, final int step) {
    if (1.5 * work[pingPong] < work[4 * (n - 1) + pingPong]) {
        // flip array
        int j = 4 * n - 1;
        for (int i = 0; i < j; i += 4) {
            for (int k = 0; k < 4; k += step) {
                final double tmp = work[i + k];
                work[i + k] = work[j - k];
                work[j - k] = tmp;
            }
            j -= 4;
        }
        return true;
    }
    return false;
}

private void computeGershgorinCircles() {

    final int m     = main.length;
    final int lowerStart = 4 * m;
    final int upperStart = 5 * m;
    lowerSpectra = Double.POSITIVE_INFINITY;
    upperSpectra = Double.NEGATIVE_INFINITY;
    double eMax = 0;

    double eCurrent = 0;
    for (int i = 0; i < m - 1; ++i) {

        final double dCurrent = main[i];
        final double ePrevious = eCurrent;
        eCurrent = Math.abs(secondary[i]);
        eMax = Math.max(eMax, eCurrent);
        final double radius = ePrevious + eCurrent;

        final double lower = dCurrent - radius;
        if (lowerStart + i < work.length) {
            work[lowerStart + i] = lower;
        }
        lowerSpectra = Math.min(lowerSpectra, lower);

        final double upper = dCurrent + radius;
        if (upperStart + i < work.length) {
            work[upperStart + i] = upper;
        }
        upperSpectra = Math.max(upperSpectra, upper);

    }

    final double dCurrent = main[m - 1];
    final double lower = dCurrent - eCurrent;
    if (lowerStart + m - 1 < work.length) {
        work[lowerStart + m - 1] = lower;
    }
    lowerSpectra = Math.min(lowerSpectra, lower);
    final double upper = dCurrent + eCurrent;
    if (upperStart + m - 1 < work.length) {
        work[upperStart + m - 1] = upper;
    }
    minPivot = MathUtils.SAFE_MIN * Math.max(1.0, eMax * eMax);

}

private Integer getPivotRow(final int col, final SimplexTableau tableau) {
    double minRatio = Double.MAX_VALUE;
    Integer minRatioPos = null;
    for (int i = tableau.getNumObjectiveFunctions(); i < tableau.getHeight(); i++) {
        final double rhs = tableau.getEntry(i, tableau.getWidth() - 1);
        final double entry = tableau.getEntry(i, col);
        if (MathUtils.compareTo(entry, 0, epsilon) >= 0) {
            final double ratio = rhs / entry;
            if (ratio < minRatio) {
                minRatio = ratio;
                minRatioPos = i; 
            }
        }
    }
    return minRatioPos;
}

private Integer getBasicRow(final int col, boolean ignoreObjectiveRows) {
    Integer row = null;
    int start = getNumObjectiveFunctions();
    for (int i = start; i < getHeight(); i++) {
        if (MathUtils.equals(getEntry(i, col), 1.0, epsilon) && (row == null)) {
            row = i;
        } else if (!MathUtils.equals(getEntry(i, col), 0.0, epsilon)) {
            return null;
        }
    }
    return row;
}

protected RealPointValuePair getSolution() {
  double[] coefficients = new double[getOriginalNumDecisionVariables()];
  Integer negativeVarBasicRow = getBasicRow(getNegativeDecisionVariableOffset());
  double mostNegative = negativeVarBasicRow == null ? 0 : getEntry(negativeVarBasicRow, getRhsOffset());
  Set<Integer> basicRows = new HashSet<Integer>();
  for (int i = 0; i < coefficients.length; i++) {
      Integer basicRow = getBasicRow(getNumObjectiveFunctions() + i);
      if (basicRows.contains(basicRow)) {
          // if multiple variables can take a given value 
          // then we choose the first and set the rest equal to 0
          coefficients[i] = 0;
      } else {
          basicRows.add(basicRow);
          coefficients[i] =
              (basicRow == null ? 0 : getEntry(basicRow, getRhsOffset())) -
              (restrictToNonNegative ? 0 : mostNegative);
      }
  }
    return new RealPointValuePair(coefficients, f.getValue(coefficients));
}

/** {@inheritDoc} */
@Override
protected void iterateSimplex(final Comparator<RealPointValuePair> comparator)
    throws FunctionEvaluationException, OptimizationException, IllegalArgumentException {

    while (true) {

        incrementIterationsCounter();

        // save the original vertex
        final RealPointValuePair[] original = simplex;
        final RealPointValuePair best = original[0];

        // perform a reflection step
        final RealPointValuePair reflected = evaluateNewSimplex(original, 1.0, comparator);
        if (comparator.compare(reflected, best) < 0) {

            // compute the expanded simplex
            final RealPointValuePair[] reflectedSimplex = simplex;
            final RealPointValuePair expanded = evaluateNewSimplex(original, khi, comparator);
            if (comparator.compare(reflected, expanded) <= 0) {
                // accept the reflected simplex
                simplex = reflectedSimplex;
            } else {
                // reject the reflected simplex and contract
                final RealPointValuePair contracted = evaluateNewSimplex(original, gamma, comparator);
                if (comparator.compare(contracted, best) < 0) {
                    // accept the contracted simplex
                    simplex = new RealPointValuePair[]{best, contracted};
                }
            }

            return;

        }

        // check convergence
        if (converged(comparator)) {
            return;
        }

    }

}

